window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0177", [{"word":"banking system","ipa_uk":"/ˈbæŋkɪŋ ˌsɪstəm/","ipa_us":"/ˈbæŋkɪŋ ˌsɪstəm/","definition_zh":"银行体系；一国或一地区全部银行、监管机构与支付清算网络构成的整体安排","definition_en":"the whole set of banks, supervisors and payment networks through which a country holds, moves and lends money","core_image":"夜里，城市地下一条条管道把资金送到各处，所有阀门都按同一套规则开合","scene":"城市里的储户把工资存进街角的分行，各家银行再按统一规则调拨资金。The banking system moves money from savers to firms that need capital.","sceneCN":"这里 banking system 指「一国银行、监管与清算构成的整体」（第 1 个义项：全国银行网络与共同规则的整体）；句意为银行体系把资金从储蓄者手中转到需要资本的企业。图中可辨识物件：分行门面、管道状资金流、账本、监管印章。","pos":[{"tag":"n.","zh":"银行体系（可数；指多国体系时用复数 banking systems）"}],"collocations":[{"phrase":"a sound banking system","zh":"稳健的银行体系"},{"phrase":"reform the banking system","zh":"改革银行体系"},{"phrase":"the banking system collapses","zh":"银行体系崩溃"},{"phrase":"a two-tier banking system","zh":"双层银行体系"},{"phrase":"shadow banking system","zh":"影子银行体系"},{"phrase":"the integrity of the banking system","zh":"银行体系的健全性"}],"forms":[{"label":"复数","form":"banking systems"},{"label":"相关名词（银行）","form":"bank"},{"label":"相关名词（银行业）","form":"banking"},{"label":"相关名词（中央银行）","form":"central bank"},{"label":"相关说法（金融体系）","form":"financial system"}],"derivatives":[{"word":"bank","pos":"n.","zh":"银行"},{"word":"banker","pos":"n.","zh":"银行家"},{"word":"banking","pos":"n.","zh":"银行业；银行业务"},{"word":"system","pos":"n.","zh":"体系；系统"},{"word":"systemic","pos":"adj.","zh":"系统性的；波及整个体系的"},{"word":"systematically","pos":"adv.","zh":"系统地"}],"senses":[{"no":"01","title":"A country's network of banks","titleCN":"一国的银行网络","definition":"the full set of banks operating in a country or region and the links between them","definitionCN":"一国或一地区全部经营中的银行及其相互联系","example":"A modern banking system links thousands of branches.","exampleCN":"现代银行体系把数千家分行连接起来。","why":"banking names the business of banks and system names an organized whole, so the phrase first means the whole network.","whyCN":"banking 指银行的业务，system 指有组织的整体，因此这个短语首先指整个网络。"},{"no":"02","title":"The institutional arrangement","titleCN":"制度层面的安排","definition":"the rules, institutions and practices that let deposits be held and payments be made","definitionCN":"使存款得以保管、支付得以完成的规则、机构与惯例","example":"Deposit insurance is a pillar of the banking system.","exampleCN":"存款保险是银行体系的一根支柱。","why":"once the network is seen as an arrangement rather than a set of buildings, the phrase covers rules and guarantees as well.","whyCN":"一旦把网络看作一种安排而不是一组建筑，这个短语就也涵盖规则与保障。"},{"no":"03","title":"Clearing and settlement","titleCN":"清算与结算机制","definition":"the machinery that clears cheques and settles transfers between banks","definitionCN":"处理票据、在银行之间结清转账的机制","example":"The banking system clears most cheques overnight.","exampleCN":"银行体系在一夜之间清算大部分支票。","why":"the network works only because banks can settle claims with one another, so the plumbing takes the same name as the whole.","whyCN":"网络能运转，靠的是银行之间能结清债权，于是这套管道也用了与整体相同的名称。"},{"no":"04","title":"Supervision and regulation","titleCN":"监管层面","definition":"the supervisory side of the arrangement, including the central bank and the regulators","definitionCN":"这一安排中负责监督的一面，包括中央银行与监管机构","example":"The central bank supervises the banking system through regular audits.","exampleCN":"中央银行通过定期审计监督银行体系。","why":"a system implies control, so the regulators who keep it stable are treated as part of it.","whyCN":"体系意味着控制，因此维持其稳定的监管者也被视为体系的一部分。"},{"no":"05","title":"A particular model","titleCN":"某种特定的体系模式","definition":"a specific design of the arrangement, such as a two-tier or a universal model","definitionCN":"这一安排的具体设计，如双层模式或全能模式","example":"Hong Kong developed a two-tier banking system in the colonial period.","exampleCN":"香港在殖民时期发展出双层银行体系。","why":"since the whole can be designed in different ways, the phrase also names each design.","whyCN":"既然整体可以有不同设计，这个短语也用来指每一种设计。"},{"no":"06","title":"The central-bank layer","titleCN":"中央银行所在的那一层","definition":"the layer of money creation and lender-of-last-resort support provided by the central bank","definitionCN":"由中央银行提供货币创造与最后贷款人支持的那一层","example":"A currency board changed how the banking system created credit.","exampleCN":"货币发行局改变了银行体系创造信用的方式。","why":"the central bank sits at the top of the same network, so its layer is called the system too.","whyCN":"中央银行位于同一网络的顶端，因此它所在的那一层也被称为体系。"},{"no":"07","title":"Core software platform","titleCN":"银行的核心软件平台","definition":"the computer platform on which a bank runs its accounts, balances and transactions","definitionCN":"银行用来运行账户、余额与交易的计算机平台","example":"The bank's core banking system failed during the transfer.","exampleCN":"转账期间，这家银行的核心银行系统出了故障。","why":"banks now run the network in software, so the phrase was borrowed for the machine that performs the same job.","whyCN":"银行如今用软件运行这张网络，于是这个短语被借来指执行同一任务的机器。"},{"no":"08","title":"A power bloc, figuratively","titleCN":"抽象义：作为权力集团","definition":"the banks and their allies regarded as a bloc that shapes policy","definitionCN":"把银行及其盟友视为塑造政策的一个集团","example":"Critics say the banking system writes the tax rules it lives by.","exampleCN":"批评者说银行体系在替自己写它赖以生存的税则。","why":"the abstract sense treats the network as an actor with interests rather than as machinery.","whyCN":"抽象义把这个网络当作有利益诉求的行为者，而非机器。"}],"etymology":{"intro":{"en":"Banking system joins a word for the moneychanger's bench to a Greek word for an organized whole. The compound itself is modern. Dates are approximate.","cn":"banking system 把一个指钱商柜台的词与一个指有组织整体的希腊词并置，这个复合词本身出现较晚。年代均为约数。"},"items":[{"era":"ITALIAN BANCA","en":"Italian banca meant 'bench, table', especially the table of a moneychanger; Medieval Latin bancus recorded the same object.","cn":"意大利语 banca 意为「长凳、桌子」，尤其指钱商的桌子；中世纪拉丁 bancus 记录了同一物件。"},{"era":"ENGLISH BANK","en":"English bank for a financial house appears in the fifteenth century, taken through French and Italian from that bench; the bench became the business.","cn":"英语中指金融机构的 bank 于 15 世纪出现，经法语与意大利语来自那张桌子；桌子变成了生意。"},{"era":"GREEK SYSTEMA","en":"Greek systēma 'an organized whole' was built on syn- 'together' and histanai 'to set, stand'.","cn":"希腊 systēma「有组织的整体」由 syn-「一起」与 histanai「放置、站立」构成。"},{"era":"LATIN SYSTEMA","en":"Late Latin systema carried the Greek noun into learned use, and English system follows in the sixteenth century.","cn":"晚期拉丁 systema 把这个希腊名词带入学术用语，英语 system 于 16 世纪接上。"},{"era":"THE COMPOUND","en":"Banking as the business of banks is a seventeenth-century formation, and banking system as a fixed phrase belongs to the nineteenth century, when central banks and clearing houses spread.","cn":"banking 指银行业务是 17 世纪的形成物，而 banking system 作为固定说法属于 19 世纪，那时中央银行与票据交换所普及。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest printed use of the full phrase is not recorded here; the pre-Latin form of histanai is a reconstruction, and the Germanic bench behind banca is also reconstructed.","cn":"来源不确定（首见年代与更深词源）：完整短语的最早印刷用例此处无记录；histanai 在拉丁语之前的形式属重构形式，banca 背后那个表示长凳的日耳曼词亦属重构形式。"}]},"similar":{"note":{"en":"Group one holds look-alikes that share the letters bank but not one origin; group two holds names for neighbouring parts of the same financial world.","cn":"第一组是共用 bank 字样却来源不同的形近词；第二组是同一金融世界里邻近部分的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bank","ipa":"/bæŋk/","tag":"the bench that became a business","definition":"From the moneychanger's bench; it names the institution itself, not the whole arrangement around it.","definitionCN":"来自钱商的柜台，指机构本身，而不是围绕它的整套安排。"},{"word":"bank","ipa":"/bæŋk/","tag":"different origin, river edge","definition":"The land along a river comes from a Scandinavian word for a ridge or shoal and is unrelated to the financial word.","definitionCN":"河岸之义来自斯堪的纳维亚语表示土脊或浅滩的词，与金融义无关。"},{"word":"bankrupt","ipa":"/ˈbæŋkrʌpt/","tag":"broken bench","definition":"From Italian banca rotta 'broken bench', the image of a trader's table smashed when he could not pay.","definitionCN":"来自意大利语 banca rotta「断掉的柜台」，想象一个无力偿债者的桌子被砸碎。"},{"word":"bench","ipa":"/bentʃ/","tag":"the literal object","definition":"The ordinary seat is the same Germanic word that Italian borrowed for the moneychanger's table.","definitionCN":"普通的坐凳与意大利语借去指钱商桌子的那个日耳曼词是同一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"financial system","ipa":"/faɪˈnænʃl ˈsɪstəm/","tag":"wider than banks","definition":"It covers markets, insurers and pension funds as well, so it is broader than the banking system.","definitionCN":"它还涵盖市场、保险与养老基金，因此比银行体系更宽。"},{"word":"banking sector","ipa":"/ˈbæŋkɪŋ ˈsektə(r)/","tag":"the banks as an industry","definition":"It treats the banks as one industry or employer, not as a working network of rules and settlement.","definitionCN":"它把银行当作一个行业或雇主，而不是一套运转的规则与结算网络。"},{"word":"payment system","ipa":"/ˈpeɪmənt ˈsɪstəm/","tag":"only the plumbing","definition":"It names only the clearing and settlement layer, not the banks that hold deposits.","definitionCN":"它只指清算与结算这一层，不包括吸收存款的银行。"},{"word":"monetary system","ipa":"/ˈmʌnɪtri ˈsɪstəm/","tag":"the currency layer","definition":"It covers the currency and the central bank, leaving commercial banking aside.","definitionCN":"它涵盖货币与中央银行，把商业银行业务放在一边。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bank comes from the moneychanger's bench; system comes from Greek for a whole put together.","cn":"bank 来自钱商的柜台；system 来自希腊语「拼合起来的整体」。"},{"en":"The family runs bank, banker, banking, banking system and systemic.","cn":"同族包括 bank、banker、banking、banking system 与 systemic。"},{"en":"Fixed phrases mark the scale: a sound banking system, a two-tier banking system, shadow banking system.","cn":"固定搭配标出规模：稳健的银行体系、双层银行体系、影子银行体系。"},{"en":"The two-tier model separates licensed deposit banks from restricted institutions.","cn":"双层模式把持牌存款银行与受限机构分开。"},{"en":"The phrase also names software, as in core banking system.","cn":"这个短语也指软件，如核心银行系统。"}],"abstract":[{"en":"Picture pipes under a city that all obey a single valve rule.","cn":"想象城市地下所有管道都遵守同一套阀门规则。"},{"en":"Picture a bench where coins are counted, growing into a building with many windows.","cn":"想象一张数钱的桌子，长成一座有许多窗子的楼房。"},{"en":"Picture a row of lamps that go dark together when one switch fails.","cn":"想象一排灯，一个开关失灵就一起熄灭。"}]},"examples":[{"en":"A sound banking system turns small savings into long-term investment.","cn":"稳健的银行体系把零散储蓄变成长期投资。"},{"en":"The two-tier banking system kept small deposit houses out of risky lending.","cn":"双层银行体系让小存款机构无法从事高风险放贷。"},{"en":"Regulators tested whether the banking system could survive a sudden run.","cn":"监管者检验银行体系能否挺过一场突如其来的挤兑。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「银行 + 体系」——把存钱、放贷、清算连成一张网 → 银行体系","word":"banking system"},"root":"意大利 banca「钱商柜台」（中世纪拉丁 bancus）+ 希腊 systēma「有组织的整体」（syn-「一起」+ histanai「放置」）；banking system 为近代复合短语，两个成分来源不同。","sensesIntro":{"en":"Eight senses follow one structure: money is held, moved and lent inside a set of rules, and the same phrase is then applied to the rules, to single designs, to the central-bank layer, to software and finally to a political bloc.","cn":"八个义项沿同一个结构展开：资金在一套规则内被保管、调拨与贷出，这个短语再依次用于规则本身、单一设计、央行那一层、软件，最后用于一个政治集团。"},"semanticMap":{"core":{"en":"CORE IMAGE: pipes under a city carrying one flow of money, with every valve obeying the same rule.","cn":"核心意象：城市地下的管道运送同一种资金流，每个阀门都遵守同一条规则。"},"chain":["HOLD MONEY","MOVE MONEY","LEND MONEY","ENFORCE RULES","CHOOSE A MODEL","RUN AS SOFTWARE"],"branches":[{"senses":"01 · 02","en":"THE WHOLE NETWORK: a country's banks plus the arrangement that holds them together.","cn":"整个网络：一国的银行，加上把它们维系在一起的安排。"},{"senses":"03","en":"THE PLUMBING: clearing and settlement are the part that lets claims pass between banks.","cn":"管道：清算与结算让债权得以在银行之间流转。"},{"senses":"04","en":"THE RULES: supervisors count as part of the system because a system implies control.","cn":"规则：监管者被视为体系的一部分，因为体系意味着控制。"},{"senses":"05 · 06","en":"DESIGNS AND LAYERS: one phrase covers a chosen model and the central-bank layer above it.","cn":"设计与层次：同一个短语既指选定的模式，也指其上方的央行层。"},{"senses":"07 · 08","en":"OUTSIDE THE BUILDINGS: the same job done by software, and the same network seen as a political actor.","cn":"建筑之外：同样的工作由软件完成，同样的网络被看作政治行为者。"}]},"affixes":{"intro":{"en":"The phrase is a compound of free forms: a Germanic bench-word that became bank, a Greek noun of assembly, and the English suffix that names a trade.","cn":"这个短语是自由词形的复合：一个由日耳曼「长凳」词变成的 bank，一个希腊语表示组合整体的名词，以及一个英语中表示行业的后缀。"},"latinIntro":{"en":"Medieval Latin bancus and Greek systēma supply the two halves, with systema carrying the Greek noun into Latin.","cn":"中世纪拉丁 bancus 与希腊 systēma 提供前后两半，systema 把希腊名词带入拉丁语。"},"items":[{"word":"bank","structure":"Italian banca, Medieval Latin bancus (bench, moneychanger's table)","meaning":"bench; a financial house","meaningCN":"长凳；钱庄","example":"The old bench gave its name to the whole institution.","exampleCN":"那张旧柜台把名字给了整个机构。"},{"word":"-ing","structure":"Old English -ing (verbal noun suffix)","meaning":"the activity of doing something","meaningCN":"从事某类活动的行为","example":"Banking grew into a trade of its own.","exampleCN":"银行业发展成一门独立的行业。"},{"word":"system","structure":"Greek systēma via Late Latin systema","meaning":"an organized whole","meaningCN":"有组织的整体","example":"The system links every member bank.","exampleCN":"这个体系把每个成员银行连接起来。"},{"word":"syn-","structure":"Greek prefix syn- (together, with)","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix marks parts placed together.","exampleCN":"这个前缀表示各部分被放在一起。"},{"word":"histanai","structure":"Greek verb histanai (to set, stand)","meaning":"to set up, make stand","meaningCN":"使立起；安置","example":"The root carries the idea of setting something in place.","exampleCN":"这个词根带着把某物安置到位的意味。"},{"word":"banker","structure":"bank + -er (person who works with)","meaning":"a person who runs or works in a bank","meaningCN":"经营或从事银行业的人","example":"The banker approved the loan.","exampleCN":"银行家批准了这笔贷款。"},{"word":"banking","structure":"bank + -ing (activity)","meaning":"the business of banks","meaningCN":"银行业务","example":"Banking employs many graduates each year.","exampleCN":"银行业每年雇用许多毕业生。"},{"word":"systemic","structure":"system + -ic (relating to)","meaning":"affecting the whole system","meaningCN":"波及整个体系的","example":"A systemic shock spread through every bank.","exampleCN":"一次系统性冲击波及每一家银行。"},{"word":"systematically","structure":"systematic + -ally (in a manner)","meaning":"in an organized, methodical way","meaningCN":"有系统地","example":"The regulator systematically checked each branch.","exampleCN":"监管者系统地检查了每一家分行。"},{"word":"systematize","structure":"system + -atize (make into a system)","meaning":"to arrange according to a system","meaningCN":"使系统化","example":"The bank systematized its clearing rules.","exampleCN":"这家银行把清算规则系统化了。"}],"latinEntries":[{"word":"bancus","structure":"bancus, -i (m., second declension; Medieval Latin)","meaning":"bench, moneychanger's table","meaningCN":"长凳；钱商柜台"},{"word":"banca","structure":"banca, -ae (f., first declension; Medieval Latin from Italian)","meaning":"bench; bank","meaningCN":"长凳；银行"},{"word":"systema","structure":"systema, -atis (n., third declension; Late Latin from Greek)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"systēma","structure":"systēma, -atos (n., third declension; Greek)","meaning":"a whole put together","meaningCN":"被组合起来的整体"}]}},{"word":"account","ipa_uk":"/əˈkaʊnt/","ipa_us":"/əˈkaʊnt/","definition_zh":"账户；账目；叙述；解释；（动词）说明、认为","definition_en":"a record of money kept with a bank or in a ledger; also a report, an explanation, or to regard something in a certain way","core_image":"柜台后的厚账本，每一笔进出都落在同一页上，页边写着事由","scene":"分行职员把每一笔进出都记在同一个户头下，页边注明事由。At the end of the month she checked her account online.","sceneCN":"这里 account 指「银行账户」（第 1 个义项：银行记录客户资金的户头）；句意为月末她在网上核对自己的账户。图中可辨识物件：账本、柜台、手机上的账户页面、钢笔。","pos":[{"tag":"n.","zh":"账户；账目；叙述；说明"},{"tag":"v.","zh":"解释；说明（account for）；认为、视为"}],"collocations":[{"phrase":"open an account","zh":"开立账户"},{"phrase":"close an account","zh":"注销账户"},{"phrase":"a bank account","zh":"银行账户"},{"phrase":"account for","zh":"解释；占（某个比例）"},{"phrase":"on account of","zh":"因为；由于"},{"phrase":"take account of","zh":"考虑到"}],"forms":[{"label":"复数","form":"accounts"},{"label":"三单（he/she/it）","form":"accounts"},{"label":"过去式","form":"accounted"},{"label":"过去分词","form":"accounted"},{"label":"现在分词","form":"accounting"}],"derivatives":[{"word":"accountant","pos":"n.","zh":"会计；会计师"},{"word":"accounting","pos":"n.","zh":"会计；会计学"},{"word":"accountable","pos":"adj.","zh":"负有责任的；可解释的"},{"word":"accountability","pos":"n.","zh":"问责；责任"},{"word":"accountancy","pos":"n.","zh":"会计工作；会计职业"},{"word":"discount","pos":"n./v.","zh":"折扣；打折"}],"senses":[{"no":"01","title":"Money held at a bank","titleCN":"银行账户","definition":"an arrangement with a bank that holds a customer's money and records every payment and withdrawal","definitionCN":"与银行达成的安排，由银行保管客户资金并记录每一笔收支","example":"She opened an account at the branch on the corner.","exampleCN":"她在街角的分行开了一个账户。","why":"the oldest sense is a reckoning, and a bank reckoning of what a customer owns became the modern account.","whyCN":"最古老的意思是「结算」，银行对客户财物的结算就变成了现代意义上的账户。"},{"no":"02","title":"A record in a ledger","titleCN":"账簿上的账目","definition":"a separate record in a ledger that collects the money entries of one person, item or category","definitionCN":"账簿中单独的一笔记录，汇集某个人、某个项目或某类别的金额条目","example":"The clerk entered the sale in the wrong account.","exampleCN":"职员把这笔销售记进了错误的账目。","why":"a ledger is a set of reckonings kept side by side, so each column of entries is itself called an account.","whyCN":"账簿是一组并排保存的结算，因此每一列条目本身就被称为一个账目。"},{"no":"03","title":"A narrative report","titleCN":"叙述；描述","definition":"a spoken or written report of events in which they are described in order","definitionCN":"按顺序讲述事件的口头或书面报告","example":"Her account of the accident matched the video.","exampleCN":"她对事故的叙述与录像一致。","why":"telling a story is also a kind of reckoning: the events are counted out one by one.","whyCN":"讲故事也是一种结算：事件被一件件数出来。"},{"no":"04","title":"A user identity online","titleCN":"网络账号","definition":"a registered identity on a website or service, with a name, password and history","definitionCN":"在网站或服务上注册的身份，带有名称、密码与使用记录","example":"He deleted his account after the breach.","exampleCN":"泄露事件之后他注销了自己的账号。","why":"a digital account is a record of what a user has done, so the bookkeeping word was reused for it.","whyCN":"数字账号记录用户做过的事，于是这个记账词被再次借用。"},{"no":"05","title":"To explain a cause","titleCN":"解释；说明原因","definition":"to give a reason or explanation for something, often with for","definitionCN":"为某事给出理由或说明，常与 for 连用","example":"Managers must account for every delay.","exampleCN":"管理者必须为每一次延误作出解释。","why":"to account for something is to give the reckoning of it, that is, to show where it came from.","whyCN":"对某事作出交代，就是给出它的结算，也就是说明它从何而来。"},{"no":"06","title":"To regard as","titleCN":"认为；视为","definition":"to judge something to be a certain thing, as in account it a success","definitionCN":"判定某物为某种性质，如认为它是成功的","example":"The court accounted the delay reasonable.","exampleCN":"法院认为这一延误是合理的。","why":"the sense comes from putting a thing into a category in one's reckoning, that is, counting it as such.","whyCN":"这一义项来自把某物放进自己结算中的某一类，也就是把它算作某种东西。"},{"no":"07","title":"A business client relationship","titleCN":"客户关系；业务户","definition":"a customer or client that a firm serves and keeps a commercial record for","definitionCN":"企业服务并为其保存商业记录的客户","example":"The sales team protects its largest account.","exampleCN":"销售团队保护着它最大的客户。","why":"firms borrowed the bank's word because each client is a running record of orders and payments.","whyCN":"企业借用了银行的说法，因为每个客户都是一份订单与付款的连续记录。"},{"no":"08","title":"A final reckoning","titleCN":"清算；结账","definition":"a settling of money owed, especially at the end of a period of responsibility","definitionCN":"结清所欠款项，尤指在一段职责结束时","example":"The steward submitted his account at the end of the voyage.","exampleCN":"事务长在航行结束时提交了他的账目。","why":"this is the original sense kept alive in formal speech: to render an account is to hand over the reckoning.","whyCN":"这是保留在正式用语中的本义：交代账目就是把结算交出来。"}],"etymology":{"intro":{"en":"Account reaches English through Old French from Latin computare 'to reckon', a verb built on com- 'together' and putare. The money sense grew out of the reckoning sense. Dates are approximate.","cn":"account 经古法语来自拉丁 computare「计算、结算」，该动词由 com-「一起」与 putare 构成。金钱义由结算义发展而来。年代均为约数。"},"items":[{"era":"LATIN PUTARE","en":"Putare is recorded in the sense 'to prune, trim' and also 'to reckon, consider'. The reckoning sense is generally explained as clearing an account the way a vine is cleared, but that link is a hypothesis.","cn":"putare 有「修剪」与「计算、考虑」两种记录在案的用法；「计算」义一般解释为像修剪藤蔓那样把账目理清，但这一联系只是假说。"},{"era":"LATIN COMPUTARE","en":"Com- 'together' plus putare gave computare 'to reckon together, calculate', the source of count, compute and account.","cn":"com-「一起」加 putare 构成 computare「合起来算、计算」，是 count、compute 与 account 的来源。"},{"era":"OLD FRENCH ACONT","en":"Old French acont, later compte, meant 'reckoning, settlement'; its first element is a reduced form of the Latin preposition ad 'to'.","cn":"古法语 acont（后作 compte）意为「结算、清算」，其首元素是拉丁介词 ad「向」的弱化形式。"},{"era":"MIDDLE ENGLISH","en":"Middle English took the word as account, first for a reckoning of money and for a story told in order.","cn":"中世纪英语把这个词吸收为 account，最初既指金钱结算，也指按顺序讲出的叙述。"},{"era":"BANKING SENSE","en":"The modern bank account, a running record of a customer's money, is established by the eighteenth century as banking houses kept individual ledgers.","cn":"现代意义上的银行账户，即客户资金的连续记录，在 18 世纪随着银行各自保存客户账簿而确立。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the exact date of the banking sense is unsettled, the 'prune' reading of putare rests on a limited record, and the pre-Latin origin of putare is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：银行义的准确年代无定论，putare 的「修剪」读解依据有限，putare 在拉丁语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms built on the same counting stem, including prefixes that change the meaning; group two holds words for neighbouring records and reports.","cn":"第一组是同出「计算」词干的形式，包括改变词义的前缀；第二组是邻近的记录与报告类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"count","ipa":"/kaʊnt/","tag":"the bare verb","definition":"The same Latin computare without the French prefix: to say numbers in order or to matter.","definitionCN":"同一个拉丁 computare，去掉法语前缀：按顺序数数，或表示「算得上」。"},{"word":"discount","ipa":"/ˈdɪskaʊnt/","tag":"count down","definition":"Dis- 'away' plus count: to take an amount off a price, or to dismiss something as not worth considering.","definitionCN":"dis-「去掉」加 count：从价格中减去一笔，或认为某事不值得考虑。"},{"word":"recount","ipa":"/rɪˈkaʊnt/","tag":"count again or tell","definition":"Re- 'again' plus count: to count again, and separately to tell a story in detail.","definitionCN":"re-「再」加 count：重新计数；另有详细讲述之意。"},{"word":"accountable","ipa":"/əˈkaʊntəbl/","tag":"required to explain","definition":"account + -able: required to give a reckoning of one's actions to someone.","definitionCN":"account 加 -able：必须向某人交代自己行为的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bill","ipa":"/bɪl/","tag":"a demand for payment","definition":"A statement of money owed for goods or services; narrower than account, which also holds prepaid money.","definitionCN":"对已供货物或服务索款的单据；比 account 窄，后者也可存放预付款。"},{"word":"invoice","ipa":"/ˈɪnvɔɪs/","tag":"a commercial document","definition":"A formal list of goods shipped and money due, sent by a seller to a buyer.","definitionCN":"卖方给买方开具的正式单据，列明所供货物与应付款项。"},{"word":"ledger","ipa":"/ˈledʒə(r)/","tag":"the book itself","definition":"The book or file in which accounts are kept; an account is one line or section inside it.","definitionCN":"保存账目的账簿或文件；account 是其中一行或一节。"},{"word":"report","ipa":"/rɪˈpɔːt/","tag":"a formal telling","definition":"A formal statement of facts; it overlaps with the narrative sense but carries no reckoning of money.","definitionCN":"对事实的正式陈述；与叙述义重叠，但不含金钱结算之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"com- 'together' + putare 'reckon': to add things up together, hence a reckoning with a bank.","cn":"com-「一起」+ putare「计算」：把各项合起来算，因此是与银行的一笔结算。"},{"en":"The family runs account, accountant, accounting, accountable, accountability, accountancy.","cn":"同族包括 account、accountant、accounting、accountable、accountability、accountancy。"},{"en":"Fixed phrases: open an account, account for, on account of, take account of.","cn":"固定搭配：开立账户、解释、因为、考虑到。"},{"en":"A bank account and a written account of a trip use the same idea: events or money set down in order.","cn":"银行账户与一篇旅行记述用的是同一个想法：把金钱或事件按顺序记下来。"},{"en":"Accounting is the trade that keeps the accounts of a firm.","cn":"会计就是为企业保存账目的行业。"}],"abstract":[{"en":"Picture a page ruled into columns, one column for money and one for words.","cn":"想象一页画成栏的纸，一栏记钱，一栏记话。"},{"en":"Picture an account as a jar that must be emptied and counted before a journey ends.","cn":"想象账户是一只罐子，旅程结束前必须倒空并清点。"},{"en":"Picture a person who must hand over a notebook of reasons for every hour spent.","cn":"想象一个人必须交出笔记本，为花掉的每个小时写明理由。"}]},"examples":[{"en":"The firm holds three accounts with the same bank.","cn":"这家公司在同一家银行有三个账户。"},{"en":"Her account of the meeting was shorter than the minutes.","cn":"她对会议的叙述比会议记录短。"},{"en":"Rising fuel costs account for half of the price increase.","cn":"燃料成本上涨解释了价格涨幅的一半。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ac（去）+ count（数）」——去银行把钱数清记上 → 账户、账目；把事情数清楚 → 解释","word":"account"},"root":"拉丁 computare「合起来计算」= com-（一起）+ putare「计算、考虑」；经古法语 acont 进入英语。putare 的「修剪」义与「计算」义之间的联系仅为假说，其更早来源不确定。","sensesIntro":{"en":"Eight senses follow one act: setting things down in order, whether coins, entries, events or reasons, and the same word then covers the record, the story, the explanation and the final settling.","cn":"八个义项沿同一个动作展开：把金钱、条目、事件或理由按顺序记下；同一个词再依次指记录、叙述、解释与最后的清算。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruled page where every entry is counted and set in its column.","cn":"核心意象：一页画好栏线的纸，每一笔都被数清并放进对应栏中。"},"chain":["RECKON","RECORD","HOLD MONEY","TELL A STORY","EXPLAIN A CAUSE","SETTLE A CLAIM"],"branches":[{"senses":"01 · 02","en":"MONEY SET DOWN: a bank holds the record, and a ledger keeps one column of it.","cn":"记下的钱：银行保存记录，账簿保存其中的一栏。"},{"senses":"03","en":"EVENTS SET DOWN: a story is a reckoning of what happened, told in order.","cn":"记下的事件：故事就是对发生之事的结算，按顺序讲出。"},{"senses":"04","en":"IDENTITY SET DOWN: an online account is a running record of what a user did.","cn":"记下的身份：网络账号是用户所作所为的连续记录。"},{"senses":"05 · 08","en":"GIVING THE RECKONING: explaining a cause and settling a debt are both handing over the account.","cn":"交出结算：解释原因与结清欠款都是把账交出来。"},{"senses":"06 · 07","en":"COUNTING SOMETHING AS: judging a thing to be so, and treating a client as a running record of trade.","cn":"把某物算作：判定某物为某种性质，以及把客户当作一份连续的生意记录。"}]},"affixes":{"intro":{"en":"Account is a Latin verb of reckoning wearing a French prefix; its stem also builds count, discount and recount, so the family can be read morpheme by morpheme.","cn":"account 是一个带法语前缀的拉丁「计算」动词；同一词干还构成 count、discount 与 recount，因此这个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin putare and computare give account, count, compute and discount, while ratio supplies the unrelated Latin noun for a reckoning.","cn":"拉丁 putare 与 computare 衍生 account、count、compute 与 discount；ratio 则是拉丁语中表示结算的另一个名词，与它们不同源。"},"items":[{"word":"ac-","structure":"ad- (Latin prefix 'to, toward', assimilated to ac-)","meaning":"to; toward","meaningCN":"向；朝","example":"The prefix turns counting into counting up to a person.","exampleCN":"这个前缀把「数」变成「向某人交代」。"},{"word":"putare","structure":"putare (Latin verb, first conjugation)","meaning":"to reckon, consider; also to prune","meaningCN":"计算；考虑；亦指修剪","example":"The root supplies the idea of reckoning.","exampleCN":"这个词根提供「计算」的意思。"},{"word":"count","structure":"Latin computare through Old French conter","meaning":"to number; to matter","meaningCN":"计数；算得上","example":"Count the coins before you leave.","exampleCN":"离开前把硬币数清。"},{"word":"account","structure":"ad- + count (a reckoning)","meaning":"a record; an explanation","meaningCN":"记录；解释","example":"She gave a full account of the loss.","exampleCN":"她对损失作了完整说明。"},{"word":"accountant","structure":"account + -ant (person who does)","meaning":"a person who keeps and audits accounts","meaningCN":"记账与查账的人","example":"The accountant closed the books for the year.","exampleCN":"会计结清了这一年的账。"},{"word":"accounting","structure":"account + -ing (activity)","meaning":"the work of keeping financial records","meaningCN":"保存财务记录的工作","example":"Accounting follows strict rules.","exampleCN":"会计工作遵循严格的规则。"},{"word":"accountable","structure":"account + -able (required to)","meaning":"required to explain one's actions","meaningCN":"必须交代自己行为的","example":"Officials are accountable to the public.","exampleCN":"官员须向公众负责。"},{"word":"accountability","structure":"accountable + -ity (state of)","meaning":"the state of being required to explain","meaningCN":"须作交代的状态；问责","example":"The audit strengthened accountability.","exampleCN":"这次审计加强了问责。"},{"word":"accountancy","structure":"accountant + -cy (practice or profession)","meaning":"the profession of accounting","meaningCN":"会计职业","example":"She trained in accountancy before banking.","exampleCN":"她在进入银行业前受过会计训练。"},{"word":"discount","structure":"dis- (away) + count","meaning":"to take an amount off; a reduction","meaningCN":"减去一笔；折扣","example":"The shop discounted the damaged stock.","exampleCN":"商店给受损存货打了折。"}],"latinEntries":[{"word":"putare","structure":"putare, putavi, putatum (verb, first conjugation)","meaning":"to reckon, think; to prune","meaningCN":"计算；认为；修剪"},{"word":"computare","structure":"computare, computavi, computatum (verb, first conjugation)","meaning":"to reckon together, calculate","meaningCN":"合起来计算"},{"word":"computus","structure":"computus, -i (m., second declension)","meaning":"a calculation, reckoning","meaningCN":"计算；结算"},{"word":"ratio","structure":"ratio, rationis (f., third declension)","meaning":"a reckoning, account, reason","meaningCN":"结算；账目；理性"}]}},{"word":"bank account","ipa_uk":"/ˈbæŋk əˌkaʊnt/","ipa_us":"/ˈbæŋk əˌkaʊnt/","definition_zh":"银行账户；客户在银行开立、用于存放资金并记录收支的户头","definition_en":"an arrangement with a bank that holds a customer's money and records payments, withdrawals and interest","core_image":"一只写着名字的抽屉，钱进钱出都在抽屉旁的小本上留下痕迹","scene":"开学前，新生在分行填好表格，把生活费交给柜台。Every student needs a bank account before the scholarship arrives.","sceneCN":"这里 bank account 指「在银行开立的存款户头」（第 1 个义项：银行代为保管资金的账户安排）；句意为每个学生在奖学金到账前都需要一个银行账户。图中可辨识物件：开户表格、存折、柜台、缴费通知单。","pos":[{"tag":"n.","zh":"银行账户（可数）"}],"collocations":[{"phrase":"open a bank account","zh":"开立银行账户"},{"phrase":"a joint bank account","zh":"联名银行账户"},{"phrase":"a savings bank account","zh":"储蓄账户"},{"phrase":"a frozen bank account","zh":"被冻结的银行账户"},{"phrase":"a bank account number","zh":"银行账号"},{"phrase":"close a bank account","zh":"注销银行账户"}],"forms":[{"label":"复数","form":"bank accounts"},{"label":"相关说法（活期账户）","form":"current account"},{"label":"相关说法（储蓄账户）","form":"savings account"},{"label":"相关名词（账户持有人）","form":"account holder"},{"label":"相关名词（银行）","form":"bank"}],"derivatives":[{"word":"bank","pos":"n.","zh":"银行"},{"word":"account","pos":"n.","zh":"账户；账目"},{"word":"accountant","pos":"n.","zh":"会计"},{"word":"accounting","pos":"n.","zh":"会计；会计学"},{"word":"accountancy","pos":"n.","zh":"会计职业"},{"word":"banking","pos":"n.","zh":"银行业"}],"senses":[{"no":"01","title":"The arrangement with a bank","titleCN":"与银行订立的账户安排","definition":"an agreement under which a bank keeps a customer's money and records every movement of it","definitionCN":"银行保管客户资金并记录其每一笔变动的约定","example":"Every student needs a bank account before the scholarship arrives.","exampleCN":"每个学生在奖学金到账前都需要一个银行账户。","why":"bank names the institution and account names the reckoning it keeps for one customer, so the phrase is the record plus the promise to keep it.","whyCN":"bank 指机构，account 指它为某个客户保存的结算，因此这个短语是记录加上保存记录的承诺。"},{"no":"02","title":"The money on deposit","titleCN":"账户里的钱","definition":"the balance actually held in such an arrangement at a given moment","definitionCN":"某一时刻该安排中实际存放的余额","example":"The bank account holds barely enough for the rent.","exampleCN":"这个银行账户里的钱几乎只够付房租。","why":"people name the container for what it contains, so the account came to mean the money inside it.","whyCN":"人们常用容器指代其中的内容，于是账户也指其中的钱。"},{"no":"03","title":"A product type","titleCN":"账户产品类型","definition":"one of the standard products a bank sells, such as a savings or a current account","definitionCN":"银行出售的标准产品之一，如储蓄账户或活期账户","example":"A savings account pays a little interest each month.","exampleCN":"储蓄账户每月支付少量利息。","why":"once banks offered several designs, the phrase began to name each product rather than any one arrangement.","whyCN":"当银行提供多种设计后，这个短语开始指每一种产品，而不只是某一项安排。"},{"no":"04","title":"The identifying number","titleCN":"账号标识","definition":"the number or code that identifies one such arrangement in a payment system","definitionCN":"在支付系统中标识某项账户安排的号码或代码","example":"Write the bank account on the transfer form.","exampleCN":"把银行账号写在转账单上。","why":"in a network each account must be findable, so the word is used for its address as well as for the thing addressed.","whyCN":"在网络中每个账户都必须能被找到，于是这个词既指账户本身，也指它的地址。"},{"no":"05","title":"A shared account","titleCN":"共有或联名账户","definition":"an account held jointly by two or more people who can all draw on it","definitionCN":"由两人或多人共同持有、各自都可支取的账户","example":"The couple keeps a joint bank account for rent.","exampleCN":"这对夫妇为付房租保留了一个联名银行账户。","why":"the arrangement can be held by more than one person, and joint ownership is named by prefixing the phrase rather than by changing it.","whyCN":"这种安排可以由不止一人持有，共有关系通过在短语前加修饰词表示，而不改变短语本身。"},{"no":"06","title":"An earmarked account","titleCN":"专款专用的账户","definition":"an account opened by an organization or a person to keep one purpose's money separate","definitionCN":"组织或个人为把某一用途的资金分开保存而开立的账户","example":"The charity opened a separate bank account for donations.","exampleCN":"这家慈善机构为捐款单独开了一个银行账户。","why":"separating money by purpose is the accounting habit that gave each column its own account, applied inside a bank.","whyCN":"按用途分钱是会计的老习惯，让每一栏各有一个账目，这一习惯被搬进了银行。"},{"no":"07","title":"A digital account record","titleCN":"数字化账户记录","definition":"the online view of the arrangement, where balances and transactions appear as data","definitionCN":"该安排在网络上的视图，余额与交易以数据形式呈现","example":"Her bank account was frozen while the bank checked the transfer.","exampleCN":"银行核查这笔转账期间，她的银行账户被冻结了。","why":"the same record now lives in software, but the phrase stayed with the record rather than with the ledger.","whyCN":"同一份记录如今存于软件之中，但短语仍跟着记录走，而不是跟着账簿走。"},{"no":"08","title":"A reserve of trust, figuratively","titleCN":"抽象义：信任的储备","definition":"a store of goodwill or credibility that a person can draw on later","definitionCN":"一个人日后可以动用的善意或信誉储备","example":"Goodwill is a bank account you draw on in hard times.","exampleCN":"善意是一个在艰难时能取用的银行账户。","why":"the metaphor treat trust as money: it can be deposited by good acts and withdrawn when help is needed.","whyCN":"这个比喻把信任当作金钱：善举是存入，需要帮助时是支取。"}],"etymology":{"intro":{"en":"Bank account pairs the moneychanger's bench with a Latin reckoning. The two words met in English banking in the eighteenth century. Dates are approximate.","cn":"bank account 把「钱商柜台」与一个拉丁「结算」词并置。两个词在 18 世纪的英格兰银行业相遇。年代均为约数。"},"items":[{"era":"ITALIAN BANK","en":"Bank came into English through French and Italian from banca, the bench where a moneychanger counted coins.","cn":"bank 经法语与意大利语进入英语，源自 banca，即钱商数钱的柜台。"},{"era":"LATIN COMPUTARE","en":"Account descends from computare 'to reckon together', built on com- and putare, and reached English through Old French acont.","cn":"account 来自 computare「合起来计算」，由 com- 与 putare 构成，经古法语 acont 进入英语。"},{"era":"EIGHTEENTH-CENTURY BANKING","en":"As London banks kept a separate ledger page for each customer, the page was called the customer's account, and the phrase bank account followed.","cn":"当伦敦的银行替每位客户保存单独的账簿页时，这一页被称为客户的 account，bank account 这一短语随之出现。"},{"era":"PRODUCTS AND NUMBERS","en":"Savings banks in the nineteenth century turned the account into a product, and cheque clearing gave it a number.","cn":"19 世纪的储蓄银行把账户变成一种产品，支票清算又给了它一个号码。"},{"era":"DIGITAL RECORD","en":"From the later twentieth century the account has been a database record, though the older ledger vocabulary survives in statements and passbooks.","cn":"从 20 世纪后期起，账户成为数据库中的记录，但旧账簿词汇仍留在对账单与存折上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and both banca and putare rest on reconstructed earlier forms.","cn":"来源不确定（首见年代与更深词源）：这一确切短语的最早用例没有定论，banca 与 putare 的早期形式都属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms that look close because they share the stem account; group two holds documents and figures that sit beside a real bank account.","cn":"第一组是因共用 account 词干而形近的形式；第二组是与真实银行账户配套出现的单据与数字。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"account","ipa":"/əˈkaʊnt/","tag":"the bare record","definition":"The single word can mean any account, including a story or an explanation; the compound narrows it to a bank.","definitionCN":"单词本身可指任何账目，包括叙述或解释；复合短语把它收窄到银行。"},{"word":"accountant","ipa":"/əˈkaʊntənt/","tag":"the person","definition":"The person who keeps and checks accounts, not the record itself.","definitionCN":"保存与核查账目的人，不是记录本身。"},{"word":"accountancy","ipa":"/əˈkaʊntənsi/","tag":"the profession","definition":"The profession of keeping accounts, which looks close but names work rather than a record.","definitionCN":"保存账目的职业，字形相近但指工作而非记录。"},{"word":"bank statement","ipa":"/bæŋk ˈsteɪtmənt/","tag":"the monthly paper","definition":"A periodic list a bank sends, showing what moved in the account; it is not the account itself.","definitionCN":"银行定期寄出的清单，列出账户内的资金变动；它不是账户本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bank balance","ipa":"/bæŋk ˈbæləns/","tag":"the figure","definition":"The amount standing in the account at one moment, as opposed to the arrangement that holds it.","definitionCN":"某一时刻账户中的金额，与持有它的安排相对。"},{"word":"deposit account","ipa":"/dɪˈpɒzɪt əˈkaʊnt/","tag":"a bank product","definition":"A type of account that pays interest and restricts withdrawals, a narrower label than bank account.","definitionCN":"付息并限制支取的账户类型，是比 bank account 更窄的标签。"},{"word":"current account","ipa":"/ˈkʌrənt əˈkaʊnt/","tag":"everyday banking","definition":"The account used for daily payments, called a checking account in American English.","definitionCN":"用于日常支付的账户，美式英语称 checking account。"},{"word":"safe deposit box","ipa":"/seɪf dɪˈpɒzɪt bɒks/","tag":"storage, not money","definition":"A locked box in a vault for valuables; it resembles an account in function but holds objects.","definitionCN":"金库中存放贵重物品的锁箱；功能上与账户相似，但存的是物件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bank comes from the moneychanger's bench; account comes from a Latin verb of reckoning.","cn":"bank 来自钱商柜台；account 来自一个拉丁「计算」动词。"},{"en":"The family runs bank, account, accountant, accounting, accountancy and banking.","cn":"同族包括 bank、account、accountant、accounting、accountancy 与 banking。"},{"en":"Fixed phrases: open a bank account, a joint bank account, a frozen bank account.","cn":"固定搭配：开立银行账户、联名银行账户、被冻结的银行账户。"},{"en":"The same record is called an account in Britain and often a bank account in full on forms.","cn":"同一份记录在英国简称 account，在表格上常写全为 bank account。"},{"en":"A statement reports the account; it is not the account.","cn":"对账单是报告账户情况，它本身不是账户。"}],"abstract":[{"en":"Picture a drawer with a name on it and a small notebook lying open beside it.","cn":"想象一只写着名字的抽屉，旁边摊开一本小本子。"},{"en":"Picture a jar of trust that fills with each favour and empties when help is asked.","cn":"想象一只信任的罐子，每次帮忙就装满一点，求助时就倒出一些。"},{"en":"Picture one page in a huge book, kept for you alone.","cn":"想象一本巨书中单独为你保存的一页。"}]},"examples":[{"en":"The branch opened her bank account in twenty minutes.","cn":"分行在二十分钟内为她开好了银行账户。"},{"en":"A joint bank account lets either partner pay the bills.","cn":"联名银行账户让伴侣任何一方都能付账。"},{"en":"He emptied the bank account before the trip.","cn":"出发前他取空了银行账户里的钱。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「银行 + 账户」——银行替你记账的那一页 → 银行账户","word":"bank account"},"root":"意大利 banca「钱商柜台」（中世纪拉丁 bancus）+ 拉丁 computare「合起来计算」（com- + putare）；两个成分经法语进入英语，18 世纪在银行业合成这一短语。","sensesIntro":{"en":"Eight senses follow one record: a bank keeps a page for a customer, and that page is then named for the money on it, the product it belongs to, its number, its shared or earmarked form, its digital image and finally a store of trust.","cn":"八个义项沿同一份记录展开：银行替客户保存一页，这一页再依次指其中的钱、所属的产品、它的号码、共有或专用的形式、数字映像，最后指一种信任储备。"},"semanticMap":{"core":{"en":"CORE IMAGE: one named page in a bank's ledger, with money entering and leaving beside it.","cn":"核心意象：银行账簿中写着名字的一页，钱在它旁边进出。"},"chain":["PROMISE","RECORD","BALANCE","PRODUCT","IDENTIFIER","TRUST STORE"],"branches":[{"senses":"01","en":"THE PROMISE: the bank undertakes to keep the money and keep the page.","cn":"承诺：银行承担保管资金与保存这一页的责任。"},{"senses":"02 · 07","en":"THE CONTENT: the money inside the record, whether seen in a passbook or on a screen.","cn":"内容：记录中的钱，无论看在存折上还是屏幕上。"},{"senses":"03","en":"THE PRODUCT: banks sell several standard designs, and each one gets the name.","cn":"产品：银行出售几种标准设计，每一种都得到这个名称。"},{"senses":"04 · 05","en":"THE ADDRESS AND THE SHARERS: a number finds it, and a joint name shares it.","cn":"地址与共有人：号码找到它，联名共享它。"},{"senses":"06 · 08","en":"SETTING MONEY APART: earmarking a purpose and storing goodwill are the same gesture outside banking.","cn":"把钱分开：为用途专款专用与储存善意，是银行之外的同一种动作。"}]},"affixes":{"intro":{"en":"This compound joins a Germanic bench-word turned bank to a Latin reckoning; neither half is a prefix or suffix, so the reading is two free forms plus their endings.","cn":"这个复合词把一个由日耳曼「长凳」词变成的 bank 接在一个拉丁「结算」词上；两半都不是前缀或后缀，因此读法是两个自由词形加各自的词尾。"},"latinIntro":{"en":"Latin computare and putare underlie account, count and discount; Medieval Latin bancus supplies bank.","cn":"拉丁 computare 与 putare 构成 account、count 与 discount 的基础；中世纪拉丁 bancus 提供 bank。"},"items":[{"word":"bank","structure":"Italian banca, Medieval Latin bancus (bench)","meaning":"a financial house","meaningCN":"金融机构；银行","example":"The bank occupies the corner building.","exampleCN":"这家银行占用街角的建筑。"},{"word":"account","structure":"ad- + count, from Latin computare","meaning":"a reckoning; a record","meaningCN":"结算；记录","example":"The account grows every month.","exampleCN":"这个账户每月增长。"},{"word":"count","structure":"Latin computare via Old French","meaning":"to number","meaningCN":"计数","example":"Tellers count the notes twice.","exampleCN":"出纳把钞票数两遍。"},{"word":"putare","structure":"Latin verb putare (to reckon)","meaning":"to reckon, consider","meaningCN":"计算；认为","example":"The root carries the act of reckoning.","exampleCN":"这个词根带着结算的动作。"},{"word":"accountant","structure":"account + -ant (person)","meaning":"one who keeps accounts","meaningCN":"记账的人","example":"The accountant signed the report.","exampleCN":"会计在报告上签了字。"},{"word":"accounting","structure":"account + -ing (activity)","meaning":"the work of keeping records","meaningCN":"记账工作","example":"Accounting exposes any gap.","exampleCN":"会计记录会暴露任何缺口。"},{"word":"accountancy","structure":"accountant + -cy (profession)","meaning":"the accounting profession","meaningCN":"会计职业","example":"Accountancy is a regulated profession.","exampleCN":"会计是一门受监管的职业。"},{"word":"accountable","structure":"account + -able (required to)","meaning":"required to explain","meaningCN":"须作出交代的","example":"The branch manager is accountable for the loss.","exampleCN":"分行经理须为这笔损失负责。"},{"word":"banking","structure":"bank + -ing (activity)","meaning":"the business of banks","meaningCN":"银行业务","example":"Banking moved online within a decade.","exampleCN":"银行业在十年内转向线上。"},{"word":"discount","structure":"dis- (away) + count","meaning":"a reduction in price","meaningCN":"价格上的减免","example":"The bank offered a discount on fees.","exampleCN":"银行在手续费上给了折扣。"}],"latinEntries":[{"word":"bancus","structure":"bancus, -i (m., second declension; Medieval Latin)","meaning":"bench, moneychanger's table","meaningCN":"长凳；钱商柜台"},{"word":"computare","structure":"computare, computavi, computatum (verb, first conjugation)","meaning":"to reckon together","meaningCN":"合起来计算"},{"word":"putare","structure":"putare, putavi, putatum (verb, first conjugation)","meaning":"to reckon; to prune","meaningCN":"计算；修剪"},{"word":"computus","structure":"computus, -i (m., second declension)","meaning":"a reckoning","meaningCN":"结算；账目"}]}},{"word":"depositor","ipa_uk":"/dɪˈpɒzɪtə(r)/","ipa_us":"/dɪˈpɑːzɪtər/","definition_zh":"存款人；存放者；（法律）寄托人；提交文件的人","definition_en":"a person or firm that puts money into a bank or entrusts something to another for safekeeping","core_image":"柜台前伸出的手把一只信封推入窗口，窗口后的人在册子上写下名字","scene":"一位老人把装着积蓄的信封推到柜台窗口，职员在册子上记下姓名。The depositor asked for a receipt before leaving.","sceneCN":"这里 depositor 指「存款人」（第 1 个义项：把钱存入银行的人）；句意为这位存款人在离开前索要了收据。图中可辨识物件：柜台窗口、信封、收据、登记册。","pos":[{"tag":"n.","zh":"存款人；存放者；寄托人（可数）"}],"collocations":[{"phrase":"a small depositor","zh":"小额存款人"},{"phrase":"protect depositors","zh":"保护存款人"},{"phrase":"an insured depositor","zh":"受保险保障的存款人"},{"phrase":"depositors' funds","zh":"存款人的资金"},{"phrase":"a foreign depositor","zh":"外国存款人"},{"phrase":"a depositor at the branch","zh":"分行的存款客户"}],"forms":[{"label":"复数","form":"depositors"},{"label":"相关动词（存放）","form":"deposit"},{"label":"相关名词（存款）","form":"deposit"},{"label":"相关名词（存放处）","form":"depository"},{"label":"相关名词（沉积；证词）","form":"deposition"}],"derivatives":[{"word":"deposit","pos":"n./v.","zh":"存款；押金；存放"},{"word":"depository","pos":"n.","zh":"存放处；保管机构"},{"word":"deposition","pos":"n.","zh":"沉积；宣誓证词"},{"word":"depositary","pos":"n.","zh":"受托保管人；存托机构"},{"word":"redeposit","pos":"v.","zh":"再次存入"}],"senses":[{"no":"01","title":"A person who pays money into a bank","titleCN":"把钱存入银行的人","definition":"a customer who places money in a bank account, either in cash or by transfer","definitionCN":"以现金或转账方式把钱放入银行账户的客户","example":"The depositor asked for a receipt before leaving.","exampleCN":"这位存款人在离开前索要了收据。","why":"deposit means to put down, and -or marks the one who does it, so the depositor is simply the person on the paying-in side of the counter.","whyCN":"deposit 意为「放下」，-or 标记做这件事的人，因此 depositor 就是柜台收付一侧交钱的那个人。"},{"no":"02","title":"One who leaves valuables for safekeeping","titleCN":"把贵重物品交人保管的人","definition":"a person who hands over documents, jewellery or other valuables to be stored safely","definitionCN":"把文件、珠宝或其他贵重物品交出保管的人","example":"Depositors left their documents in the bank's vault.","exampleCN":"存放者把文件留在银行的金库里。","why":"the bank sense is only one case of the older sense: anything entrusted to another for keeping makes the giver a depositor.","whyCN":"银行义只是旧义的一个特例：任何交人保管之物，其交付者都成为寄存人。"},{"no":"03","title":"One who files a document with an authority","titleCN":"向机关提交文件的人","definition":"a person who lodges a paper, such as a deed or a plan, with an official registry","definitionCN":"把契据、图则等文件送交官方登记机构的人","example":"The depositor filed the deed at the registry.","exampleCN":"提交人把契据送交登记处存档。","why":"lodging a paper in an official archive is putting it down for keeping, so the same agent noun serves.","whyCN":"把文件送进官方档案，就是把它放下保存，因此沿用了同一个施事名词。"},{"no":"04","title":"The party who entrusts in law","titleCN":"法律上的寄托人","definition":"in bailment, the party who gives property to another while keeping ownership of it","definitionCN":"在寄托关系中把财产交给他人保管但仍保留所有权的一方","example":"As depositor, she kept title to the stored grain.","exampleCN":"作为寄托人，她保留着所存谷物的所有权。","why":"law needs a name for the giver as distinct from the bailee, and it took the ordinary word for one who deposits.","whyCN":"法律需要一个与保管人相区别的名称来指交付方，于是采用了表示存放者的普通词。"},{"no":"05","title":"A device that lays down material","titleCN":"沉积材料的装置","definition":"in manufacturing or geology, an agent or machine that places a layer of material on a surface","definitionCN":"在制造或地质过程中，把一层材料铺到表面上的作用者或机器","example":"The depositor spreads a thin metal layer on the wafer.","exampleCN":"沉积装置在晶片上铺出一层薄金属。","why":"technical usage keeps the literal core, putting material down, and lets an apparatus be the one that does it.","whyCN":"技术用法保留了字面核心「把材料放下」，并让一台装置充当执行者。"},{"no":"06","title":"A candidate who pays an electoral deposit","titleCN":"缴纳选举保证金的候选人","definition":"in some electoral systems, a candidate who must pay a sum that is returned only if enough votes are won","definitionCN":"在某些选举制度中须缴纳一笔款项、得票不足便不予退还的候选人","example":"Each depositor must pay the sum before nomination.","exampleCN":"每位缴纳保证金的候选人必须在提名前付款。","why":"the money is literally deposited against the candidate's seriousness, so the payer takes the name of the act.","whyCN":"这笔钱是为候选人的认真程度作押，因此付款者取了这一行为的名称。"},{"no":"07","title":"One who entrusts something immaterial","titleCN":"抽象义：托付无形之物的人","definition":"a person who places hope, trust or memory in someone or something for keeping","definitionCN":"把希望、信任或记忆交付某人某物保存的人","example":"Anyone who deposits trust in a brand becomes its depositor.","exampleCN":"任何把信任存进某个品牌的人都成了它的托付者。","why":"the metaphor extends the vault to non-physical things: trust too can be handed over and kept.","whyCN":"这个比喻把金库扩展到非实物：信任也可以被交出并保存。"},{"no":"08","title":"A customer of an old goldsmith bank","titleCN":"旧时金匠银行的存户","definition":"historically, a person who left coin or plate with a goldsmith who issued receipts against it","definitionCN":"历史上把硬币或银器留给金匠、由其开具收据的人","example":"Goldsmiths kept a book of every depositor.","exampleCN":"金匠为每位存户都保留了一本册子。","why":"before modern banks, goldsmiths took deposits and issued notes, and their customers were the first to be called depositors in English.","whyCN":"在现代银行出现前，金匠吸收存款并开出票据，他们的客户是最早在英语中被称为存款人的人。"}],"etymology":{"intro":{"en":"Depositor is an English agent noun built on deposit, which comes from Latin depositum, the past participle of deponere 'to put down'. Dates are approximate.","cn":"depositor 是英语在 deposit 之上构成的施事名词，而 deposit 来自拉丁 depositum，即 deponere「放下」的过去分词。年代均为约数。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant 'to put, place, set'. Its compounds are everywhere in English: compose, impose, propose, expose, deposit.","cn":"ponere 意为「放置、安放」，其复合词遍布英语：compose、impose、propose、expose、deposit。"},{"era":"LATIN DEPONERE","en":"De- 'down, away' plus ponere gave deponere 'to put down, lay aside', used for entrusting something to another.","cn":"de-「向下、离开」加 ponere 构成 deponere「放下、搁置」，用于把某物交托他人。"},{"era":"LATIN DEPOSITUM","en":"The neuter past participle depositum meant 'a thing put down', and this noun carried both the object stored and the act of storing.","cn":"中性过去分词 depositum 意为「被放下之物」，这个名词既指被存放的物件，也指存放的行为。"},{"era":"ENGLISH DEPOSIT","en":"English took deposit in the seventeenth century for money placed with a bank and for material laid down by nature.","cn":"英语在 17 世纪吸收 deposit，既指存入银行的钱，也指自然沉积的物质。"},{"era":"ENGLISH AGENT NOUN","en":"Depositor is formed inside English with -or, the agent ending, and appears in the seventeenth century alongside the growth of banking.","cn":"depositor 由英语内部加施事后缀 -or 构成，于 17 世纪随银行业的发展出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the exact first use of depositor is unsettled, and the pre-Latin origin of ponere is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：depositor 的最早用例无定论，ponere 在拉丁语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms built on the same depositing stem; group two holds people whose money sits in a bank under a different name.","cn":"第一组是同出「存放」词干的形式；第二组是以别的名称把钱放在银行里的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deposit","ipa":"/dɪˈpɒzɪt/","tag":"the act or the sum","definition":"The verb and noun for putting money in; it names the act or the amount, not the person.","definitionCN":"表示存钱的动词与名词，指行为或金额，不指人。"},{"word":"depository","ipa":"/dɪˈpɒzɪtəri/","tag":"the place","definition":"A place or institution where things are stored, such as a book depository; the ending marks a location.","definitionCN":"存放物品的场所或机构，如图书存放处；词尾标记地点。"},{"word":"deposition","ipa":"/dɪˌpɒzɪʃn/","tag":"sworn evidence or sediment","definition":"A formal sworn statement, or material laid down by nature; the ending marks an action or result.","definitionCN":"正式的宣誓证词，或自然沉积的物质；词尾标记动作或结果。"},{"word":"depot","ipa":"/ˈdiːpəʊ/","tag":"a storehouse","definition":"From the same Latin depositum through French, but it names a warehouse or bus station.","definitionCN":"同出拉丁 depositum，经法语而来，但指仓库或公交场站。"}]},{"heading":"NEAR MEANING","entries":[{"word":"saver","ipa":"/ˈseɪvə(r)/","tag":"one who keeps money","definition":"A person who puts money aside, whether or not a bank holds it; depositor insists on the bank.","definitionCN":"把钱留起来的人，钱是否在银行无所谓；depositor 则强调银行。"},{"word":"account holder","ipa":"/əˈkaʊnt ˈhəʊldə(r)/","tag":"the record's owner","definition":"The person in whose name an account stands; a depositor may act for someone else.","definitionCN":"账户登记在其名下的人；存款人可能代他人办理。"},{"word":"investor","ipa":"/ɪnˈvestə(r)/","tag":"money at risk","definition":"One who puts money into assets expecting a return; a bank deposit is a claim, not an investment in that sense.","definitionCN":"把资金投入资产以期回报的人；银行存款是一种债权，不是此意义上的投资。"},{"word":"bailee","ipa":"/ˈbeɪliː/","tag":"the receiving side","definition":"In law, the person who receives goods for safekeeping; the depositor is the opposite side of the same relation.","definitionCN":"法律上接收货物保管的人；寄存人是同一关系中的另一方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"de- 'down' + ponere 'place': to put something down for keeping, hence deposit.","cn":"de-「向下」+ ponere「放置」：把东西放下保管，因此是存放。"},{"en":"The agent ending -or marks the person: depositor is the one who deposits.","cn":"施事后缀 -or 标记人：depositor 就是存放的那个人。"},{"en":"The family runs deposit, depositor, depository, deposition and depositary.","cn":"同族包括 deposit、depositor、depository、deposition 与 depositary。"},{"en":"Fixed phrases: a small depositor, an insured depositor, depositors' funds.","cn":"固定搭配：小额存款人、受保险保障的存款人、存款人的资金。"},{"en":"In law the depositor keeps ownership while another holds the goods.","cn":"在法律上，寄存人保留所有权，由他人持有货物。"}],"abstract":[{"en":"Picture a hand pushing an envelope through a slot and keeping the receipt half.","cn":"想象一只手把信封推进窗口，自己留下收据的另一半。"},{"en":"Picture trust as coins poured into a slot that only opens on request.","cn":"想象信任像硬币一样倒进一个只在请求时才打开的投口。"},{"en":"Picture a vault whose door has the depositor's name engraved outside.","cn":"想象一扇金库门，外面刻着寄存人的名字。"}]},"examples":[{"en":"The bank promised every depositor a written statement.","cn":"银行承诺给每位存款人一份书面对账单。"},{"en":"Small depositors were paid first after the collapse.","cn":"倒闭之后，小额存款人最先获得偿付。"},{"en":"A depositor may reclaim the goods when the agreed period ends.","cn":"约定期限结束后，寄存人可以取回货物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「de（下）+ posit（放）+ or（人）」——把东西放下保管的人 → 存款人、寄存人","word":"depositor"},"root":"拉丁 deponere「放下、搁置」= de-（向下、离开）+ ponere「放置」；过去分词 depositum「被放下之物」。depositor 为英语在 deposit 上加施事后缀 -or 构成。","sensesIntro":{"en":"Eight senses follow one act: something valuable is put down with another for keeping, and the person who does it is named across banking, archives, law, industry, elections and finally metaphor.","cn":"八个义项沿同一个动作展开：把贵重之物放下交人保管，做这件事的人在银行、档案、法律、工业、选举乃至比喻中都被这样称呼。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand placing a sealed envelope on a counter and receiving a receipt.","cn":"核心意象：一只手把封好的信封放在柜台上，并拿到一张收据。"},"chain":["PUT DOWN","ENTRUST","KEEP SAFE","RECORD THE NAME","CLAIM OWNERSHIP","EXTEND THE VAULT"],"branches":[{"senses":"01 · 08","en":"MONEY IN A BANK: the modern customer and the old goldsmith's client are the same person in different centuries.","cn":"银行里的钱：现代客户与旧时金匠的存户，是不同世纪里的同一种人。"},{"senses":"02","en":"VALUABLES IN STORAGE: documents and plate are entrusted just as money is.","cn":"存储的贵重物：文件与银器和钱一样被交托保管。"},{"senses":"03","en":"PAPERS LODGED: filing a deed with a registry is putting it down for keeping.","cn":"送存的文件：把契据送进登记处，就是把它放下保存。"},{"senses":"04 · 07","en":"OWNERSHIP KEPT: law separates the giver from the holder, and metaphor lets hope or trust be entrusted too.","cn":"保留的所有权：法律把交付方与持有人分开，比喻则让希望或信任也可被托付。"},{"senses":"05 · 06","en":"MATERIAL AND MONEY PUT DOWN: an industrial coater and an electoral pledge both perform the literal act.","cn":"放下的材料与钱：工业涂层装置与选举保证金都执行这个字面动作。"}]},"affixes":{"intro":{"en":"Depositor is a Latin verb stem wearing two English endings, an agent suffix on a participle noun, so the whole word reads as one who performs the act of putting down.","cn":"depositor 是一个拉丁动词词干带上英语词尾：在分词名词后加施事后缀，整个词读作「执行放下这一动作的人」。"},"latinIntro":{"en":"Latin ponere and its compound deponere supply the stem, with depositum giving the noun; the agent ending -or matches Latin agent nouns such as creditor.","cn":"拉丁 ponere 及其复合词 deponere 提供词干，depositum 提供名词；施事后缀 -or 与 creditor 等拉丁施事名词一致。"},"items":[{"word":"de-","structure":"Latin prefix de- (down, away)","meaning":"down; away","meaningCN":"向下；离开","example":"The prefix marks the downward placing.","exampleCN":"这个前缀标出向下放置的动作。"},{"word":"ponere","structure":"ponere, posui, positum (Latin verb, third conjugation)","meaning":"to put, place","meaningCN":"放置；安放","example":"The root is the plain act of placing.","exampleCN":"这个词根就是放置这一朴素动作。"},{"word":"deposit","structure":"de- + ponere (to put down)","meaning":"to place for keeping; the thing placed","meaningCN":"放下保管；被放下之物","example":"She deposited the cheque at noon.","exampleCN":"她在中午存入了支票。"},{"word":"depositor","structure":"deposit + -or (person who acts)","meaning":"one who deposits","meaningCN":"存放的人","example":"The depositor kept the receipt.","exampleCN":"存款人保留了收据。"},{"word":"depository","structure":"deposit + -ory (place or thing)","meaning":"a place where things are kept","meaningCN":"保存物品的场所","example":"The library acts as a legal depository.","exampleCN":"这家图书馆充当法定存放机构。"},{"word":"depositary","structure":"deposit + -ary (person or body entrusted)","meaning":"a person or body holding something in trust","meaningCN":"受托保管的人或机构","example":"The treaty named a depositary for the texts.","exampleCN":"条约指定了一个文本保管机构。"},{"word":"deposition","structure":"deposit + -ion (action or result)","meaning":"the act of laying down; sworn evidence","meaningCN":"放置；沉积；宣誓证词","example":"The deposition was read into the record.","exampleCN":"宣誓证词被记入案卷。"},{"word":"deposit account","structure":"deposit + account (fixed phrase)","meaning":"an account that pays interest","meaningCN":"付息的存款账户","example":"The deposit account pays monthly interest.","exampleCN":"这个存款账户按月付息。"},{"word":"redeposit","structure":"re- (again) + deposit","meaning":"to put money in again","meaningCN":"再次存入","example":"He redeposited the refund the next day.","exampleCN":"他第二天把退款又存了回去。"},{"word":"depot","structure":"Latin depositum through French dépôt","meaning":"a storehouse or transport base","meaningCN":"仓库；交通场站","example":"The buses return to the depot at night.","exampleCN":"公交车夜里回到场站。"}],"latinEntries":[{"word":"ponere","structure":"ponere, posui, positum (verb, third conjugation)","meaning":"to put, place","meaningCN":"放置；安放"},{"word":"deponere","structure":"deponere, deposui, depositum (verb, third conjugation)","meaning":"to put down, entrust","meaningCN":"放下；交托"},{"word":"depositum","structure":"depositum, -i (n., second declension)","meaning":"a thing deposited, a trust","meaningCN":"存放之物；托付物"}]}},{"word":"withdrawal","ipa_uk":"/wɪðˈdrɔːəl/","ipa_us":"/wɪðˈdrɔːəl/","definition_zh":"取款；退出；撤退；撤回；退缩；召回；取出的款项","definition_en":"the act of taking money out of an account, of pulling back from an activity, or of taking something back","core_image":"一只手从柜台窗口收回，手里多了一叠钞票，册子上刚划掉一行","scene":"她在柜台递上存折，要求取出一部分积蓄，职员清点后把钞票递出来。The withdrawal left the account almost empty.","sceneCN":"这里 withdrawal 指「取款」（第 1 个义项：把账户里的钱取出）；句意为这次取款之后账户几乎空了。图中可辨识物件：存折、柜台窗口、点钞机、划掉的记录行。","pos":[{"tag":"n.","zh":"取款；退出；撤退；撤回；退缩；召回（可数或不可数）"}],"collocations":[{"phrase":"a cash withdrawal","zh":"现金取款"},{"phrase":"make a withdrawal","zh":"取款"},{"phrase":"withdrawal from an agreement","zh":"退出某项协议"},{"phrase":"troop withdrawal","zh":"撤军"},{"phrase":"a withdrawal of support","zh":"撤回支持"},{"phrase":"a product withdrawal","zh":"产品召回"}],"forms":[{"label":"复数","form":"withdrawals"},{"label":"相关动词（取出）","form":"withdraw"},{"label":"相关动词三单","form":"withdraws"},{"label":"相关动词过去式","form":"withdrew"},{"label":"相关动词过去分词","form":"withdrawn"},{"label":"相关动词现在分词","form":"withdrawing"}],"derivatives":[{"word":"withdraw","pos":"v.","zh":"取出；退出；撤退"},{"word":"withdrawn","pos":"adj.","zh":"内向的；不与人来往的"},{"word":"withdrawable","pos":"adj.","zh":"可提取的"},{"word":"withdrawer","pos":"n.","zh":"取款人"},{"word":"withholding","pos":"n.","zh":"预扣（税款）"}],"senses":[{"no":"01","title":"Taking money out of an account","titleCN":"从账户取款","definition":"the act of taking money out of a bank account","definitionCN":"把资金从银行账户中取出的行为","example":"She made a withdrawal of two hundred yuan at the counter.","exampleCN":"她在柜台取了两百元。","why":"withdraw pictures drawing something back out of where it was placed, and money placed in a bank is drawn back out.","whyCN":"withdraw 描绘的是把放在某处的东西抽回来，而放进银行的钱正是被抽回来的对象。"},{"no":"02","title":"Pulling out of an activity","titleCN":"退出某项活动或协议","definition":"the act of ending one's participation in an agreement, a contest or an organization","definitionCN":"结束对某项协议、比赛或组织的参与","example":"The company announced its withdrawal from the talks.","exampleCN":"这家公司宣布退出谈判。","why":"to withdraw from something is to pull oneself back from it, so the noun names both the leaving and the state of having left.","whyCN":"从某事中 withdraw，就是把自己从中抽回，因此这个名词既指离开的动作，也指离开后的状态。"},{"no":"03","title":"Retracting a statement","titleCN":"撤回声明或指控","definition":"the act of taking back a claim, an offer or a promise already made","definitionCN":"收回已经作出的主张、提议或承诺","example":"The newspaper printed a withdrawal of the false claim.","exampleCN":"报纸刊登了对那项不实指控的撤回。","why":"words can be drawn back like objects, so a public taking back of a claim took the same noun.","whyCN":"话语像物件一样可以被抽回，因此公开收回主张也用了同一个名词。"},{"no":"04","title":"A military retreat","titleCN":"军事撤退","definition":"the orderly pulling back of troops from a position or a region","definitionCN":"部队从阵地或地区有序后撤","example":"The withdrawal of troops began at dawn.","exampleCN":"部队在黎明开始撤离。","why":"the military sense is the physical core made large: forces are drawn back from the ground they held.","whyCN":"军事义是字面核心的放大：军队从他们占据的地面被抽回。"},{"no":"05","title":"Emotional or social retreat","titleCN":"情绪上的退缩、离群","definition":"a habit of pulling away from other people or from contact, often as a symptom","definitionCN":"习惯性地避开他人或接触，常作为一种症状","example":"His withdrawal from friends worried his family.","exampleCN":"他避开朋友的状态让家人担忧。","why":"the metaphor moves from space to feeling: a person draws back from social contact as from a place.","whyCN":"这个比喻从空间转向感受：一个人从社交接触中抽身，如同从一个地方撤退。"},{"no":"06","title":"A recall of a product","titleCN":"产品召回","definition":"the removal of goods from shops or use because they are unsafe or faulty","definitionCN":"因不安全或有缺陷而把商品从商店或使用中收回","example":"The agency ordered the withdrawal of the faulty toy.","exampleCN":"该机构下令召回这款有缺陷的玩具。","why":"taking a product back out of circulation is the same gesture as taking money out of an account.","whyCN":"把产品从流通中收回，与把钱从账户中取出是同一个动作。"},{"no":"07","title":"The amount taken out","titleCN":"取出的款项","definition":"the sum of money actually taken out in one act","definitionCN":"一次行为中实际取出的金额","example":"The withdrawal was counted twice by the clerk.","exampleCN":"出纳把取出的款项清点了两遍。","why":"English often uses the action noun for its result, so a withdrawal is also the cash that changed hands.","whyCN":"英语常用动作名词指其结果，因此 withdrawal 也指经手的那笔现金。"},{"no":"08","title":"Leaving a contest","titleCN":"退出比赛","definition":"the act of dropping out of a race, tournament or competition before it ends","definitionCN":"在比赛、锦标赛或竞赛结束前退出","example":"Her withdrawal from the race came as a surprise.","exampleCN":"她退出这场比赛令人意外。","why":"a contest is a commitment like an agreement, so quitting it is described with the same pulling-back noun.","whyCN":"比赛与协议一样是一种承诺，因此退出比赛也用同一个表示抽身的词。"}],"etymology":{"intro":{"en":"Withdrawal is a native English verb plus a Romance noun ending. The verb withdraw is Old English; the noun is much later. Dates are approximate.","cn":"withdrawal 是一个英语本族动词加一个罗曼语系名词词尾。动词 withdraw 属古英语，名词出现得晚得多。年代均为约数。"},"items":[{"era":"OLD ENGLISH WITH","en":"The prefix is Old English wið 'against, away'. It is not the modern preposition with; the two forms are related but their functions differ.","cn":"这个前缀是古英语 wið「对着、离开」，并非现代介词 with；两者形式相关，但功能不同。"},{"era":"OLD ENGLISH DRAGAN","en":"Dragan meant 'to draw, drag'. Withdraw therefore meant to draw back or away, first of physical movement.","cn":"dragan 意为「拉、拖」。因此 withdraw 最初指把东西向后或向外拉开，先用于具体移动。"},{"era":"MILITARY AND LEGAL USE","en":"By the sixteenth century the verb covered pulling back troops and taking back a claim or a promise.","cn":"到 16 世纪，这个动词已涵盖后撤军队与收回主张或承诺。"},{"era":"NOUN IN -AL","en":"The noun withdrawal is recorded from the nineteenth century, formed with the ending -al that English took from Latin through French.","cn":"名词 withdrawal 自 19 世纪有记录，用的是英语经法语从拉丁语借来的词尾 -al。"},{"era":"BANKING SENSE","en":"As cheque accounts spread, withdrawal became the standard word for money taken out, and it later named the cash itself.","cn":"随着支票账户普及，withdrawal 成为指取出资金的标准词，后来又指那笔现金本身。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record of the banking sense is not fixed, and the deeper shared origin of wið and with is a reconstruction.","cn":"来源不确定（首见年代）：银行义的最早记录没有定论；wið 与 with 更深层的共同来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms that share the withdrawing stem; group two holds words for leaving, taking back and pulling out that differ in scope.","cn":"第一组是共用「抽回」词干的形式；第二组是范围不同的离开、收回与撤出类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"withdraw","ipa":"/wɪðˈdrɔː/","tag":"the verb","definition":"The verb names the act; the noun names the act as a thing, so the two are not interchangeable in grammar.","definitionCN":"动词指动作，名词把动作当作事物来指，两者在语法上不可互换。"},{"word":"withdrawn","ipa":"/wɪðˈdrɔːn/","tag":"the participle","definition":"Either the past participle of the verb or an adjective for a shy, remote person.","definitionCN":"既是动词的过去分词，也可是形容羞怯疏离之人的形容词。"},{"word":"withholding","ipa":"/wɪðˈhəʊldɪŋ/","tag":"holding back","definition":"From withhold: keeping back tax or information. It looks close but its second element is hold, not draw.","definitionCN":"来自 withhold：扣留税款或信息。字形相近，但后半是 hold 而非 draw。"},{"word":"withstand","ipa":"/wɪðˈstænd/","tag":"standing against","definition":"To resist or endure. It shares the old prefix but its second element is stand.","definitionCN":"抵抗、经受。共用古老前缀，但后半是 stand。"}]},{"heading":"NEAR MEANING","entries":[{"word":"retreat","ipa":"/rɪˈtriːt/","tag":"moving back in war","definition":"A withdrawal of forces, often because of defeat; it stresses the movement, not the act of taking something out.","definitionCN":"部队后撤，常因战败；强调移动，而不强调取出某物。"},{"word":"retraction","ipa":"/rɪˈtrækʃn/","tag":"taking back words","definition":"A formal taking back of a statement; withdrawal is broader and can also mean money or troops.","definitionCN":"正式收回声明；withdrawal 范围更广，也可指钱或军队。"},{"word":"departure","ipa":"/dɪˈpɑːtʃə(r)/","tag":"leaving a place","definition":"The act of going away from a place; it does not imply pulling back from a commitment.","definitionCN":"离开某地；不含从承诺中抽身之意。"},{"word":"secession","ipa":"/sɪˈseʃn/","tag":"leaving a body","definition":"Formal separation from a state or union; it is political and permanent, unlike a single withdrawal.","definitionCN":"从国家或联盟正式分离；带有政治性与永久性，不同于一次退出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"with- here is the old prefix 'away, against', and draw is to pull: to pull away.","cn":"这里的 with- 是古前缀「离开、对着」，draw 是拉：往外拉。"},{"en":"The family runs withdraw, withdrawal, withdrawn, withdrawable and withdrawer.","cn":"同族包括 withdraw、withdrawal、withdrawn、withdrawable 与 withdrawer。"},{"en":"Fixed phrases: a cash withdrawal, troop withdrawal, a withdrawal of support.","cn":"固定搭配：现金取款、撤军、撤回支持。"},{"en":"The noun ending -al turns the act into a countable thing, so one can speak of a withdrawal.","cn":"名词词尾 -al 把动作变成可数之物，因此可以说一次取款。"},{"en":"Withdraw, withhold and withstand all share the old prefix but have different second elements.","cn":"withdraw、withhold 与 withstand 共用古老前缀，但后半部分各不相同。"}],"abstract":[{"en":"Picture a hand sliding back out of a slot, leaving the slot emptier.","cn":"想象一只手从投口里抽回，投口因此更空。"},{"en":"Picture a person stepping backwards out of a lit circle.","cn":"想象一个人从一圈灯光里向后退出去。"},{"en":"Picture a word spoken aloud being lifted back into the mouth.","cn":"想象一句说出口的话被收回嘴里。"}]},"examples":[{"en":"Large withdrawals must be booked a day ahead.","cn":"大额取款必须提前一天预约。"},{"en":"The withdrawal of the offer ended the negotiation.","cn":"提议被撤回，谈判就此结束。"},{"en":"Repeated withdrawals drained the account.","cn":"反复取款把账户掏空了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「with（往回）+ draw（拉）+ al（名词）」——往回拉 → 取款、退出、撤退","word":"withdrawal"},"root":"古英语 wið「离开、对着」+ dragan「拉、拖」构成 withdraw；再加英语经法语从拉丁借来的名词词尾 -al 构成 withdrawal。with- 并非现代介词 with。","sensesIntro":{"en":"Eight senses follow one gesture: something is drawn back out of where it was placed, whether money, troops, a promise, a product, a person's attention or a competitor's entry.","cn":"八个义项沿同一个动作展开：把放在某处的东西抽回，无论那是金钱、军队、承诺、产品、一个人的社交投入，还是一名参赛者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pulling back out of a slot, taking something with it.","cn":"核心意象：一只手从投口中抽回，手里带走某物。"},"chain":["DRAW BACK","TAKE OUT","LEAVE A PLACE","LEAVE A COMMITMENT","TAKE BACK WORDS","REMOVE FROM USE"],"branches":[{"senses":"01 · 07","en":"MONEY OUT: the act of drawing cash out and the cash itself share one name.","cn":"取出钱：取现的动作与取出的现金共用一个名称。"},{"senses":"02 · 08","en":"LEAVING A COMMITMENT: quitting talks and quitting a race are both pulling oneself out.","cn":"离开承诺：退出谈判与退出比赛都是把自己抽出来。"},{"senses":"03","en":"WORDS BACK: a claim is withdrawn as if it were an object handed back.","cn":"收回话语：主张被撤回，仿佛是一件被交还的物件。"},{"senses":"04","en":"TROOPS BACK: the physical core writ large, forces drawn off the ground they held.","cn":"撤回军队：字面核心的放大，军队从占据的地面撤走。"},{"senses":"05 · 06","en":"OUT OF CONTACT AND OUT OF CIRCULATION: a person pulls back socially, and a faulty product is pulled from shelves.","cn":"退出接触与退出流通：人从社交中抽身，缺陷产品从货架上撤下。"}]},"affixes":{"intro":{"en":"Withdrawal is one native English verb plus one borrowed noun ending. The verb splits into an old prefix and a Germanic verb; the ending -al is Romance.","cn":"withdrawal 由一个英语本族动词加一个借来的名词词尾构成。动词可拆为古老前缀与一个日耳曼动词，词尾 -al 属罗曼语系。"},"latinIntro":{"en":"The base is Germanic, so there is no Latin verb behind it; only the noun ending -al came into English from Latin through French.","cn":"词基是日耳曼语，因此背后没有对应的拉丁动词；只有名词词尾 -al 经法语从拉丁语进入英语。"},"items":[{"word":"with-","structure":"Old English wið (against, away)","meaning":"away; against","meaningCN":"离开；对着","example":"The prefix reverses the direction of the verb.","exampleCN":"这个前缀把动词的方向反过来。"},{"word":"draw","structure":"Old English dragan (to drag, draw)","meaning":"to pull","meaningCN":"拉；拖","example":"Draw the curtain before the light fades.","exampleCN":"在光线消退前拉上帘子。"},{"word":"withdraw","structure":"with- + draw","meaning":"to pull back or take out","meaningCN":"抽回；取出","example":"He withdrew the offer the next day.","exampleCN":"他第二天撤回了提议。"},{"word":"-al","structure":"-al (noun ending from Latin -alis through French)","meaning":"the act or result of","meaningCN":"……的行为或结果","example":"The ending turns the verb into a noun.","exampleCN":"这个词尾把动词变成名词。"},{"word":"withdrawal","structure":"withdraw + -al","meaning":"the act of drawing back","meaningCN":"抽回的行为","example":"The withdrawal cleared the shelf.","exampleCN":"这次撤回清空了货架。"},{"word":"withdrawn","structure":"withdraw + -n (past participle)","meaning":"pulled back; reserved in manner","meaningCN":"被抽回的；性情内向的","example":"He grew withdrawn after the move.","exampleCN":"搬家之后他变得沉默寡言。"},{"word":"withdrawable","structure":"withdraw + -able (can be)","meaning":"able to be taken out","meaningCN":"可被取出的","example":"The funds are withdrawable at any branch.","exampleCN":"这笔资金可在任何分行取出。"},{"word":"withdrawer","structure":"withdraw + -er (person who)","meaning":"one who takes money out","meaningCN":"取款的人","example":"The withdrawer signed the slip.","exampleCN":"取款人在单据上签了字。"},{"word":"withholding","structure":"with- + hold + -ing","meaning":"keeping back tax or information","meaningCN":"扣留税款或信息","example":"Withholding tax is deducted at source.","exampleCN":"预扣税在源头扣除。"},{"word":"withstand","structure":"with- + stand","meaning":"to resist, endure","meaningCN":"抵抗；经受","example":"The bridge can withstand a strong flood.","exampleCN":"这座桥能经受猛烈的洪水。"}],"latinEntries":[]}},{"word":"withdraw","ipa_uk":"/wɪðˈdrɔː/","ipa_us":"/wɪðˈdrɔː/","definition_zh":"取出（存款）；抽回；撤退；退出；收回（说过的话）；退缩；召回；拉开","definition_en":"to take money out of an account, to pull something back, to leave a commitment, or to take back something said","core_image":"一只手把已经放进去的东西重新抽出来，动作方向与放入时相反","scene":"夜深了，他站在取款机前插入卡片，输入金额后又把卡收回口袋。She had to withdraw cash before the banks closed.","sceneCN":"这里 withdraw 指「取出存款」（第 1 个义项：把账户里的钱取出来）；句意为她必须在银行关门前取出些现金。图中可辨识物件：取款机、卡片、出钞口、收起的口袋。","pos":[{"tag":"v.","zh":"取出；抽回；撤退；退出；收回（可及物或不及物）"}],"collocations":[{"phrase":"withdraw money","zh":"取钱"},{"phrase":"withdraw from a deal","zh":"退出交易"},{"phrase":"withdraw troops","zh":"撤军"},{"phrase":"withdraw a statement","zh":"撤回声明"},{"phrase":"withdraw an offer","zh":"撤回提议"},{"phrase":"withdraw support","zh":"撤回支持"},{"phrase":"withdraw into oneself","zh":"变得沉默内向"}],"forms":[{"label":"三单（he/she/it）","form":"withdraws"},{"label":"过去式","form":"withdrew"},{"label":"过去分词","form":"withdrawn"},{"label":"现在分词","form":"withdrawing"},{"label":"名词","form":"withdrawal"}],"derivatives":[{"word":"withdrawal","pos":"n.","zh":"取款；退出；撤退"},{"word":"withdrawn","pos":"adj.","zh":"内向的；不与人来往的"},{"word":"withdrawable","pos":"adj.","zh":"可提取的"},{"word":"withdrawer","pos":"n.","zh":"取款人"},{"word":"withholding","pos":"n.","zh":"预扣（税款）"}],"senses":[{"no":"01","title":"To take money out of an account","titleCN":"取出存款","definition":"to take money out of a bank account","definitionCN":"把资金从银行账户中取出","example":"She had to withdraw cash before the banks closed.","exampleCN":"她必须在银行关门前取出些现金。","why":"the verb keeps its literal picture: something placed inside is drawn back out.","whyCN":"这个动词保留了字面图景：放进去的东西被抽回来。"},{"no":"02","title":"To pull something back","titleCN":"把某物抽回、移开","definition":"to move something back or away from where it was, often with the hand","definitionCN":"把某物从原来的位置向后或向外移开，常用手","example":"He withdrew his hand from the hot rail.","exampleCN":"他把手从滚烫的栏杆上缩回。","why":"this is the physical sense from which all the others are cut, and it still survives in everyday use.","whyCN":"这是其余义项所由切出的物理义，至今仍活跃于日常用法。"},{"no":"03","title":"To retreat militarily","titleCN":"军事撤退","definition":"to move troops back from a position or out of a region","definitionCN":"让部队从阵地后撤或撤出某地区","example":"The fleet withdrew from the harbour before dawn.","exampleCN":"舰队在黎明前撤出港口。","why":"an army drawn back from the ground it held is the literal picture applied at scale.","whyCN":"军队从占据的地面被抽回，是字面图景在更大尺度上的应用。"},{"no":"04","title":"To leave a commitment","titleCN":"退出某项承诺","definition":"to stop taking part in an agreement, a contest or an organization","definitionCN":"停止参与某项协议、比赛或组织","example":"Two sponsors withdrew from the event.","exampleCN":"两家赞助商退出了这项活动。","why":"withdrawing from a commitment is drawing oneself out of it, leaving the commitment behind like an empty slot.","whyCN":"退出承诺就是把自己从中抽走，把承诺留在身后，像一个空了的投口。"},{"no":"05","title":"To retract words","titleCN":"收回说过的话","definition":"to take back a statement, a claim, an offer or a threat","definitionCN":"收回声明、主张、提议或威胁","example":"The minister withdrew the remark within an hour.","exampleCN":"部长在一小时内收回了那句话。","why":"words are treated as objects that can be handed out and pulled back, which is why the same verb serves.","whyCN":"话语被当作可以递出又抽回的物件，因此沿用同一个动词。"},{"no":"06","title":"To become socially remote","titleCN":"退缩、变得离群","definition":"to pull away from other people, often into silence or solitude","definitionCN":"避开他人，常陷入沉默或独处","example":"After the loss he withdrew into himself.","exampleCN":"失去亲人后，他变得沉默内向。","why":"the space of the body becomes the space of feeling: one retreats from contact as from a place.","whyCN":"身体的空间变成情感的空间：人从接触中撤退，如同从一个地方撤离。"},{"no":"07","title":"To remove from circulation","titleCN":"召回、停止流通","definition":"to take a product, a coin or a book out of use or out of the shops","definitionCN":"把产品、硬币或书籍从使用或商店中收回","example":"The publisher withdrew the edition after the error.","exampleCN":"出错之后，出版社召回了这一版。","why":"withdrawing a thing from circulation is the same gesture as taking money from an account.","whyCN":"把某物从流通中收回，与从账户取钱是同一个动作。"},{"no":"08","title":"To draw back physically","titleCN":"拉开、抽开（帘幕等）","definition":"to pull a covering or a barrier back so that something is opened or revealed","definitionCN":"把遮盖物或屏障拉开，使某处打开或显露","example":"She withdrew the curtain to let the light in.","exampleCN":"她拉开帘子让光进来。","why":"the oldest literal use is simply to draw something away, and curtains still keep that sense alive.","whyCN":"最古老的字面用法就是「把某物拉开」，帘幕至今保留着这层意思。"}],"etymology":{"intro":{"en":"Withdraw is wholly Germanic: an Old English prefix of reversal plus a verb of pulling. It is not built from the Latin re- or from the modern preposition with. Dates are approximate.","cn":"withdraw 完全属日耳曼语：一个表示反向的古英语前缀加一个表示拉的动词。它并非由拉丁 re- 或现代介词 with 构成。年代均为约数。"},"items":[{"era":"OLD ENGLISH WIÐ","en":"Wið meant 'against, towards, away'. Its descendant with became a preposition, but in compounds the old sense of reversal survived.","cn":"wið 意为「对着、朝向、离开」。它的后裔 with 变成了介词，但在复合词中仍保留古老的反向义。"},{"era":"OLD ENGLISH DRAGAN","en":"Dragan 'to draw, drag' is native Germanic, related to Dutch dragen and German tragen; it is not a borrowing of Latin trahere.","cn":"dragan「拉、拖」是日耳曼本族词，与荷兰语 dragen、德语 tragen 相关；它不是对拉丁 trahere 的借用。"},{"era":"MIDDLE ENGLISH","en":"Withdrawen appears in Middle English for drawing back a person, a hand or a force.","cn":"中世纪英语的 withdrawen 指把一个人、一只手或一支部队抽回。"},{"era":"SIXTEENTH CENTURY","en":"The verb widened to taking back a claim, an offer or a privilege, and to leaving an alliance.","cn":"到 16 世纪，这个动词扩展到收回主张、提议或特权，以及退出联盟。"},{"era":"BANKING SENSE","en":"From the nineteenth century, withdrawing money from an account became the dominant everyday use.","cn":"从 19 世纪起，从账户取钱成为最主要的日常用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record of the banking use is not fixed, and any deeper link between wið and Latin re- would be a reconstruction, not a derivation.","cn":"来源不确定（首见年代）：银行用法的最早记录没有定论；把 wið 与拉丁 re- 拉上更深关系的说法只能是重构形式，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one holds forms that share the withdrawing stem or the old prefix; group two holds verbs of leaving, reducing and taking back with different scope.","cn":"第一组是共用「抽回」词干或古老前缀的形式；第二组是范围不同的离开、减少与收回类动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"withdrawal","ipa":"/wɪðˈdrɔːəl/","tag":"the noun","definition":"The noun for the act; the verb cannot stand where a noun is needed, as after a preposition.","definitionCN":"指动作的名词；在需要名词的位置（如介词后）不能换成动词。"},{"word":"withdrawn","ipa":"/wɪðˈdrɔːn/","tag":"the participle","definition":"The past participle of this verb, also used as an adjective for a reserved person.","definitionCN":"本动词的过去分词，也用作形容沉默内向者的形容词。"},{"word":"withhold","ipa":"/wɪðˈhəʊld/","tag":"hold back","definition":"To keep back money, consent or information; the second element is hold, so nothing is drawn out.","definitionCN":"扣住钱、同意或信息；第二成分是 hold，因此没有「抽出」之意。"},{"word":"withstand","ipa":"/wɪðˈstænd/","tag":"stand against","definition":"To resist or bear up under pressure; sharing the prefix does not make it a synonym.","definitionCN":"在压力下抵抗、撑住；共用前缀并不使它成为同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"retreat","ipa":"/rɪˈtriːt/","tag":"move back","definition":"To move back, especially in war or from a difficult situation; it lacks the taking-out sense.","definitionCN":"后撤，尤指战败或脱离困境；不含「取出」之意。"},{"word":"retract","ipa":"/rɪˈtrækt/","tag":"take back words","definition":"To formally take back a statement or an accusation; it is narrower than withdraw.","definitionCN":"正式收回声明或指控；比 withdraw 窄。"},{"word":"remove","ipa":"/rɪˈmuːv/","tag":"take away","definition":"To take something away from a place; it does not imply that the thing was previously put there by the same person.","definitionCN":"把某物从某处拿走；不暗示该物原先由同一人放入。"},{"word":"pull out","ipa":"/pʊl ˈaʊt/","tag":"the plain phrasal verb","definition":"The everyday equivalent for leaving a commitment or taking something out; withdraw is its formal counterpart.","definitionCN":"退出承诺或取出某物的日常说法；withdraw 是它正式的对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"with- is the old prefix 'away, against', and draw is 'pull': the word literally means pull away.","cn":"with- 是古前缀「离开、对着」，draw 是「拉」：这个词字面上就是往外拉。"},{"en":"The family runs withdraw, withdrawal, withdrawn, withdrawable and withdrawer.","cn":"同族包括 withdraw、withdrawal、withdrawn、withdrawable 与 withdrawer。"},{"en":"Fixed phrases: withdraw money, withdraw from a deal, withdraw troops, withdraw an offer.","cn":"固定搭配：取钱、退出交易、撤军、撤回提议。"},{"en":"The irregular forms are withdraws, withdrew, withdrawn, withdrawing.","cn":"不规则变化为 withdraws、withdrew、withdrawn、withdrawing。"},{"en":"Withdraw is not re- plus draw; the prefix is the Old English word for away.","cn":"withdraw 不是 re- 加 draw；前缀是古英语表示「离开」的词。"}],"abstract":[{"en":"Picture a drawer pulled open only to put the same object back where it was.","cn":"想象拉开抽屉，只为把同一件东西放回原处。"},{"en":"Picture a soldier stepping backwards while still facing the line.","cn":"想象一名士兵面朝队列向后退步。"},{"en":"Picture a sentence lifted off a page and returned to the mouth.","cn":"想象一句话从纸上被提起，退回嘴里。"}]},"examples":[{"en":"You can withdraw the money at any branch.","cn":"你可以在任何分行取出这笔钱。"},{"en":"The team withdrew from the tournament after the injury.","cn":"受伤之后，这支队伍退出了锦标赛。"},{"en":"He withdrew the accusation and apologised.","cn":"他撤回了指控并道歉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「with（往回）+ draw（拉）」——往回拉 → 取钱、撤退、收回","word":"withdraw"},"root":"古英语 wið「离开、对着」+ dragan「拉、拖」。dragan 属日耳曼本族词，与拉丁 trahere 无关；with- 也非现代介词 with。","sensesIntro":{"en":"Eight senses follow one gesture: something is pulled back out of its place, and the same verb covers cash, hands, armies, commitments, words, social contact, products and curtains.","cn":"八个义项沿同一个动作展开：把某物从原处抽回，同一个动词涵盖现金、手、军队、承诺、话语、社交接触、产品与帘幕。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pulling something back out of the slot it was put into.","cn":"核心意象：一只手把放进去的东西从投口里抽回来。"},"chain":["PULL BACK","TAKE OUT MONEY","LEAVE A PLACE","LEAVE A DEAL","TAKE BACK WORDS","WITHDRAW INTO SELF"],"branches":[{"senses":"01 · 02","en":"THE LITERAL PULL: cash out of an account and a hand off a hot rail are the same movement.","cn":"字面上的抽回：从账户取现与把手离开滚烫栏杆是同一个动作。"},{"senses":"03","en":"ARMIES BACK: the same pull applied to forces on ground.","cn":"军队后撤：同一个抽回动作用于地面的部队。"},{"senses":"04 · 07","en":"OUT OF A DEAL, OUT OF CIRCULATION: leaving an agreement and recalling an edition are both removal.","cn":"退出交易、退出流通：离开协议与召回版本都是移除。"},{"senses":"05","en":"WORDS BACK: a statement is handed back like an object.","cn":"收回话语：声明像物件一样被交还。"},{"senses":"06 · 08","en":"BACK FROM CONTACT AND BACK FROM THE WINDOW: social retreat and drawing a curtain share the direction.","cn":"退出接触与拉开帘幕：社交退缩与拉帘子方向相同。"}]},"affixes":{"intro":{"en":"The verb is two native pieces with no Romance root: an old prefix of reversal and a Germanic verb of pulling.","cn":"这个动词由两个本族成分构成，没有罗曼语词根：一个表示反向的古老前缀与一个日耳曼语表示拉的动词。"},"latinIntro":{"en":"There is no Latin source for this verb, so no Latin headwords are listed; the resemblance to Latin re- is only a resemblance.","cn":"这个动词没有拉丁语来源，因此不列拉丁词条；它与拉丁 re- 的相似只是外形相似。"},"items":[{"word":"with-","structure":"Old English wið (against, away)","meaning":"away; back","meaningCN":"离开；向后","example":"The prefix reverses the pull.","exampleCN":"这个前缀把「拉」的方向反转。"},{"word":"draw","structure":"Old English dragan (to drag)","meaning":"to pull, drag","meaningCN":"拉；拖","example":"They draw the boat onto the shore.","exampleCN":"他们把船拖上岸。"},{"word":"withdraw","structure":"with- + draw","meaning":"to pull back, take out","meaningCN":"抽回；取出","example":"She withdrew the cash at noon.","exampleCN":"她在中午取出了现金。"},{"word":"withdrawal","structure":"withdraw + -al (act or result)","meaning":"the act of pulling back","meaningCN":"抽回的行为","example":"The withdrawal took a minute.","exampleCN":"这次取款花了一分钟。"},{"word":"withdrawn","structure":"withdraw + -n (past participle)","meaning":"pulled back; reserved","meaningCN":"被抽回的；内向的","example":"The troops were withdrawn by night.","exampleCN":"部队在夜里撤走了。"},{"word":"withdrawing","structure":"withdraw + -ing (present participle)","meaning":"the act in progress","meaningCN":"正在抽回","example":"He is withdrawing his support.","exampleCN":"他正在撤回支持。"},{"word":"withdrawable","structure":"withdraw + -able (can be)","meaning":"able to be taken out","meaningCN":"可被取出的","example":"The deposit is withdrawable on demand.","exampleCN":"这笔存款可随时提取。"},{"word":"withdrawer","structure":"withdraw + -er (person who)","meaning":"one who withdraws money","meaningCN":"取款的人","example":"The withdrawer showed her card.","exampleCN":"取款人出示了她的卡。"},{"word":"withheld","structure":"with- + hold (past tense)","meaning":"kept back","meaningCN":"被扣住的","example":"The payment was withheld pending checks.","exampleCN":"付款在核查期间被扣住。"},{"word":"withstand","structure":"with- + stand","meaning":"to resist","meaningCN":"抵抗","example":"The wall can withstand the wind.","exampleCN":"这堵墙能顶住大风。"}],"latinEntries":[]}},{"word":"loan","ipa_uk":"/ləʊn/","ipa_us":"/loʊn/","definition_zh":"贷款；借款；出借；借用物；借词","definition_en":"money lent on the understanding that it will be repaid, or any thing lent for temporary use","core_image":"一只手把一叠钱推过桌面，桌对面的人签下一张写有归还日期的纸","scene":"年底，小店老板在银行签下文件，拿到一笔钱用于进货，约定按月归还。The shop took out a loan to buy stock for the winter.","sceneCN":"这里 loan 指「贷款」（第 1 个义项：借出并约定归还的钱）；句意为这家小店取得一笔贷款来备冬季存货。图中可辨识物件：合同、钞票、日历、签字笔。","pos":[{"tag":"n.","zh":"贷款；借款；借用物；借词（可数）"},{"tag":"v.","zh":"出借；贷出（多用于美式）"}],"collocations":[{"phrase":"take out a loan","zh":"取得贷款"},{"phrase":"pay off a loan","zh":"还清贷款"},{"phrase":"a student loan","zh":"学生贷款"},{"phrase":"a mortgage loan","zh":"按揭贷款"},{"phrase":"on loan","zh":"借来的；借展的"},{"phrase":"a loan word","zh":"借词"}],"forms":[{"label":"复数","form":"loans"},{"label":"三单（he/she/it）","form":"loans"},{"label":"过去式","form":"loaned"},{"label":"过去分词","form":"loaned"},{"label":"现在分词","form":"loaning"}],"derivatives":[{"word":"lend","pos":"v.","zh":"借出；贷款给"},{"word":"lender","pos":"n.","zh":"出借人；放贷方"},{"word":"loanee","pos":"n.","zh":"借入者；借用人"},{"word":"loanable","pos":"adj.","zh":"可出借的"},{"word":"loanword","pos":"n.","zh":"借词；外来词"},{"word":"reloan","pos":"v./n.","zh":"再借出；转贷"}],"senses":[{"no":"01","title":"Money lent for repayment","titleCN":"约定归还的贷款","definition":"a sum of money given to a borrower on condition that it is paid back, usually with interest","definitionCN":"交给借款人、约定归还（通常附利息）的一笔钱","example":"The shop took out a loan to buy stock for the winter.","exampleCN":"这家小店取得一笔贷款来备冬季存货。","why":"the core of the word is a thing handed over temporarily, and money is the thing most often handed over on those terms.","whyCN":"这个词的核心是临时交出的东西，而钱是最常按这种条件交出的东西。"},{"no":"02","title":"The act of lending","titleCN":"出借这一行为","definition":"the act or arrangement of lending something, as in the making of a loan","definitionCN":"借出某物的行为或安排，如放贷","example":"The loan was arranged in a single afternoon.","exampleCN":"这笔贷款在一个下午就办妥了。","why":"English uses the same noun for the act and the object, so a loan can name the transaction as well as the sum.","whyCN":"英语用同一个名词指行为和物件，因此 loan 既可指交易，也可指金额。"},{"no":"03","title":"An object lent temporarily","titleCN":"临时借出的物品","definition":"a thing other than money lent for temporary use, such as a book or a tool","definitionCN":"除金钱外临时借出的物品，如书或工具","example":"The library made a loan of the atlas for one week.","exampleCN":"图书馆把地图册外借一周。","why":"the money sense is the dominant one, but the older general sense of a thing lent never disappeared.","whyCN":"金钱义占主导，但「借出之物」这一更早的泛指义从未消失。"},{"no":"04","title":"A word borrowed from another language","titleCN":"借词；外来词","definition":"a word taken into one language from another, usually shortened from loanword","definitionCN":"从另一种语言进入某种语言的词，通常是 loanword 的缩略","example":"Sushi is a loan in English from Japanese.","exampleCN":"sushi 是英语从日语借来的借词。","why":"linguists extended the money metaphor to words, which are borrowed and never returned.","whyCN":"语言学家把金钱比喻扩展到词上：词被借走，却从不归还。"},{"no":"05","title":"To lend, as a verb","titleCN":"出借（动词义）","definition":"to give something to someone for temporary use, especially in American usage","definitionCN":"把某物交给他人临时使用，尤见于美式用法","example":"The bank loaned the money at a fixed rate.","exampleCN":"银行以固定利率贷出这笔钱。","why":"the verb is a later back-formation from the noun and remains less common than lend in British English.","whyCN":"动词义是从名词后起的逆构，在英式英语中仍不如 lend 常用。"},{"no":"06","title":"A temporarily transferred player","titleCN":"租借球员","definition":"in sport, a player allowed to play for another club for a period while still under contract","definitionCN":"体育中仍在原俱乐部合同期内、被允许为另一俱乐部短期出赛的球员","example":"The young striker joined on loan until June.","exampleCN":"这名年轻前锋以租借形式加盟到六月。","why":"a player is the object lent: the owning club keeps the contract, the other club gets temporary use.","whyCN":"球员就是被借出的对象：原俱乐部保留合同，另一俱乐部获得临时使用权。"},{"no":"07","title":"A work lent for an exhibition","titleCN":"借展作品","definition":"a painting or object lent by one museum to another for a show","definitionCN":"一家博物馆借给另一家用于展览的画作或器物","example":"The portrait is a loan from a private collection.","exampleCN":"这幅肖像是从私人收藏借展的作品。","why":"museums use the word because ownership stays put while the object travels temporarily.","whyCN":"博物馆用这个词，因为物件临时出门而所有权留在原处。"},{"no":"08","title":"A temporary grant, figuratively","titleCN":"抽象义：暂时的给予","definition":"a short grant of something immaterial, such as time, attention or confidence","definitionCN":"对无形之物的短期给予，如时间、关注或信心","example":"Time is a generous lender of second chances.","exampleCN":"时间总是大方地借出重来的机会。","why":"the metaphor treats time and trust as things lent rather than given, since they must be returned in some form.","whyCN":"这个比喻把时间与信任当作借出而非给出之物，因为它们终须以某种形式归还。"}],"etymology":{"intro":{"en":"Loan is a Scandinavian borrowing into English, not a Latin word. It is closely tied to lend, and the two descend from one Germanic idea. Dates are approximate.","cn":"loan 是英语从斯堪的纳维亚语借入的词，并非拉丁词。它与 lend 关系密切，两者源自同一个日耳曼概念。年代均为约数。"},"items":[{"era":"OLD NORSE LAN","en":"Old Norse lán meant 'loan, something lent'; it entered English during the Viking settlements and settled into the everyday vocabulary.","cn":"古诺斯语 lán 意为「借款、被借出之物」，在维京人定居时期进入英语，并落入日常词汇。"},{"era":"OLD ENGLISH LÆN","en":"Old English had læn 'loan' and lænan 'to lend'; the native noun was later replaced in most uses by the Scandinavian form.","cn":"古英语有 læn「借款」与 lænan「借出」；本族名词后来在多数用法中被斯堪的纳维亚形式取代。"},{"era":"GERMANIC ROOT","en":"The Germanic stock is generally traced to a root meaning 'to leave', so that a loan is literally something left with another person.","cn":"这套日耳曼词一般被追溯到表示「留下」的词根，因此借款字面上就是留在别人手里的东西。"},{"era":"DEEPER LINK","en":"That root would make loan a distant relative of Latin linquere 'to leave', but the connection is a reconstruction and not a borrowing from Latin.","cn":"若该词根成立，loan 便是拉丁 linquere「留下」的远亲；但这一联系属重构形式，并非从拉丁语借入。"},{"era":"MIDDLE ENGLISH SPELLING","en":"Middle English wrote the word as lone or lane; the modern spelling with -oa- is a later convention.","cn":"中世纪英语把这个词写作 lone 或 lane；现代带 -oa- 的拼法是后来的惯例。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the exact first record in English is not fixed, and the pre-Germanic root is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：它在英语中的最早记录没有定论，日耳曼语之前的词根属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms that share the lending stem; group two holds financial words that overlap with loan but differ in who owes and who owns.","cn":"第一组是共用「借出」词干的形式；第二组是与 loan 重叠、但在「谁欠谁、谁拥有」上不同的金融词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lend","ipa":"/lend/","tag":"the verb, native","definition":"The native verb for giving something temporarily; loan as a verb is its American twin.","definitionCN":"本族动词，表示临时给出；作动词的 loan 是它的美式孪生形式。"},{"word":"lender","ipa":"/ˈlendə(r)/","tag":"the person","definition":"One who lends; the ending -er marks the giver, not the thing given.","definitionCN":"出借的人；词尾 -er 标记给予者，而非被给予之物。"},{"word":"loanee","ipa":"/ləʊˈniː/","tag":"the receiver","definition":"The person who receives a loan; -ee marks the receiver, the mirror of -er.","definitionCN":"接受贷款的人；-ee 标记接受者，与 -er 相对。"},{"word":"lone","ipa":"/ləʊn/","tag":"same sound, different word","definition":"Meaning 'solitary', from a different stem; it sounds exactly like loan but shares no history.","definitionCN":"意为「孤单的」，词干不同；读音与 loan 完全相同，却无共同来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"credit","ipa":"/ˈkredɪt/","tag":"trust, not the sum","definition":"The trust that allows goods or money to be given before payment; a loan is the sum so given.","definitionCN":"允许先给货或钱后付款的信任；loan 是据此给出的款项。"},{"word":"mortgage","ipa":"/ˈmɔːɡɪdʒ/","tag":"a loan against property","definition":"A loan secured on property; it is one kind of loan, not a synonym for all loans.","definitionCN":"以财产作担保的贷款；是贷款的一种，并非所有贷款的统称。"},{"word":"debt","ipa":"/det/","tag":"what is owed","definition":"The obligation created by a loan; the loan is the money handed over, the debt is what remains owed.","definitionCN":"贷款产生的偿付义务；loan 是交出的钱，debt 是仍欠的部分。"},{"word":"advance","ipa":"/əˈvɑːns/","tag":"money paid early","definition":"Money paid before it is due, often to a worker or supplier; it may or may not be repaid.","definitionCN":"在到期前支付的款项，常给工人或供应商；可能需偿还，也可能不必。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Loan came from Old Norse, and lend is its native English cousin from the same Germanic idea.","cn":"loan 来自古诺斯语，lend 是同一日耳曼概念下的英语本族表亲。"},{"en":"The family runs loan, lend, lender, loanee, loanable, loanword and reloan.","cn":"同族包括 loan、lend、lender、loanee、loanable、loanword 与 reloan。"},{"en":"Fixed phrases: take out a loan, pay off a loan, a student loan, on loan.","cn":"固定搭配：取得贷款、还清贷款、学生贷款、借来的。"},{"en":"Loan and lone sound alike but have no shared history.","cn":"loan 与 lone 读音相同，却没有共同来源。"},{"en":"Museums and football clubs both say on loan when ownership stays put.","cn":"博物馆与足球俱乐部都用 on loan，表示所有权留在原处。"}],"abstract":[{"en":"Picture a coin handed across a table with a string still tied to the giver's hand.","cn":"想象一枚硬币递过桌面，绳子的另一端仍系在给出者手上。"},{"en":"Picture a borrowed book that returns with someone else's notes in the margin.","cn":"想象一本借出的书回来时页边写着别人的批注。"},{"en":"Picture time as a bank that lends hours and asks for them back later.","cn":"想象时间是一家银行，借出小时，日后又要求归还。"}]},"examples":[{"en":"The loan must be repaid within five years.","cn":"这笔贷款必须在五年内归还。"},{"en":"She took the novel on loan from the library.","cn":"她从图书馆借走了那本小说。"},{"en":"The painting is on loan to the museum for the summer.","cn":"这幅画整个夏天借展给博物馆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「loan 借出」——钱借出去，约期归还 → 贷款、借用物","word":"loan"},"root":"古诺斯语 lán「借款、借出之物」，与古英语 læn、动词 lænan「借出」同源；这套词一般追溯到表示「留下」的日耳曼词根，与拉丁 linquere「留下」的更深联系属重构形式。","sensesIntro":{"en":"Eight senses follow one act: something is handed over for temporary use and must come back, whether money, a book, a player, a painting, a word or a little time.","cn":"八个义项沿同一个动作展开：把某物交出供临时使用，并终须归还，无论那是钱、书、球员、画作、词，还是一点时间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a coin pushed across a table with a string still tied to the giver.","cn":"核心意象：一枚硬币被推过桌面，绳子的另一端仍系在给出者手上。"},"chain":["HAND OVER","KEEP OWNERSHIP","SET A TERM","EXPECT RETURN","EXTEND TO THINGS","EXTEND TO WORDS"],"branches":[{"senses":"01 · 02","en":"MONEY AND ITS ACT: the sum lent and the transaction share one noun.","cn":"钱与行为：借出的金额与这笔交易共用一个名词。"},{"senses":"03 · 07","en":"OBJECTS THAT TRAVEL: a book or a painting leaves its owner for a while and returns.","cn":"出门的物件：书或画暂时离开主人，然后再回来。"},{"senses":"04","en":"WORDS THAT NEVER RETURN: a borrowed word stays in the new language for good.","cn":"不再归还的词：借词永久留在新语言里。"},{"senses":"05","en":"THE VERB FORM: the same transaction seen as an action rather than a thing.","cn":"动词形式：同一笔交易被看作动作而非物件。"},{"senses":"06 · 08","en":"TEMPORARY GRANTS: a player and a stretch of time are both lent without being given away.","cn":"暂时的给予：球员与一段时间都是借出，而非送出。"}]},"affixes":{"intro":{"en":"Loan is a whole Scandinavian word, so its family is built by adding English endings to loan or to its native twin lend, not by peeling off Latin parts.","cn":"loan 是一个完整的斯堪的纳维亚词，因此它的词族靠给 loan 或其本族孪生词 lend 加英语词尾构成，而不是拆拉丁成分。"},"latinIntro":{"en":"No Latin word stands behind loan; Latin expressed the idea with mutuum, which is not related in form. Any link through the root for 'leave' is a reconstruction at a deeper level.","cn":"loan 背后没有拉丁词；拉丁语用 mutuum 表达这一概念，而它在形式上并无关联。通过「留下」词根建立的联系属更深层的重构形式。"},"items":[{"word":"loan","structure":"Old Norse lán (something lent)","meaning":"a sum or thing lent","meaningCN":"借出的钱或物","example":"The loan runs for three years.","exampleCN":"这笔贷款期限三年。"},{"word":"lend","structure":"Old English lænan (to lend)","meaning":"to give for temporary use","meaningCN":"临时给出使用","example":"They lend tools to their neighbours.","exampleCN":"他们把工具借给邻居。"},{"word":"lender","structure":"lend + -er (person who)","meaning":"one who lends","meaningCN":"出借的人","example":"The lender set a fixed rate.","exampleCN":"放贷方定下固定利率。"},{"word":"loanee","structure":"loan + -ee (person who receives)","meaning":"one who receives a loan","meaningCN":"接受贷款的人","example":"The loanee signed the schedule.","exampleCN":"借入者签了还款计划。"},{"word":"loanable","structure":"loan + -able (can be)","meaning":"able to be lent","meaningCN":"可出借的","example":"Only loanable stock leaves the store.","exampleCN":"只有可出借的库存才会离开商店。"},{"word":"loanword","structure":"loan + word (compound)","meaning":"a word taken from another language","meaningCN":"从另一语言借入的词","example":"The dictionary marks each loanword.","exampleCN":"词典标出每一个借词。"},{"word":"reloan","structure":"re- (again) + loan","meaning":"to lend again or pass on a loan","meaningCN":"再借出；转贷","example":"The bank reloaned the repaid funds.","exampleCN":"银行把已还的资金再次贷出。"},{"word":"on loan","structure":"loan in a prepositional phrase","meaning":"held temporarily from an owner","meaningCN":"以借用的方式持有","example":"The sculpture is on loan from a gallery.","exampleCN":"这件雕塑是从画廊借展的。"}],"latinEntries":[]}},{"word":"lender","ipa_uk":"/ˈlendə(r)/","ipa_us":"/ˈlendər/","definition_zh":"出借人；放贷方；贷款机构；出借物品者；法律上的出借人","definition_en":"a person or institution that gives money or goods to another on the understanding of repayment or return","core_image":"桌子一端的人把合同推过去，另一端的人接过钱，归还日期写在纸的中央","scene":"签约桌上，放款方把合同推到对面，逐条说明利率与还款期限。The lender asked for two guarantors before signing.","sceneCN":"这里 lender 指「放贷方」（第 1 个义项：把钱借出、等待归还的人或机构）；句意为放贷方在签约前要求两名担保人。图中可辨识物件：合同、利率表、印章、担保人签名栏。","pos":[{"tag":"n.","zh":"出借人；放贷方（可数）"}],"collocations":[{"phrase":"a mortgage lender","zh":"按揭放贷机构"},{"phrase":"the lender of last resort","zh":"最后贷款人"},{"phrase":"a private lender","zh":"私人放贷者"},{"phrase":"a lender's risk","zh":"放贷方的风险"},{"phrase":"a foreign lender","zh":"外国贷款方"},{"phrase":"the lender and the borrower","zh":"出借人与借款人"}],"forms":[{"label":"复数","form":"lenders"},{"label":"相关动词（出借）","form":"lend"},{"label":"相关动词过去式","form":"lent"},{"label":"相关动词过去分词","form":"lent"},{"label":"相关名词（借出之物）","form":"loan"},{"label":"相关名词（借入者）","form":"borrower"}],"derivatives":[{"word":"lend","pos":"v.","zh":"借出；贷款给"},{"word":"loan","pos":"n./v.","zh":"贷款；出借"},{"word":"lending","pos":"n.","zh":"放贷；出借"},{"word":"lender","pos":"n.","zh":"放贷方"},{"word":"lendable","pos":"adj.","zh":"可出借的"}],"senses":[{"no":"01","title":"A person who lends money","titleCN":"把钱借出的人","definition":"a person who gives money to another on the understanding that it will be repaid","definitionCN":"把钱交给他人、并约定归还的人","example":"The lender asked for two guarantors before signing.","exampleCN":"放贷方在签约前要求两名担保人。","why":"lend plus the agent ending -er names the giver in the transaction, the mirror image of the borrower.","whyCN":"lend 加施事后缀 -er，指交易中的给出方，与借款人正好相对。"},{"no":"02","title":"A financial institution in the business","titleCN":"从事放贷业务的金融机构","definition":"a bank, building society or finance company whose business is to make loans","definitionCN":"以发放贷款为业务的银行、建房互助会或金融公司","example":"Several lenders compete for the same mortgage.","exampleCN":"几家放贷机构为同一笔按揭竞争。","why":"once lending became an industry, the agent noun came to name firms as well as individuals.","whyCN":"当放贷成为一门行业，这个施事名词也用来指公司，而不只是个人。"},{"no":"03","title":"One who lends an object","titleCN":"出借物品的人","definition":"a person who allows another to use an object temporarily and expects it back","definitionCN":"允许他人临时使用某物、并期待归还的人","example":"The lender of the bicycle wants it back by Friday.","exampleCN":"借出自行车的人希望星期五前收回。","why":"the money sense is the dominant one, but the verb lends itself to any object handed over for temporary use.","whyCN":"金钱义占主导，但这个动词也可用于任何临时交出的物件。"},{"no":"04","title":"The party who lends in law","titleCN":"法律上的出借人","definition":"in bailment for use, the party who gives property while keeping ownership and expecting its return","definitionCN":"在使用借贷关系中交出财产、保留所有权并期待返还的一方","example":"As lender, she retained ownership of the tools.","exampleCN":"作为出借人，她保留着工具的所有权。","why":"law separates the giver from the holder, and the giver is named with the ordinary agent noun.","whyCN":"法律把交付方与持有人分开，交付方就用这个普通施事名词来指称。"},{"no":"05","title":"A sovereign or international lender","titleCN":"国家或国际贷款方","definition":"a state, fund or international body that lends to governments or large projects","definitionCN":"向政府或大型项目放贷的国家、基金或国际机构","example":"Foreign lenders restructured the debt last year.","exampleCN":"外国贷款方去年重组了这笔债务。","why":"states lend on the same terms as banks, so the word scales from a person to a treasury.","whyCN":"国家按与银行相同的条件放贷，因此这个词可以从个人放大到国库。"},{"no":"06","title":"A supplier who extends credit","titleCN":"给予赊账的供货方","definition":"a seller who hands over goods before payment and so carries the risk of non-payment","definitionCN":"在收款前先交货、因而承担不付款风险的卖方","example":"The supplier acted as lender while the goods were unpaid.","exampleCN":"货款未付期间，供应商实际上充当了出借方。","why":"credit is a loan in kind, so a supplier who waits for payment is lending the value of the goods.","whyCN":"赊账是实物形式的贷款，因此等待付款的供货方借出的是货物的价值。"},{"no":"07","title":"Any source that grants temporarily","titleCN":"抽象义：暂时给予的来源","definition":"figuratively, a person or thing that supplies something for a time without giving it away","definitionCN":"比喻上指临时提供某物、并不真正送出的来源","example":"Memory is a stern lender of borrowed scenes.","exampleCN":"记忆是一个严厉的出借者，只借出场景而不送出。","why":"the metaphor keeps the key condition: what is lent must eventually be given back.","whyCN":"这个比喻保留了关键条件：借出之物终须归还。"},{"no":"08","title":"A historical moneylender","titleCN":"旧时的放债者","definition":"historically, a private person who lent coin at interest, often under legal caps","definitionCN":"历史上以利息放贷的私人，常受法定上限约束","example":"The old lender charged interest that the law capped.","exampleCN":"这位旧时放债者收取的利息受法律上限约束。","why":"before banks served ordinary people, private lenders filled the gap, and the word carries that history.","whyCN":"在银行为普通人服务之前，私人放贷者填补了空缺，这个词带着那段历史。"}],"etymology":{"intro":{"en":"Lender is an English agent noun on lend, a native verb from Old English lænan. Nothing in it comes from Latin. Dates are approximate.","cn":"lender 是英语在 lend 之上构成的施事名词，而 lend 是来自古英语 lænan 的本族动词，其中没有拉丁成分。年代均为约数。"},"items":[{"era":"OLD ENGLISH LÆNAN","en":"Lænan meant 'to lend, to grant the use of', and came from læn 'a loan', the same stock that produced the modern noun loan.","cn":"lænan 意为「借出、准许使用」，来自 læn「借款」，与现代名词 loan 同出一源。"},{"era":"GERMANIC STOCK","en":"The verb belongs to a Germanic family that includes Dutch lenen and German leihen, all built on the idea of leaving something with another.","cn":"这个动词属日耳曼语族，包括荷兰语 lenen 与德语 leihen，都建立在「把某物留在他人处」这一概念上。"},{"era":"AGENT ENDING","en":"The ending -er is the native English agent suffix, so lender is simply the one who lends; the word is recorded from the twelfth century.","cn":"词尾 -er 是英语本族施事后缀，因此 lender 就是出借的人；该词自 12 世纪有记录。"},{"era":"BANKING USE","en":"As banking grew, lender widened from a private person to a firm, and phrases such as mortgage lender followed.","cn":"随着银行业发展，lender 从私人扩展到机构，mortgage lender 一类说法随之出现。"},{"era":"INTERNATIONAL USE","en":"In the twentieth century the word scaled again, naming states and international funds that lend to governments.","cn":"到 20 世纪，这个词再次放大，用来指向政府放贷的国家与国际基金。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record is not precisely dated, and the deeper pre-Germanic root is a reconstruction.","cn":"来源不确定（首见年代）：最早记录没有确切年代，日耳曼语之前的更深词根属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms from the same lending stem; group two holds the parties and instruments that sit on either side of a loan.","cn":"第一组是同出「借出」词干的形式；第二组是贷款两侧的人与工具。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lend","ipa":"/lend/","tag":"the verb","definition":"The act of giving temporarily; lender is the person who performs it.","definitionCN":"临时给出的动作；lender 是执行这一动作的人。"},{"word":"loan","ipa":"/ləʊn/","tag":"the thing","definition":"The sum or object lent; the lender gives the loan.","definitionCN":"借出的款项或物件；放贷方给出这笔贷款。"},{"word":"borrower","ipa":"/ˈbɒrəʊə(r)/","tag":"the other side","definition":"The person who receives the loan; lender and borrower are defined against each other.","definitionCN":"接受贷款的人；放贷方与借款人相互定义。"},{"word":"lender of last resort","ipa":"/ˈlendə(r) əv læst rɪˈzɔːt/","tag":"a fixed phrase","definition":"A central bank that lends when no other lender will; the phrase is a title, not a separate word.","definitionCN":"在其他放贷方都不肯放贷时提供贷款的中央银行；这是固定称谓，不是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"creditor","ipa":"/ˈkredɪtə(r)/","tag":"one who is owed","definition":"A person to whom money is owed; a lender is a creditor while the loan is outstanding, but a creditor need not have lent cash.","definitionCN":"被欠款的人；贷款未清时放贷方就是债权人，但债权人不一定借出过现金。"},{"word":"investor","ipa":"/ɪnˈvestə(r)/","tag":"money for a share","definition":"One who puts money in for a return from profits; a lender only expects repayment and interest.","definitionCN":"投入资金以分享利润的人；放贷方只期待还款与利息。"},{"word":"pawnbroker","ipa":"/ˈpɔːnbrəʊkə(r)/","tag":"lending against goods","definition":"A lender who takes an object as security and lends a fraction of its value.","definitionCN":"以物品作担保、按其价值的一部分放贷的人。"},{"word":"guarantor","ipa":"/ˌɡærənˈtɔː(r)/","tag":"the backstop","definition":"A person who promises to repay if the borrower fails; not a lender, but the lender's protection.","definitionCN":"承诺在借款人违约时偿还的人；不是放贷方，而是放贷方的保障。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"lend + -er: the person who lends; the ending is the ordinary English agent suffix.","cn":"lend 加 -er：出借的人；这个词尾就是英语普通的施事后缀。"},{"en":"The family runs lend, lent, lending, lender, loan and borrower.","cn":"同族包括 lend、lent、lending、lender、loan 与 borrower。"},{"en":"Fixed phrases: a mortgage lender, a private lender, the lender of last resort.","cn":"固定搭配：按揭放贷机构、私人放贷者、最后贷款人。"},{"en":"Lender and borrower are mirror terms: one gives, one receives.","cn":"lender 与 borrower 是一对镜像词：一个给，一个受。"},{"en":"Lender is not Latin; it is the native verb plus the native suffix.","cn":"lender 不是拉丁词；它是本族动词加本族词尾。"}],"abstract":[{"en":"Picture a hand holding the other end of a string tied to a coin.","cn":"想象一只手握着绳子的另一端，绳头系着一枚硬币。"},{"en":"Picture a chair lent to a guest who is expected to leave it by the door.","cn":"想象一把借给客人的椅子，客人离开时须放回门边。"},{"en":"Picture a clock that lends minutes and always takes them back.","cn":"想象一座钟借出分钟，又总会收回。"}]},"examples":[{"en":"The lender requires proof of income.","cn":"放贷方要求提供收入证明。"},{"en":"Small lenders were hit hardest by the rate rise.","cn":"利率上升对小型放贷机构打击最大。"},{"en":"The central bank acted as lender of last resort.","cn":"中央银行充当了最后贷款人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「lend（借出）+ er（人）」——把东西借出去的人 → 出借人、放贷方","word":"lender"},"root":"古英语 lænan「借出」+ 本族施事后缀 -er；lænan 来自 læn「借款」，与古诺斯语 lán、现代 loan 同源。无拉丁来源。","sensesIntro":{"en":"Eight senses follow one role: the person on the giving side of a temporary transfer, whether an individual, a bank, an object's owner, a state, a supplier or a metaphor.","cn":"八个义项沿同一个角色展开：临时转移中处于给出方的那个人，无论他是个人、银行、物主、国家、供货方，还是一个比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand lets go of a coin while the other end of the string stays with the giver.","cn":"核心意象：一只手松开硬币，绳子的另一端仍留在给出者手里。"},"chain":["GIVE TEMPORARILY","EXPECT RETURN","CHARGE INTEREST","TAKE SECURITY","SCALE TO FIRMS","SCALE TO STATES"],"branches":[{"senses":"01 · 03","en":"THE PERSON: one who lends money and one who lends a bicycle are the same role.","cn":"人：借钱给人的人与借出自行车的人是同一个角色。"},{"senses":"02 · 06","en":"LENDING AS BUSINESS: a bank and a supplier waiting for payment both carry the risk.","cn":"作为业务的出借：银行与等待付款的供货方都承担风险。"},{"senses":"04","en":"THE LEGAL ROLE: ownership stays with the giver while use passes over.","cn":"法律角色：使用权转出，所有权仍留在给出方。"},{"senses":"05","en":"THE SOVEREIGN ROLE: the same terms writ large between states.","cn":"国家角色：同样的条件在国与国之间放大。"},{"senses":"07 · 08","en":"OUTSIDE FINANCE: a metaphor for any temporary giver, and the memory of private moneylenders.","cn":"金融之外：既可比喻任何暂时给予者，也承载私人放债者的记忆。"}]},"affixes":{"intro":{"en":"The word is one native verb plus one native agent ending, so its parts are English through and through.","cn":"这个词是一个本族动词加一个本族施事词尾，两个部分都彻头彻尾属于英语。"},"latinIntro":{"en":"There is no Latin source here; Latin would express the lender with creditor or faenerator, words built on different roots.","cn":"这里没有拉丁来源；拉丁语会用 creditor 或 faenerator 表达放贷者，那些词建立在不同的词根上。"},"items":[{"word":"lend","structure":"Old English lænan (to lend)","meaning":"to grant temporary use","meaningCN":"准许临时使用","example":"Neighbours lend each other tools.","exampleCN":"邻居之间互借工具。"},{"word":"-er","structure":"Old English -ere (agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The ending marks the doer of the action.","exampleCN":"这个词尾标记动作的执行者。"},{"word":"lender","structure":"lend + -er","meaning":"one who lends","meaningCN":"出借的人","example":"The lender signed first.","exampleCN":"放贷方先签了字。"},{"word":"lending","structure":"lend + -ing (activity or participle)","meaning":"the business of lending","meaningCN":"放贷业务","example":"Lending slowed after the crisis.","exampleCN":"危机之后放贷放缓。"},{"word":"lent","structure":"lend + irregular past ending","meaning":"gave temporarily","meaningCN":"借出了","example":"She lent him the car for a day.","exampleCN":"她把车借给他用一天。"},{"word":"loan","structure":"Old Norse lán (a loan)","meaning":"the thing lent","meaningCN":"借出之物","example":"The loan fell due in May.","exampleCN":"贷款五月到期。"},{"word":"borrower","structure":"borrow + -er (the receiving side)","meaning":"one who takes a loan","meaningCN":"接受贷款的人","example":"The borrower repaid early.","exampleCN":"借款人提前还清了。"},{"word":"lendable","structure":"lend + -able (can be)","meaning":"able to be lent","meaningCN":"可出借的","example":"The fund keeps a lendable reserve.","exampleCN":"该基金保留一笔可出借的储备。"}],"latinEntries":[]}},{"word":"borrower","ipa_uk":"/ˈbɒrəʊə(r)/","ipa_us":"/ˈbɑːroʊər/","definition_zh":"借款人；借入者；借用人；举债方；法律上的借用人","definition_en":"a person or organization that takes money or an object from another on the understanding of repayment or return","core_image":"桌子另一端的人接过钱，在纸上写下自己的名字和还款日期","scene":"年轻夫妇在银行签下按揭文件，承诺每月按时偿还。The borrower missed the first payment and called the bank.","sceneCN":"这里 borrower 指「借款人」（第 1 个义项：取得贷款并承诺偿还的人）；句意为这名借款人错过了第一次还款并致电银行。图中可辨识物件：按揭合同、还款日历、电话、签名笔。","pos":[{"tag":"n.","zh":"借款人；借入者；借用人（可数）"}],"collocations":[{"phrase":"a creditworthy borrower","zh":"信用良好的借款人"},{"phrase":"a mortgage borrower","zh":"按揭借款人"},{"phrase":"a borrower defaults","zh":"借款人违约"},{"phrase":"a borrower's credit history","zh":"借款人的信用记录"},{"phrase":"a corporate borrower","zh":"企业借款人"},{"phrase":"the borrower and the lender","zh":"借款人与出借人"}],"forms":[{"label":"复数","form":"borrowers"},{"label":"相关动词（借入）","form":"borrow"},{"label":"相关动词三单","form":"borrows"},{"label":"相关动词过去式","form":"borrowed"},{"label":"相关动词过去分词","form":"borrowed"},{"label":"相关动词现在分词","form":"borrowing"}],"derivatives":[{"word":"borrow","pos":"v.","zh":"借入；借用"},{"word":"borrowing","pos":"n.","zh":"借贷；借款；借词"},{"word":"borrowable","pos":"adj.","zh":"可借入的"},{"word":"borrowings","pos":"n.","zh":"借款总额；借入项"},{"word":"lender","pos":"n.","zh":"出借人；放贷方"}],"senses":[{"no":"01","title":"A person who takes a loan","titleCN":"取得贷款的人","definition":"a person or firm that receives money on a promise to repay it, usually with interest","definitionCN":"接受资金并承诺偿还（通常附利息）的个人或公司","example":"The borrower missed the first payment and called the bank.","exampleCN":"这名借款人错过了第一次还款并致电银行。","why":"borrow names the receiving side of a loan, and -er marks the one who does it, so the borrower is the taker.","whyCN":"borrow 指贷款中的接受方，-er 标记做这件事的人，因此 borrower 是取得一方。"},{"no":"02","title":"One who borrows an object","titleCN":"借用物品的人","definition":"a person who takes an object for temporary use and is expected to return it","definitionCN":"拿走某物临时使用、并须归还的人","example":"The borrower returned the drill the same evening.","exampleCN":"借用人当天晚上就归还了电钻。","why":"the word covers any temporary taking, not only money, because borrow never meant money alone.","whyCN":"这个词涵盖任何临时取用，不只金钱，因为 borrow 从来不只是指钱。"},{"no":"03","title":"A company or state that issues debt","titleCN":"举债的公司或国家","definition":"an entity that raises money by issuing bonds or notes and so becomes the debtor","definitionCN":"通过发行债券或票据筹资、因而成为债务人的实体","example":"The borrower sold bonds to refinance old debt.","exampleCN":"这家举债方发行债券以重组旧债。","why":"in capital markets the entity that owes the money is called the borrower even when no bank is involved.","whyCN":"在资本市场中，欠款实体即使不经过银行也被称为借款人。"},{"no":"04","title":"A language that takes a word in","titleCN":"借入词语的语言","definition":"in linguistics, the community or language that adopts a word from another language","definitionCN":"语言学上从另一语言吸收词语的社群或语言","example":"English is a great borrower of technical terms.","exampleCN":"英语是技术术语的巨大借入者。","why":"linguists speak of words as borrowed, so the adopting language becomes the borrower.","whyCN":"语言学家把词语说成被借入，于是吸收方语言就成了借入者。"},{"no":"05","title":"One who borrows ideas","titleCN":"借用他人想法的人","definition":"a person who takes and uses someone else's idea, method or style","definitionCN":"取用他人想法、方法或风格的人","example":"The young painter was a borrower of older styles.","exampleCN":"这位年轻画家借用较早的风格。","why":"ideas travel like objects: they are taken, used and often returned in altered form.","whyCN":"想法像物件一样流动：被取走、使用，常以改变后的形态归还。"},{"no":"06","title":"The party who borrows in law","titleCN":"法律上的借用人","definition":"in bailment for use, the party who receives property for temporary use without gaining ownership","definitionCN":"在使用借贷关系中临时取得财产使用、但不获得所有权的一方","example":"The borrower must return the machine in good order.","exampleCN":"借用人必须完好归还这台机器。","why":"law needs a precise opposite to the lender, and it uses the everyday word for the receiving side.","whyCN":"法律需要一个与出借人精确相对的词，于是采用了表示接受方的日常词。"},{"no":"07","title":"A library patron","titleCN":"图书馆借阅者","definition":"a person who takes books or media from a library on loan","definitionCN":"从图书馆借走书籍或资料的人","example":"Every borrower may renew a book twice.","exampleCN":"每位借阅者可以续借两次。","why":"libraries were among the first institutions to use the word for ordinary object loans.","whyCN":"图书馆是最早把这词用于普通物品出借的机构之一。"},{"no":"08","title":"One who relies on others, figuratively","titleCN":"抽象义：依赖他人的人","definition":"figuratively, a person who depends on resources, courage or meaning supplied by someone else","definitionCN":"比喻上指依赖他人提供的资源、勇气或意义的人","example":"Every borrower of courage eventually has to repay it.","exampleCN":"每个借来勇气的人最终都得偿还。","why":"the metaphor extends borrowing to qualities that cannot be owned, only drawn on.","whyCN":"这个比喻把借入扩展到无法拥有、只能取用的品质。"}],"etymology":{"intro":{"en":"Borrower is English borrow plus the agent ending -er. Borrow is native, from Old English borgian, and has no Latin source. Dates are approximate.","cn":"borrower 是英语 borrow 加施事后缀 -er。borrow 是本族词，来自古英语 borgian，没有拉丁来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH BORGIAN","en":"Borgian meant 'to borrow' and also 'to lend', because the word first described the pledge given when something was handed over.","cn":"borgian 既指「借入」也指「借出」，因为这个词最初描述的是交付某物时所给的抵押。"},{"era":"OLD ENGLISH BORG","en":"The related noun borg meant 'pledge, surety'; a loan was secured by a pledge, so the pledge gave the transaction its name.","cn":"相关名词 borg 意为「抵押、担保」；贷款以抵押作保，于是抵押给了这笔交易名称。"},{"era":"GERMANIC FAMILY","en":"The stock appears in Old Norse borga and German borgen, all centred on lending against a pledge.","cn":"这套词见于古诺斯语 borga 与德语 borgen，核心都是凭抵押借贷。"},{"era":"AGENT ENDING","en":"The ending -er is the native agent suffix, and borrower is recorded from the fourteenth century.","cn":"词尾 -er 是本族施事后缀，borrower 自 14 世纪有记录。"},{"era":"FINANCIAL USE","en":"As banking spread, borrower narrowed towards the person who owes money, while the general sense of any borrowed object survived in libraries.","cn":"随着银行业普及，borrower 向欠款者收窄，而借任何物品的泛指义在图书馆里留存下来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record is not precisely dated, and the deeper pre-Germanic origin of borg is a reconstruction.","cn":"来源不确定（首见年代）：最早记录没有确切年代，borg 在日耳曼语之前的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms from the borrowing stem or words that look close; group two holds the parties and roles that surround a borrower.","cn":"第一组是同出「借入」词干或字形相近的形式；第二组是借款人周围的相关方与角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"borrow","ipa":"/ˈbɒrəʊ/","tag":"the verb","definition":"To take temporarily; the borrower is the person who does it.","definitionCN":"临时取用；borrower 是做这件事的人。"},{"word":"borrowing","ipa":"/ˈbɒrəʊɪŋ/","tag":"the act or amount","definition":"The act of taking a loan, or the sum taken; it is not the person.","definitionCN":"借入的行为或借入的金额，不是人。"},{"word":"borough","ipa":"/ˈbʌrə/","tag":"different origin","definition":"A town with a charter, from Old English burg 'fortified place'; it looks and sounds similar but is unrelated.","definitionCN":"享有特许状的城镇，来自古英语 burg「设防之地」；字形和读音相近，但无关联。"},{"word":"burrow","ipa":"/ˈbʌrəʊ/","tag":"different word","definition":"A hole dug by an animal, from Old English byrgian; it resembles borrow only in spelling.","definitionCN":"动物挖的洞穴，来自古英语 byrgian；仅在拼写上像 borrow。"}]},{"heading":"NEAR MEANING","entries":[{"word":"debtor","ipa":"/ˈdebtə(r)/","tag":"one who owes","definition":"A person who owes money; a borrower is a debtor while the loan is outstanding, but the words belong to different registers.","definitionCN":"欠款的人；贷款未清时借款人就是债务人，但两个词的使用场合不同。"},{"word":"lender","ipa":"/ˈlendə(r)/","tag":"the other side","definition":"The party who gives the money or object; the borrower is defined against it.","definitionCN":"给出资金或物品的一方；借款人以之相对定义。"},{"word":"lessee","ipa":"/ˈlesiː/","tag":"renting, not borrowing","definition":"One who holds property under a lease and pays rent; a borrower repays the same thing, a lessee pays for use.","definitionCN":"依租约持有财产并付租金的人；借款人归还原物，承租人则为使用付费。"},{"word":"mortgagor","ipa":"/ˈmɔːɡɪdʒɔː(r)/","tag":"the property side","definition":"The borrower who pledges property as security for a mortgage.","definitionCN":"在按揭中以财产作担保的借款人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"borrow + -er: the one who takes temporarily, the mirror of lender.","cn":"borrow 加 -er：临时取用的人，与 lender 相对。"},{"en":"The family runs borrow, borrowed, borrowing, borrower and borrowings.","cn":"同族包括 borrow、borrowed、borrowing、borrower 与 borrowings。"},{"en":"Fixed phrases: a mortgage borrower, a corporate borrower, a borrower defaults.","cn":"固定搭配：按揭借款人、企业借款人、借款人违约。"},{"en":"Borrow first meant to give a pledge, so a borrower is someone who has pledged something.","cn":"borrow 最初指给出抵押，因此借款人就是曾经押上某物的人。"},{"en":"Borrow, borough and burrow look alike but come from different stems.","cn":"borrow、borough 与 burrow 形近，却来自不同词干。"}],"abstract":[{"en":"Picture a hand taking a coin while a string stays tied to the giver's wrist.","cn":"想象一只手接过硬币，绳子仍系在给出者的手腕上。"},{"en":"Picture a reader leaving a library with a book that carries a due date.","cn":"想象一位读者带着一本写着到期日的书离开图书馆。"},{"en":"Picture courage as a coat borrowed from a friend and returned at the door.","cn":"想象勇气是一件向朋友借的外套，在门口归还。"}]},"examples":[{"en":"The borrower must provide two references.","cn":"借款人必须提供两名推荐人。"},{"en":"Corporate borrowers rushed to refinance before rates rose.","cn":"企业借款人在利率上升前争相重组债务。"},{"en":"The borrower returned the book two days late.","cn":"借阅者晚了两天才还书。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「borrow（借入）+ er（人）」——把东西借进来的人 → 借款人、借用人","word":"borrower"},"root":"古英语 borgian「借入（亦曾指借出）」+ 本族施事后缀 -er；borgian 与名词 borg「抵押、担保」相关，核心是凭抵押借贷。无拉丁来源。","sensesIntro":{"en":"Eight senses follow one role: the person on the receiving side of a temporary transfer, whether money, an object, a bond issue, a word, an idea or a quality.","cn":"八个义项沿同一个角色展开：临时转移中处于接受方的那个人，无论接受的是钱、物件、债券、词语、想法，还是一种品质。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand taking a coin while the string stays tied to the giver.","cn":"核心意象：一只手接过硬币，绳子仍系在给出者手上。"},"chain":["TAKE TEMPORARILY","PROMISE RETURN","OWE MONEY","TAKE A WORD","TAKE AN IDEA","RELY ON OTHERS"],"branches":[{"senses":"01 · 02","en":"THE PERSON WHO TAKES: money and objects are taken on the same promise to give back.","cn":"取用的人：钱与物件都按同一个归还承诺被取走。"},{"senses":"03","en":"THE ENTITY THAT OWES: a bond issuer is a borrower even without a bank.","cn":"欠款的实体：债券发行者即使不经过银行也是借款人。"},{"senses":"04 · 05","en":"WORDS AND IDEAS: a language and a painter both take what others made.","cn":"词语与想法：一种语言与一位画家都取用他人所造之物。"},{"senses":"06 · 07","en":"LAW AND LIBRARIES: the legal user and the library patron are everyday cases of temporary taking.","cn":"法律与图书馆：合法使用人与图书馆读者都是临时取用的日常情形。"},{"senses":"08","en":"BORROWED QUALITIES: courage and meaning can be drawn on but never owned.","cn":"借来的品质：勇气与意义可以取用，却无法拥有。"}]},"affixes":{"intro":{"en":"Borrower is a native verb plus a native agent ending; the stem once meant to give a pledge, which is why a borrower is also someone who has pledged.","cn":"borrower 是一个本族动词加本族施事词尾；词干原指给出抵押，因此借款人也是曾经押上某物的人。"},"latinIntro":{"en":"No Latin word lies behind this family; Latin used mutuum for a loan and creditor or debitor for the parties, all on different roots.","cn":"这个词族背后没有拉丁词；拉丁语用 mutuum 表示贷款，用 creditor 或 debitor 表示双方，词根都不同。"},"items":[{"word":"borrow","structure":"Old English borgian (to borrow, formerly also to lend)","meaning":"to take with a promise to return","meaningCN":"取用并承诺归还","example":"May I borrow your pen?","exampleCN":"我可以借你的笔吗？"},{"word":"borg","structure":"Old English borg (pledge, surety)","meaning":"a pledge backing a loan","meaningCN":"为借贷作保的抵押","example":"The pledge gave the transaction its name.","exampleCN":"抵押给了这笔交易名称。"},{"word":"-er","structure":"Old English -ere (agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The ending marks the person who acts.","exampleCN":"这个词尾标记行动的人。"},{"word":"borrower","structure":"borrow + -er","meaning":"one who takes temporarily","meaningCN":"临时取用的人","example":"The borrower signed the schedule.","exampleCN":"借款人签了还款计划。"},{"word":"borrowing","structure":"borrow + -ing (act or amount)","meaning":"the act of taking a loan","meaningCN":"借入的行为","example":"Borrowing rose before the deadline.","exampleCN":"截止日前借入量上升。"},{"word":"borrowed","structure":"borrow + -ed (past or adjective)","meaning":"taken temporarily; adopted","meaningCN":"被借入的；被吸收的","example":"The borrowed word kept its original spelling.","exampleCN":"这个借词保留了原来的拼写。"},{"word":"borrowable","structure":"borrow + -able (can be)","meaning":"able to be borrowed","meaningCN":"可借入的","example":"The tools are borrowable for a week.","exampleCN":"这些工具可借一周。"},{"word":"borrowings","structure":"borrowing + -s (plural noun)","meaning":"the total amount borrowed","meaningCN":"借入总额","example":"The firm's borrowings exceeded its assets.","exampleCN":"这家公司的借入总额超过了资产。"}],"latinEntries":[]}},{"word":"borrowing","ipa_uk":"/ˈbɒrəʊɪŋ/","ipa_us":"/ˈbɑːroʊɪŋ/","definition_zh":"借入；借贷；借款额；借词；借用","definition_en":"the act of taking money or an object on loan, the amount so taken, or a word adopted from another language","core_image":"账簿上新添的一栏，栏头写着「借入」，下面的数字一行行加长","scene":"公司财务在报表上把新借入的款项单独列成一栏，准备逐年归还。Heavy borrowing kept the factory open through the winter.","sceneCN":"这里 borrowing 指「借入、借贷」（第 1 个义项：取得贷款这一行为）；句意为大量借贷让工厂撑过了冬天。图中可辨识物件：报表、栏线、计算器、还款计划表。","pos":[{"tag":"n.","zh":"借贷；借入；借款额；借词（可数或不可数）"}],"collocations":[{"phrase":"government borrowing","zh":"政府举债"},{"phrase":"heavy borrowing","zh":"大量借贷"},{"phrase":"corporate borrowing","zh":"企业借款"},{"phrase":"foreign borrowing","zh":"对外借款"},{"phrase":"a borrowing cost","zh":"借贷成本"},{"phrase":"borrowing from another language","zh":"从另一语言借入"}],"forms":[{"label":"复数（借款项；借词）","form":"borrowings"},{"label":"相关动词（借入）","form":"borrow"},{"label":"相关动词三单","form":"borrows"},{"label":"相关动词过去式","form":"borrowed"},{"label":"相关动词过去分词","form":"borrowed"},{"label":"相关名词（借款人）","form":"borrower"}],"derivatives":[{"word":"borrow","pos":"v.","zh":"借入；借用"},{"word":"borrower","pos":"n.","zh":"借款人；借用人"},{"word":"borrowings","pos":"n.","zh":"借款总额；借入项"},{"word":"borrowable","pos":"adj.","zh":"可借入的"},{"word":"lending","pos":"n.","zh":"放贷；出借"}],"senses":[{"no":"01","title":"The act of taking a loan","titleCN":"借入这一行为","definition":"the act of obtaining money or goods that must be repaid or returned","definitionCN":"取得须偿还或归还的钱或货物的行为","example":"Heavy borrowing kept the factory open through the winter.","exampleCN":"大量借贷让工厂撑过了冬天。","why":"borrow plus the noun ending -ing turns the act into a thing one can talk about, count and criticise.","whyCN":"borrow 加名词词尾 -ing，把动作变成可以谈论、计量与批评的事物。"},{"no":"02","title":"The amount borrowed","titleCN":"借入的金额","definition":"the total sum taken on loan, especially as shown in accounts","definitionCN":"借入款项的总额，尤指账面上列示的数额","example":"The company's borrowings doubled in two years.","exampleCN":"这家公司的借款额在两年内翻了一番。","why":"the plural of the action noun is standard in finance for the sums owed, because each loan is a separate taking.","whyCN":"金融语境中常用这个动作名词的复数指欠款总额，因为每一笔贷款都是一次单独的借入。"},{"no":"03","title":"A word taken from another language","titleCN":"借词；外来词","definition":"a word adopted into one language from another, often with adapted spelling or sound","definitionCN":"从另一语言吸收进某种语言的词，拼写或读音常经调整","example":"The dictionary lists hundreds of French borrowings.","exampleCN":"这部词典列出数百个法语借词。","why":"linguists describe words as borrowed, so the process and the word itself both take the borrowing label.","whyCN":"语言学家把词语说成借入，因此过程与词本身都带上了「借入」的标签。"},{"no":"04","title":"The process of linguistic borrowing","titleCN":"语言借用的过程","definition":"the historical process by which one language takes words, sounds or structures from another","definitionCN":"一种语言从另一语言吸收词、语音或结构的历史过程","example":"Borrowing between the two languages lasted three centuries.","exampleCN":"两种语言之间的借用持续了三个世纪。","why":"the abstract process sense lets historians talk about borrowing without naming any single word.","whyCN":"抽象的过程义让史家可以谈论借用，而不必指某一个具体的词。"},{"no":"05","title":"A temporary player transfer","titleCN":"球员租借","definition":"in sport, the arrangement by which a club takes a contracted player from another club for a period","definitionCN":"体育中一家俱乐部在一定期限内取得另一家合同期内球员的安排","example":"The club's borrowing of the winger lasted half a season.","exampleCN":"这家俱乐部租借这名边锋只持续了半个赛季。","why":"a player is taken temporarily and returned, so the transfer is described with the same noun as any other loan.","whyCN":"球员被临时取用并归还，因此这种转会与别的借用共用同一个名词。"},{"no":"06","title":"An object taken for temporary use","titleCN":"借用的物品","definition":"a thing other than money that is taken temporarily and must be returned","definitionCN":"除金钱外被临时取用、并须归还的物件","example":"The borrowing of the ladder saved them a trip to the shop.","exampleCN":"借来这把梯子让他们省了一趟去店里的路。","why":"the everyday sense never died out, even though finance now dominates the word.","whyCN":"尽管金融义如今占主导，这个日常义从未消失。"},{"no":"07","title":"Reliance on others' ideas","titleCN":"抽象义：沿用他人的想法","definition":"figuratively, the taking of ideas, styles or methods from another source without owning them","definitionCN":"比喻上指从另一来源取用想法、风格或方法，却不真正拥有","example":"The composer's borrowing from folk songs is openly acknowledged.","exampleCN":"这位作曲家对民歌的借用是公开承认的。","why":"ideas are treated as goods that can be taken on loan and handed back in altered form.","whyCN":"想法被当作可以借走、并以改变形式交还的货物。"},{"no":"08","title":"Public-sector borrowing","titleCN":"公共部门举债","definition":"the amount a government or public body must raise in a year to cover the gap between spending and revenue","definitionCN":"政府或公共机构为弥补收支缺口而在一年内必须筹措的金额","example":"Public borrowing rose as tax receipts fell.","exampleCN":"税收下降之际，公共部门举债上升。","why":"the aggregate sense treats all the state's loans as one measurable flow with economic effects.","whyCN":"总量义把国家的所有借款看作一个有经济影响的可测流量。"}],"etymology":{"intro":{"en":"Borrowing is the native verb borrow plus the noun ending -ing; borrow itself goes back to Old English borgian and has no Latin source. Dates are approximate.","cn":"borrowing 是本族动词 borrow 加名词词尾 -ing；borrow 本身可追溯到古英语 borgian，没有拉丁来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH BORGIAN","en":"Borgian meant 'to borrow' and also 'to lend'; the verb described a transaction secured by a pledge rather than a one-way transfer.","cn":"borgian 既指「借入」也指「借出」；这个动词描述的是以抵押作保的交易，而非单向转移。"},{"era":"OLD ENGLISH BORG","en":"The noun borg 'pledge, surety' supplied the security behind the deal, and the verb was formed on it.","cn":"名词 borg「抵押、担保」提供交易背后的保障，动词即由此构成。"},{"era":"GERMANIC FAMILY","en":"Cognates include Old Norse borga and German borgen, all built on lending against a pledge.","cn":"同源词包括古诺斯语 borga 与德语 borgen，都建立在凭抵押借贷之上。"},{"era":"NOUN IN -ING","en":"The ending -ing is the native English suffix for an activity or its result, so borrowing names the act and, in the plural, the sums taken.","cn":"词尾 -ing 是英语本族表示活动或其结果的后缀，因此 borrowing 指行为，复数则指借入的款项。"},{"era":"LINGUISTIC USE","en":"From the nineteenth century linguists used borrowing for words taken from other languages, extending the money metaphor to vocabulary.","cn":"从 19 世纪起，语言学家用 borrowing 指从其他语言吸收的词，把金钱比喻扩展到词汇。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the first use of the financial plural is not precisely dated, and the pre-Germanic origin of borg is a reconstruction.","cn":"来源不确定（首见年代）：金融复数的最早用例没有确切年代，borg 在日耳曼语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms from the same stem or with a similar shape; group two holds financial aggregates that overlap with borrowing in meaning.","cn":"第一组是同词干或字形相近的形式；第二组是在含义上与 borrowing 重叠的金融总量词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"borrow","ipa":"/ˈbɒrəʊ/","tag":"the verb","definition":"The act of taking on loan; borrowing is the same act turned into a noun.","definitionCN":"借入的动作；borrowing 是同一动作变成名词。"},{"word":"borrower","ipa":"/ˈbɒrəʊə(r)/","tag":"the person","definition":"The person who borrows; the ending -er marks a person, while -ing marks the act.","definitionCN":"借入的人；-er 标记人，-ing 标记行为。"},{"word":"lending","ipa":"/ˈlendɪŋ/","tag":"the mirror act","definition":"The act of giving on loan; borrowing and lending are the two sides of one transaction.","definitionCN":"出借的行为；借入与出借是同一笔交易的两面。"},{"word":"borrowings","ipa":"/ˈbɒrəʊɪŋz/","tag":"the plural sum","definition":"The plural is a finance term for total debt, not merely several acts of borrowing.","definitionCN":"复数形式是金融术语，指债务总额，不只是多次借入行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"debt","ipa":"/det/","tag":"what remains owed","definition":"The obligation left after borrowing; borrowing is the flow, debt is the stock.","definitionCN":"借入之后留下的偿付义务；borrowing 是流量，debt 是存量。"},{"word":"loan","ipa":"/ləʊn/","tag":"one instrument","definition":"A single sum lent; borrowing can cover many loans and need not be arranged with a bank.","definitionCN":"单笔借出的款项；borrowing 可涵盖多笔贷款，且未必经由银行。"},{"word":"leverage","ipa":"/ˈliːvərɪdʒ/","tag":"debt used to invest","definition":"Borrowed money used to amplify returns; it stresses the investment strategy, not the act of borrowing.","definitionCN":"用来放大收益的借入资金；强调投资策略，而非借入行为。"},{"word":"arrears","ipa":"/əˈrɪəz/","tag":"overdue amounts","definition":"Money that is late, not money newly borrowed; it marks a failure to pay on time.","definitionCN":"逾期未付的钱，不是新借入的钱；它标记未能按时付款。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"borrow + -ing: the act of taking on loan, and in the plural the sums taken.","cn":"borrow 加 -ing：借入的行为，复数则指借入的款项。"},{"en":"The family runs borrow, borrower, borrowing, borrowings and borrowable.","cn":"同族包括 borrow、borrower、borrowing、borrowings 与 borrowable。"},{"en":"Fixed phrases: government borrowing, heavy borrowing, corporate borrowing, foreign borrowing.","cn":"固定搭配：政府举债、大量借贷、企业借款、对外借款。"},{"en":"Borrow and lend are the two directions of one deal.","cn":"借入与借出是一笔交易的两个方向。"},{"en":"Borrowing is also the word linguists use for words taken from other languages.","cn":"borrowing 也是语言学家用来指从其他语言吸收词语的词。"}],"abstract":[{"en":"Picture a column of figures that grows longer every month.","cn":"想象一列数字每个月都变得更长。"},{"en":"Picture a word moving house into a new language and keeping its old furniture.","cn":"想象一个词搬进新语言，还带着旧家具。"},{"en":"Picture a player wearing another club's shirt for half a season.","cn":"想象一名球员穿着另一家俱乐部的球衣半个赛季。"}]},"examples":[{"en":"Borrowing is cheaper when interest rates are low.","cn":"利率低时借贷更便宜。"},{"en":"The government cut borrowing after the recovery.","cn":"经济复苏后政府削减了举债。"},{"en":"The word comes from a borrowing made in the sixteenth century.","cn":"这个词来自 16 世纪的一次借用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「borrow（借入）+ ing（行为）」——借进来的这件事或这笔钱 → 借贷、借款额","word":"borrowing"},"root":"古英语 borgian「借入（亦曾指借出）」+ 本族名词词尾 -ing；borgian 与 borg「抵押、担保」相关。无拉丁来源。","sensesIntro":{"en":"Eight senses follow one act: taking something on loan, and the same noun covers the act, the sum, a word taken into a language, a transferred player and a public deficit.","cn":"八个义项沿同一个动作展开：把某物借入，同一个名词涵盖行为、金额、被语言吸收的词、被租借的球员以及公共赤字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new column headed 'taken on loan' with figures growing down the page.","cn":"核心意象：报表上新添一栏，栏头写着「借入」，数字沿页面往下增长。"},"chain":["TAKE ON LOAN","OWE A SUM","COUNT THE TOTAL","TAKE A WORD","TAKE A PLAYER","FILL A DEFICIT"],"branches":[{"senses":"01 · 06","en":"THE ACT ITSELF: money or a ladder, the taking is the same and must be undone.","cn":"行为本身：无论是钱还是梯子，取用都一样，且都须归还。"},{"senses":"02","en":"THE STOCK: the plural turns many takings into one figure of debt.","cn":"存量：复数把多次借入变成一个债务数字。"},{"senses":"03 · 04","en":"WORDS TAKEN: one borrowed word and the whole historical process share the label.","cn":"借来的词：单个借词与整个历史过程共用这个标签。"},{"senses":"05","en":"PLAYERS TAKEN: a club borrows a contracted player and returns him.","cn":"借来的球员：俱乐部借入合同期内的球员，再归还。"},{"senses":"07 · 08","en":"IDEAS AND DEFICITS: composers borrow styles, and states borrow to cover spending.","cn":"想法与赤字：作曲家借用风格，国家借钱弥补开支。"}]},"affixes":{"intro":{"en":"Borrowing is a native stem plus a native noun ending, so its parts are English and its meaning is the act or the result of taking on loan.","cn":"borrowing 是一个本族词干加本族名词词尾，两个部分都属英语，含义是借入这一动作或其结果。"},"latinIntro":{"en":"There is no Latin source; the Latin words for a loan and for borrowing belong to other roots and are not ancestors of this form.","cn":"这里没有拉丁来源；拉丁语表示贷款与借入的词属于别的词根，并不是这一形式的祖先。"},"items":[{"word":"borrow","structure":"Old English borgian (to borrow)","meaning":"to take with a promise to return","meaningCN":"取用并承诺归还","example":"They borrow the boat every summer.","exampleCN":"他们每年夏天都借这条船。"},{"word":"-ing","structure":"Old English -ing (noun of action or result)","meaning":"the act or result of","meaningCN":"……的行为或结果","example":"The ending turns the verb into a noun.","exampleCN":"这个词尾把动词变成名词。"},{"word":"borrowing","structure":"borrow + -ing","meaning":"the act of taking on loan","meaningCN":"借入的行为","example":"Borrowing funded the new line.","exampleCN":"借贷为这条新生产线提供了资金。"},{"word":"borrowings","structure":"borrowing + -s (plural)","meaning":"the sums owed","meaningCN":"欠款总额","example":"Borrowings appear on the balance sheet.","exampleCN":"借款额列在资产负债表上。"},{"word":"borrower","structure":"borrow + -er (person who)","meaning":"one who takes a loan","meaningCN":"借入的人","example":"The borrower repaid in full.","exampleCN":"借款人全额偿还。"},{"word":"borrowed","structure":"borrow + -ed (past participle)","meaning":"taken temporarily; adopted","meaningCN":"被借入的；被吸收的","example":"The borrowed tune became a hit.","exampleCN":"这首借来的曲子成了热门。"},{"word":"borrowable","structure":"borrow + -able (can be)","meaning":"able to be borrowed","meaningCN":"可借入的","example":"Only borrowable items leave the desk.","exampleCN":"只有可外借的物品才离开服务台。"},{"word":"lending","structure":"lend + -ing (the mirror act)","meaning":"the act of giving on loan","meaningCN":"出借的行为","example":"Lending and borrowing must balance.","exampleCN":"出借与借入必须平衡。"}],"latinEntries":[]}},{"word":"debt","ipa_uk":"/det/","ipa_us":"/det/","definition_zh":"债务；欠款；负债；人情债；道义上的亏欠","definition_en":"money or another obligation that one person owes to another and is expected to repay","core_image":"账本上一行没有划掉的红字，利息在它旁边又添了新的数字","scene":"账本上那行红字一直没有被划掉，利息又在它旁边添了新的数字。The debt grew faster than the shop could repay it.","sceneCN":"这里 debt 指「债务」（第 1 个义项：欠下并须偿还的钱）；句意为债务增长得比这家小店偿还的速度更快。图中可辨识物件：账本、红字、算盘、到期通知。","pos":[{"tag":"n.","zh":"债务；欠款；人情债（可数或不可数）"}],"collocations":[{"phrase":"pay off a debt","zh":"还清债务"},{"phrase":"fall into debt","zh":"陷入负债"},{"phrase":"national debt","zh":"国家债务"},{"phrase":"a debt of gratitude","zh":"人情债；受恩之感"},{"phrase":"debt relief","zh":"债务减免"},{"phrase":"in debt to someone","zh":"欠某人钱或人情"}],"forms":[{"label":"复数","form":"debts"},{"label":"相关名词（债务人）","form":"debtor"},{"label":"相关名词（债权人）","form":"creditor"},{"label":"相关形容词（负债的）","form":"indebted"},{"label":"相关名词（债券）","form":"debenture"}],"derivatives":[{"word":"debtor","pos":"n.","zh":"债务人；欠款人"},{"word":"indebted","pos":"adj.","zh":"负债的；受恩的"},{"word":"indebtedness","pos":"n.","zh":"负债状态；受恩之感"},{"word":"debenture","pos":"n.","zh":"债券；信用债券"},{"word":"debit","pos":"n./v.","zh":"借方；记入借方"}],"senses":[{"no":"01","title":"Money that must be repaid","titleCN":"须偿还的欠款","definition":"a sum of money owed by one person or organization to another","definitionCN":"一个人或组织欠另一方的款项","example":"The debt grew faster than the shop could repay it.","exampleCN":"债务增长得比这家小店偿还的速度更快。","why":"debt is the thing owed, the residue left when something has been received but not yet paid for.","whyCN":"debt 是被欠之物，是某物已被取得却尚未付清时留下的余数。"},{"no":"02","title":"The state of owing","titleCN":"负债的状态","definition":"the condition of being under an obligation to pay, as in to be in debt","definitionCN":"处于付款义务之下的状态，如处于负债之中","example":"The family has been in debt since the harvest failed.","exampleCN":"收成失败之后，这家人一直负债。","why":"English often names a condition with the same word as the thing that causes it, so debt is both the sum and the state.","whyCN":"英语常用造成某种状况之物来命名该状况，因此 debt 既是金额，也是状态。"},{"no":"03","title":"A particular obligation or instrument","titleCN":"一笔具体债务或债务工具","definition":"a specific liability, such as a bond, a note or an unpaid invoice, treated as one item","definitionCN":"一项具体的偿付义务，如债券、票据或未付账单，被当作一个项目","example":"The firm carries three large debts on its books.","exampleCN":"这家公司的账上有三笔大额债务。","why":"once accounts list obligations one by one, each entry is a countable debt.","whyCN":"当账簿逐项列示义务时，每一条记录就是一笔可数的债务。"},{"no":"04","title":"A debt of gratitude","titleCN":"人情债；受恩之感","definition":"a moral obligation to thank or repay someone for a kindness","definitionCN":"因他人善意而产生的感谢或回报义务","example":"She owes him a debt of gratitude for the introduction.","exampleCN":"她因那次引荐而欠他一份人情。","why":"a favour received is treated as a loan: something was given, and something should come back.","whyCN":"受人之惠被当作一笔借款：有物被给出，便应有物回来。"},{"no":"05","title":"A moral or ethical obligation","titleCN":"道义上的义务","definition":"an obligation to act or to make amends that is not enforceable by money","definitionCN":"须行动或补偿的义务，但不能以金钱强制执行","example":"The reporter felt a debt to the families she had interviewed.","exampleCN":"这位记者觉得自己对那些受访家庭负有责任。","why":"the metaphor of owing extends from money to conscience, where the creditor is other people.","whyCN":"欠债的比喻从金钱扩展到良心，在那里债权人是他人。"},{"no":"06","title":"Borrowing as an aggregate","titleCN":"作为总量的债务","definition":"the total stock of borrowing in a household, a firm or a country, treated as one quantity","definitionCN":"家庭、企业或国家借入的总存量，被当作一个数量","example":"Household debt reached a record share of income.","exampleCN":"家庭债务占收入的比重达到历史高位。","why":"economics needs a mass noun for all obligations together, and debt supplies it.","whyCN":"经济学需要一个总称来指全部义务，debt 正好提供这个不可数用法。"},{"no":"07","title":"Sin pictured as a debt","titleCN":"宗教中把罪看作债务","definition":"in religious language, wrongdoing regarded as an obligation that must be forgiven or paid","definitionCN":"宗教语言中把过错视为须被宽恕或偿付的义务","example":"The prayer asks that debts be forgiven as we forgive others.","exampleCN":"祷词请求宽恕我们的债，如同我们宽恕别人。","why":"the metaphor is old: a wrong creates a claim against the offender, and mercy cancels it.","whyCN":"这个比喻很古老：过错在犯错者身上产生一项债权，而慈悲将其勾销。"},{"no":"08","title":"A return owed in kind","titleCN":"抽象义：须以某种方式回报","definition":"figuratively, something that must be given back to a person, a place or a past that shaped one","definitionCN":"比喻上指必须回报给某人、某地或某个塑造了自己的过去的东西","example":"The novelist acknowledged a debt to the town that raised her.","exampleCN":"这位小说家承认自己欠养育她的那座小镇一份情。","why":"the abstract sense keeps the structure of owing while dropping money: what is owed may be memory, care or work.","whyCN":"抽象义保留欠的结构而舍弃金钱：所欠的可能是记忆、照料或劳动。"}],"etymology":{"intro":{"en":"Debt comes through Old French from Latin debitum, the past participle of debere 'to owe', built on de- and habere 'to have'. Its b was restored in spelling by Latin-loving printers. Dates are approximate.","cn":"debt 经古法语来自拉丁 debitum，即 debere「欠」的过去分词，由 de- 与 habere「有」构成。它的 b 是喜爱拉丁语的印刷者后来补回拼写的。年代均为约数。"},"items":[{"era":"LATIN HABERE","en":"Habere meant 'to have, hold'. With de- 'away from', it produced debere: to have something that is another's, hence to owe.","cn":"habere 意为「有、持有」；加 de-「离开」，构成 debere：持有属于他人之物，因此是欠。"},{"era":"LATIN DEBITUM","en":"The neuter past participle debitum meant 'that which is owed', and it was used both as a noun and in accounting.","cn":"中性过去分词 debitum 意为「被欠之物」，既作名词，也用于记账。"},{"era":"OLD FRENCH DETTE","en":"Old French reduced the word to dette, dropping the b in pronunciation, and Middle English took it in that form.","cn":"古法语把词形缩减为 dette，读音中丢掉了 b，中世纪英语即以这一形式吸收。"},{"era":"RESTORED SPELLING","en":"Sixteenth-century printers reinserted the b to match Latin, producing the modern debt while the pronunciation stayed as det.","cn":"16 世纪的印刷者为对应拉丁语补回 b，形成现代拼写 debt，而读音仍为 det。"},{"era":"DOUBLET WITH DEBIT","en":"Debit was borrowed later directly from Latin debitum, so debt and debit are doublets: one through French, one straight from Latin.","cn":"debit 后来直接从拉丁 debitum 借入，因此 debt 与 debit 是双重借词：一个经法语，一个直取拉丁。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the exact century of the spelling change is not fixed, and the pre-Latin origin of habere is a reconstruction.","cn":"来源不确定（首见年代）：拼写改变的确切世纪没有定论，habere 在拉丁语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to debt; group two holds obligations that differ in kind or in legal force.","cn":"第一组是在字形或读音上与 debt 相近的词；第二组是种类或法律效力不同的义务。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"debit","ipa":"/ˈdebɪt/","tag":"the accounting twin","definition":"From the same Latin debitum, but it names a left-hand ledger entry; debt is the obligation itself.","definitionCN":"同出拉丁 debitum，但指账簿左侧的一笔分录；debt 则是义务本身。"},{"word":"debtor","ipa":"/ˈdebtə(r)/","tag":"the person","definition":"The party who owes; debt is what is owed.","definitionCN":"欠债的一方；debt 是被欠之物。"},{"word":"debenture","ipa":"/dɪˈbentʃə(r)/","tag":"a debt instrument","definition":"A bond-like instrument acknowledging a debt, usually unsecured; it is one kind of debt on paper.","definitionCN":"一种承认债务的债券类工具，通常无担保；它是记在纸上的债务之一。"},{"word":"indebted","ipa":"/ɪnˈdetɪd/","tag":"the adjective","definition":"Owing money, or owing gratitude; the adjective describes a person, while debt is the thing.","definitionCN":"负债的或受恩的；形容词描述人，debt 指物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"liability","ipa":"/laɪˈbɪləti/","tag":"the accounting term","definition":"A legal or accounting obligation to pay; broader than debt because it includes duties not created by borrowing.","definitionCN":"法律或会计上的付款义务；比 debt 更宽，因为它包括并非由借贷产生的义务。"},{"word":"obligation","ipa":"/əˈblɪɡeɪʃn/","tag":"any binding duty","definition":"A duty that binds a person, whether or not money is involved; debt is the money-shaped case.","definitionCN":"约束某人的义务，未必涉及金钱；debt 是其中以金钱为形态的那一种。"},{"word":"arrears","ipa":"/əˈrɪəz/","tag":"overdue debt","definition":"Debt that has not been paid when due; it adds lateness to the idea of owing.","definitionCN":"到期未付的债务；在「欠」之上加了「逾期」。"},{"word":"loan","ipa":"/ləʊn/","tag":"the origin of a debt","definition":"The sum handed over; once received, it becomes a debt on the borrower's side.","definitionCN":"被交出的款项；一经取得，在借款人一侧就变成债务。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"de- 'away' + habere 'have': to have what belongs to another, hence to owe.","cn":"de-「离开」+ habere「有」：持有属于他人之物，因此是欠。"},{"en":"The family runs debt, debtor, indebted, indebtedness, debenture and debit.","cn":"同族包括 debt、debtor、indebted、indebtedness、debenture 与 debit。"},{"en":"Fixed phrases: pay off a debt, fall into debt, national debt, a debt of gratitude.","cn":"固定搭配：还清债务、陷入负债、国家债务、人情债。"},{"en":"The b in debt is silent; it was put back to match Latin and never pronounced.","cn":"debt 中的 b 不发音；它是对应拉丁语补回的，从未被读出。"},{"en":"Debt and debit are doublets from one Latin word, one through French and one direct.","cn":"debt 与 debit 是同一个拉丁词的双重借词，一个经法语，一个直取。"}],"abstract":[{"en":"Picture a red line in a ledger that no eraser can reach.","cn":"想象账簿上一行红字，任何橡皮都擦不到。"},{"en":"Picture a hand receiving a gift with a string tied around the wrist.","cn":"想象一只手接过礼物，手腕上系着一根绳。"},{"en":"Picture a town that raised you holding an invisible invoice.","cn":"想象养育你的那座小镇握着一张看不见的账单。"}]},"examples":[{"en":"The company restructured its debt last year.","cn":"这家公司去年重组了债务。"},{"en":"He fell into debt after the business failed.","cn":"生意失败后他陷入负债。"},{"en":"I owe her a debt of gratitude for the help.","cn":"我欠她一份人情，感谢她的帮助。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「debt 读作 det」——账上欠着、迟早要还的那一笔 → 债务、人情债","word":"debt"},"root":"拉丁 debere「欠」= de-（离开）+ habere「有」；过去分词 debitum「被欠之物」，经古法语 dette 进入英语，16 世纪按拉丁补回 b。debt 与 debit 为同源双重借词。","sensesIntro":{"en":"Eight senses follow one structure: something has been received and not yet returned, and that gap is then counted as money, a state, an instrument, gratitude, conscience, an economy-wide stock, sin and finally a return owed to a place or a past.","cn":"八个义项沿同一个结构展开：某物已被取得却尚未归还，这个缺口再依次被算作金钱、状态、工具、恩情、良心、经济总量、罪，最后是对某地或某个过去的回报。"},"semanticMap":{"core":{"en":"CORE IMAGE: an uncrossed red line in a ledger with interest added beside it.","cn":"核心意象：账簿上一行没有划掉的红字，旁边又添上了利息。"},"chain":["RECEIVE","OWE","REPAY","COUNT THE STOCK","EXTEND TO GRATITUDE","EXTEND TO CONSCIENCE"],"branches":[{"senses":"01 · 02","en":"THE SUM AND THE STATE: what is owed and the condition of owing share one word.","cn":"金额与状态：被欠之物与欠的状态共用一个词。"},{"senses":"03 · 06","en":"ONE ITEM AND THE WHOLE STOCK: accounts count debts singly, economics counts them together.","cn":"单项与总量：会计逐笔数债，经济学把它们合起来数。"},{"senses":"04","en":"GRATITUDE: a favour received creates a claim that money cannot settle.","cn":"恩情：受人之惠产生一项金钱无法结清的债权。"},{"senses":"05 · 07","en":"CONSCIENCE AND SIN: wrongdoing is pictured as a claim held against the offender.","cn":"良心与罪：过错被描绘成对犯错者持有的一项债权。"},{"senses":"08","en":"A RETURN IN KIND: what is owed to a place or a past may be memory, care or work.","cn":"以物回报：欠某地或某个过去的，可能是记忆、照料或劳动。"}]},"affixes":{"intro":{"en":"Debt is a Latin participle reduced by French and then re-Latinised in spelling, so its parts are a prefix, a verb of having, and a participial ending.","cn":"debt 是一个被法语简化、又在拼写上重新拉丁化的拉丁分词，其成分是一个前缀、一个表示「有」的动词与一个分词词尾。"},"latinIntro":{"en":"Latin habere and debere supply the family, with debitum giving both debt and debit, while debtor and debenture grew from the same stock.","cn":"拉丁 habere 与 debere 提供这个词族，debitum 同时给出 debt 与 debit，debtor 与 debenture 也由同一词干生长出来。"},"items":[{"word":"de-","structure":"Latin prefix de- (away from, down)","meaning":"away; down","meaningCN":"离开；向下","example":"The prefix marks having something away from its owner.","exampleCN":"这个前缀标记持有属于他人之物。"},{"word":"habere","structure":"habere, habui, habitum (Latin verb, second conjugation)","meaning":"to have, hold","meaningCN":"有；持有","example":"The root is the plain act of holding.","exampleCN":"这个词根就是持有这一朴素动作。"},{"word":"debere","structure":"de- + habere (to owe)","meaning":"to owe","meaningCN":"欠","example":"To owe is to hold what is another's.","exampleCN":"欠就是持有他人之物。"},{"word":"debitum","structure":"debere + participial ending -itum","meaning":"that which is owed","meaningCN":"被欠之物","example":"The participle became a noun of obligation.","exampleCN":"这个分词变成了表示义务的名词。"},{"word":"debt","structure":"Latin debitum through Old French dette","meaning":"an obligation to pay","meaningCN":"偿付义务","example":"The debt fell due in spring.","exampleCN":"债务在春天到期。"},{"word":"debtor","structure":"debt + -or (person who owes)","meaning":"one who owes","meaningCN":"欠债的人","example":"The debtor asked for more time.","exampleCN":"债务人请求宽限。"},{"word":"indebted","structure":"in- (in a state) + debt + -ed","meaning":"placed under a debt; grateful","meaningCN":"处于负债状态的；受恩的","example":"The family was deeply indebted.","exampleCN":"这家人负债很深。"},{"word":"indebtedness","structure":"indebted + -ness (state)","meaning":"the state of owing","meaningCN":"负债的状态","example":"Indebtedness limited new borrowing.","exampleCN":"负债状态限制了新的借贷。"},{"word":"debenture","structure":"debent- (from Latin debentur, 'they are owed') + -ure","meaning":"a written acknowledgement of debt","meaningCN":"承认债务的书面凭证","example":"The firm issued debentures to raise cash.","exampleCN":"这家公司发行债券以筹资。"},{"word":"debit","structure":"Latin debitum borrowed directly","meaning":"a left-hand ledger entry","meaningCN":"账簿左侧的分录","example":"The clerk entered the sum as a debit.","exampleCN":"职员把这笔金额记为借方。"}],"latinEntries":[{"word":"habere","structure":"habere, habui, habitum (verb, second conjugation)","meaning":"to have, hold","meaningCN":"有；持有"},{"word":"debere","structure":"debere, debui, debitum (verb, second conjugation)","meaning":"to owe","meaningCN":"欠"},{"word":"debitum","structure":"debitum, -i (n., second declension)","meaning":"a debt, that which is owed","meaningCN":"债务；被欠之物"},{"word":"debitor","structure":"debitor, debitoris (m., third declension)","meaning":"one who owes","meaningCN":"欠债者"}]}},{"word":"indebtedness","ipa_uk":"/ɪnˈdetɪdnəs/","ipa_us":"/ɪnˈdetɪdnəs/","definition_zh":"负债状态；负债总额；受恩之情；道义上的亏欠","definition_en":"the state or extent of owing money, or the state of being under an obligation of gratitude","core_image":"年末账房里，先生把各家欠款抄成一页总数，纸角压着一枚镇纸","scene":"年末账房里，先生把各家欠款抄成一页总数，纸角压着一枚镇纸。The family's indebtedness forced them to sell the farm.","sceneCN":"这里 indebtedness 指「负债状态」（第 1 个义项：处于欠债之中的状况）；句意为这家人的负债状态迫使他们卖掉了农场。图中可辨识物件：总账页、镇纸、算盘、封蜡。","pos":[{"tag":"n.","zh":"负债状态；负债总额；受恩之感（不可数）"}],"collocations":[{"phrase":"a burden of indebtedness","zh":"负债的重担"},{"phrase":"household indebtedness","zh":"家庭负债"},{"phrase":"corporate indebtedness","zh":"企业负债"},{"phrase":"a sense of indebtedness","zh":"受恩之感"},{"phrase":"reduce indebtedness","zh":"减少负债"},{"phrase":"indebtedness to a friend","zh":"对朋友的亏欠"}],"forms":[{"label":"复数（少见，指多种负债情形）","form":"indebtednesses"},{"label":"相关形容词（负债的）","form":"indebted"},{"label":"相关名词（债务）","form":"debt"},{"label":"相关名词（债务人）","form":"debtor"},{"label":"相关动词（使负债）","form":"indebt"}],"derivatives":[{"word":"indebted","pos":"adj.","zh":"负债的；受恩的"},{"word":"debt","pos":"n.","zh":"债务"},{"word":"debtor","pos":"n.","zh":"债务人"},{"word":"indebt","pos":"v.","zh":"使负债；使受恩"},{"word":"debit","pos":"n./v.","zh":"借方；记入借方"}],"senses":[{"no":"01","title":"The state of owing money","titleCN":"欠债的状态","definition":"the condition of being under a financial obligation to repay money","definitionCN":"处于须偿还资金的财务义务之下的状况","example":"The family's indebtedness forced them to sell the farm.","exampleCN":"这家人的负债状态迫使他们卖掉了农场。","why":"indebted is the adjective for being placed under a debt, and -ness turns that condition into a noun.","whyCN":"indebted 是「被置于债务之下」的形容词，-ness 把这种状况变成名词。"},{"no":"02","title":"The total amount owed","titleCN":"负债总额","definition":"the aggregate sum a person, firm or country owes at a given time","definitionCN":"个人、企业或国家在某一时点所欠的总额","example":"The report measured the indebtedness of the whole sector.","exampleCN":"这份报告衡量了整个行业的负债总额。","why":"the state noun is also used for the size of the state, because an aggregate is easiest to discuss as a condition.","whyCN":"这个状态名词也用来指状态的规模，因为总量最便于当作一种状况来讨论。"},{"no":"03","title":"An obligation to return a favour","titleCN":"回报恩惠的义务","definition":"the state of being bound to repay a kindness received","definitionCN":"因受人之惠而须回报的状态","example":"Her indebtedness to the mentor shaped every later choice.","exampleCN":"她对恩师的亏欠影响了此后每一个选择。","why":"the metaphor of debt extends to kindness: a favour is received and a return is expected.","whyCN":"债务的比喻扩展到善意：受了恩惠，就有回报的期待。"},{"no":"04","title":"A feeling of gratitude","titleCN":"受恩之感","definition":"the emotion of gratitude that accompanies a favour one cannot easily repay","definitionCN":"因受惠而难以轻易回报所伴随的感激之情","example":"He spoke of his indebtedness with tears in his eyes.","exampleCN":"他谈起自己的受恩之感时眼里含着泪。","why":"indebted came to mean grateful in the seventeenth century, and the noun carried that feeling with it.","whyCN":"indebted 在 17 世纪获得「感激」义，这个名词也带着那份感情。"},{"no":"05","title":"Leverage in economics","titleCN":"经济上的杠杆水平","definition":"the ratio that shows how much of an entity's activity is financed by borrowing","definitionCN":"显示某实体的活动有多少由借入资金支撑的比率","example":"Rising indebtedness made the airline vulnerable to a rate rise.","exampleCN":"杠杆水平上升使这家航空公司在利率上升时变得脆弱。","why":"economics prefers the state noun because it measures a condition rather than a single loan.","whyCN":"经济学偏爱这个状态名词，因为它衡量的是状况而非单笔贷款。"},{"no":"06","title":"Legal liability status","titleCN":"法律上的负债地位","definition":"the position of being legally answerable for a debt, as in a balance sheet","definitionCN":"在法律上对债务负有责任的地位，如资产负债表所列","example":"The audit questioned the indebtedness recorded for the subsidiary.","exampleCN":"审计对子公司账上的负债地位提出疑问。","why":"law and accounting care about who is answerable, so the state of being bound is the relevant fact.","whyCN":"法律与会计关心谁负有责任，因此「被约束的状态」才是相关事实。"},{"no":"07","title":"A bond of service in older usage","titleCN":"旧时受惠而形成的服役束缚","definition":"historically, the condition of being bound to a lord or patron by gifts or favours received","definitionCN":"历史上因受赠或受惠而对领主或赞助人形成的束缚","example":"The old chronicle describes the indebtedness of the tenants to the abbey.","exampleCN":"这部旧编年史记述了佃户对修道院的受惠束缚。","why":"before money credit was common, favours and gifts created lasting ties that were also called debts.","whyCN":"在金钱信贷普及之前，恩惠与赠礼造成持久关系，也被称作欠。"},{"no":"08","title":"Being beholden to an influence","titleCN":"抽象义：受某种影响所困","definition":"figuratively, the state of owing one's ideas or success to a person, a school or an age","definitionCN":"比喻上指自己的思想或成就归功于某人、某学派或某个时代的状态","example":"The painter's indebtedness to the northern masters is plain in every canvas.","exampleCN":"这位画家对北方大师的亏欠在每幅画上都显而易见。","why":"the abstract sense keeps the structure of owing while the creditor becomes an influence rather than a person.","whyCN":"抽象义保留了欠的结构，只是债权人从一个人变成了一种影响。"}],"etymology":{"intro":{"en":"Indebtedness is built inside English from in-, debt, -ed and -ness; debt itself is Latin. The compound may have been helped by Medieval Latin indebitatus. Dates are approximate.","cn":"indebtedness 由英语内部用 in-、debt、-ed、-ness 构成；debt 本身是拉丁词。这个复合形式可能受中世纪拉丁 indebitatus 影响。年代均为约数。"},"items":[{"era":"LATIN DEBITUM","en":"Debitum 'that which is owed' is the base of debt, borrowed through Old French dette with the b later restored in spelling.","cn":"debitum「被欠之物」是 debt 的词基，经古法语 dette 借入，后来在拼写上补回 b。"},{"era":"ENGLISH IN-","en":"The prefix in- here means 'in a state or condition', not 'not': indebted is being placed in debt, not being free of it.","cn":"这里的前缀 in- 意为「处于某种状态」，而非否定：indebted 是陷入债务，不是免于债务。"},{"era":"ENGLISH -ED","en":"The participial ending -ed turns the noun into an adjective meaning 'placed under', giving indebted.","cn":"分词词尾 -ed 把名词变成表示「被置于……之下」的形容词，形成 indebted。"},{"era":"MEDIEVAL LATIN HELP","en":"Medieval Latin indebitatus is generally thought to have supported the English form, though English could have built it independently.","cn":"中世纪拉丁 indebitatus 一般认为支持了英语形式，尽管英语也可能自行构成。"},{"era":"NOUN IN -NESS","en":"The ending -ness is the native suffix for a state, so indebtedness names the condition rather than any single debt.","cn":"词尾 -ness 是本族表示状态的后缀，因此 indebtedness 指状况，而非任何一笔具体的债。"},{"era":"GRATITUDE SENSE","en":"From the seventeenth century indebted also meant grateful, and indebtedness followed, adding a sense no accounting book contains.","cn":"从 17 世纪起，indebted 也指感激，indebtedness 随之获得一层任何账簿都不包含的意思。"}]},"similar":{"note":{"en":"Group one holds forms from the same debt family; group two holds measures and states of owing that differ in scope.","cn":"第一组是同出债务词族的形式；第二组是范围不同的欠债状态与度量。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"indebted","ipa":"/ɪnˈdetɪd/","tag":"the adjective","definition":"The adjective for owing money or gratitude; the noun adds -ness to name the state.","definitionCN":"表示负债或受恩的形容词；名词加 -ness 指这种状态。"},{"word":"debt","ipa":"/det/","tag":"the thing owed","definition":"A specific obligation; indebtedness is the condition of having such obligations.","definitionCN":"具体的偿付义务；indebtedness 是拥有这类义务的状况。"},{"word":"debtor","ipa":"/ˈdebtə(r)/","tag":"the person","definition":"The party who owes; the state noun describes that party's position.","definitionCN":"欠债的一方；状态名词描述这一方的处境。"},{"word":"debit","ipa":"/ˈdebɪt/","tag":"a ledger entry","definition":"A bookkeeping entry on the left side; it is a record of a change, not a state of owing.","definitionCN":"账簿左侧的分录；它记录变动，而非欠债状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"leverage","ipa":"/ˈliːvərɪdʒ/","tag":"the ratio","definition":"The proportion of debt used to finance assets; indebtedness is the raw condition, leverage the measured ratio.","definitionCN":"用债务为资产融资的比例；indebtedness 是原始状态，leverage 是测得的比率。"},{"word":"liabilities","ipa":"/laɪˈbɪlətiz/","tag":"the balance-sheet total","definition":"All amounts a firm must pay, including non-debt items such as provisions; indebtedness usually counts only borrowings.","definitionCN":"企业须支付的全部金额，包括拨备等非债务项；indebtedness 通常只计借入款项。"},{"word":"solvency","ipa":"/ˈsɒlvənsi/","tag":"the opposite condition","definition":"The ability to meet obligations as they fall due; it is the test applied to indebtedness.","definitionCN":"按期履行义务的能力；它是对负债状态所施加的检验。"},{"word":"gratitude","ipa":"/ˈɡrætɪtjuːd/","tag":"the feeling","definition":"Thankfulness for a kindness; indebtedness in its emotional sense is gratitude mixed with a sense of owing.","definitionCN":"对善意的感谢；情感义的 indebtedness 是感激夹杂着亏欠感。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'in a state' + debt + -ed + -ness: the condition of being placed under a debt.","cn":"in-「处于状态」+ debt + -ed + -ness：被置于债务之下的状况。"},{"en":"The family runs debt, debtor, indebted, indebtedness, indebt and debit.","cn":"同族包括 debt、debtor、indebted、indebtedness、indebt 与 debit。"},{"en":"Fixed phrases: household indebtedness, corporate indebtedness, a sense of indebtedness.","cn":"固定搭配：家庭负债、企业负债、受恩之感。"},{"en":"The in- here is not a negative: indebted means in debt, not free of it.","cn":"这里的 in- 不是否定：indebted 意为陷入债务，不是免于债务。"},{"en":"Indebted also means grateful, so indebtedness can name an emotion.","cn":"indebted 也指感激，因此 indebtedness 可以指一种情感。"}],"abstract":[{"en":"Picture a page of totals sealed with wax and never quite closed.","cn":"想象一页总数被蜡封住，却始终没有真正合上。"},{"en":"Picture a gift that leaves a thread tied to the receiver's hand.","cn":"想象一份礼物在接收者手上留下一根线。"},{"en":"Picture a painter carrying an old master's palette everywhere.","cn":"想象一位画家走到哪里都带着一位大师的调色盘。"}]},"examples":[{"en":"Household indebtedness reached its highest level in a decade.","cn":"家庭负债达到十年来的最高水平。"},{"en":"The charity spoke of its indebtedness to local volunteers.","cn":"这家慈善机构谈到它对本地志愿者的亏欠。"},{"en":"High indebtedness left little room for new investment.","cn":"高负债使新投资几乎没有空间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（陷入）+ debt（债）+ ness（状态）」——陷在债里的那种状态 → 负债、受恩","word":"indebtedness"},"root":"英语内部构成：in-（处于某种状态）+ debt（债务，来自拉丁 debitum）+ -ed + -ness。中世纪拉丁 indebitatus 一般认为对形式有支持作用。","sensesIntro":{"en":"Eight senses follow one condition: a person or body is placed under an obligation, and that condition is then measured, extended to kindness, felt as gratitude, read in accounts, tied to old service and finally owed to an influence.","cn":"八个义项沿同一种处境展开：人或机构被置于某项义务之下，这种处境再依次被计量、扩展到恩惠、感受为感激、在账上读取、联系到旧时服役，最后归欠于一种影响。"},"semanticMap":{"core":{"en":"CORE IMAGE: a page of totals pressed under a paperweight, sealed but not settled.","cn":"核心意象：一页总数压在镇纸下，封了蜡却仍未结清。"},"chain":["BE PLACED UNDER","OWE MONEY","TOTAL THE DEBT","OWE A FAVOUR","FEEL GRATITUDE","OWE AN INFLUENCE"],"branches":[{"senses":"01 · 02","en":"THE CONDITION AND ITS SIZE: being in debt and the total owed are two views of one state.","cn":"处境与规模：处于负债与负债总额是同一状态的两种视角。"},{"senses":"03","en":"A FAVOUR OWED: kindness received creates a return obligation.","cn":"欠下的恩惠：受人之惠产生回报义务。"},{"senses":"04","en":"THE FEELING: gratitude is the emotional form of owing.","cn":"感受：感激是「欠」的情感形态。"},{"senses":"05 · 06","en":"MEASURED AND LEGAL: leverage ratios and balance-sheet liability turn the state into a figure.","cn":"计量与法律：杠杆比率与资产负债表负债把状态变成数字。"},{"senses":"07 · 08","en":"OLD BONDS AND NEW MASTERS: service to an abbey and debt to a school of painting share the shape.","cn":"旧束缚与新师承：对修道院的服役与对某画派的亏欠形状相同。"}]},"affixes":{"intro":{"en":"The word stacks an English prefix, a Latin noun, an English participial ending and an English state ending, a clear case of mixed stock.","cn":"这个词叠了一个英语前缀、一个拉丁名词、一个英语分词词尾与一个英语状态词尾，是成分混杂的明显例子。"},"latinIntro":{"en":"Only the noun debt is Latin, from debitum; in-, -ed and -ness are English, so the family mixes a Romance core with Germanic grammar.","cn":"只有名词 debt 是拉丁语，来自 debitum；in-、-ed 与 -ness 都是英语，因此这个词族把罗曼语词核与日耳曼语法混在一起。"},"items":[{"word":"in-","structure":"English prefix in- (into, in a state)","meaning":"into; in the condition of","meaningCN":"进入；处于……状态","example":"The prefix puts the person inside the debt.","exampleCN":"这个前缀把人放进债务之中。"},{"word":"debt","structure":"Latin debitum through Old French dette","meaning":"that which is owed","meaningCN":"被欠之物","example":"Debt is the core of the whole family.","exampleCN":"debt 是整个词族的核心。"},{"word":"-ed","structure":"English participial ending -ed","meaning":"placed under; having","meaningCN":"被置于；具有","example":"The ending makes a state into an adjective.","exampleCN":"这个词尾把状态变成形容词。"},{"word":"-ness","structure":"Old English -nes (state, quality)","meaning":"the state of being","meaningCN":"……的状态","example":"The ending turns the adjective into a noun.","exampleCN":"这个词尾把形容词变成名词。"},{"word":"indebted","structure":"in- + debt + -ed","meaning":"owing money or gratitude","meaningCN":"负债的；受恩的","example":"The family was indebted to the bank.","exampleCN":"这家人欠银行的钱。"},{"word":"indebtedness","structure":"indebted + -ness","meaning":"the state of owing","meaningCN":"负债的状态","example":"Indebtedness rose across the region.","exampleCN":"整个地区的负债上升。"},{"word":"indebt","structure":"in- + debt (verb)","meaning":"to place under a debt","meaningCN":"使负债","example":"The loan indebted the couple for years.","exampleCN":"这笔贷款让这对夫妇多年负债。"},{"word":"debtor","structure":"debt + -or (person who owes)","meaning":"one who owes","meaningCN":"债务人","example":"The debtor negotiated a delay.","exampleCN":"债务人与对方协商延期。"},{"word":"debit","structure":"Latin debitum (direct borrowing)","meaning":"a left-hand entry","meaningCN":"左侧分录","example":"The debit matched the invoice.","exampleCN":"这笔借方分录与账单相符。"}],"latinEntries":[{"word":"debitum","structure":"debitum, -i (n., second declension)","meaning":"that which is owed","meaningCN":"被欠之物"},{"word":"debere","structure":"debere, debui, debitum (verb, second conjugation)","meaning":"to owe","meaningCN":"欠"},{"word":"debitor","structure":"debitor, debitoris (m., third declension)","meaning":"one who owes","meaningCN":"欠债者"}]}},{"word":"creditor","ipa_uk":"/ˈkredɪtə(r)/","ipa_us":"/ˈkredɪtər/","definition_zh":"债权人；放贷方；账面上的应付对象；债权国","definition_en":"a person, firm or country to whom money is owed and who has a claim on the debtor","core_image":"清算桌上，一叠文件依次被盖章，每个印章下面写着一个可以收回的数目","scene":"清算会议上，各方依次在文件上盖章，确认各自可以收回的金额。The creditor refused the offer and demanded full payment.","sceneCN":"这里 creditor 指「债权人」（第 1 个义项：被欠款、对债务人享有请求权的一方）；句意为这名债权人拒绝了方案，要求全额偿付。图中可辨识物件：清算文件、印章、金额栏、编号标签。","pos":[{"tag":"n.","zh":"债权人；放贷方；债权国（可数）"}],"collocations":[{"phrase":"a secured creditor","zh":"有担保的债权人"},{"phrase":"an unsecured creditor","zh":"无担保债权人"},{"phrase":"creditors' meeting","zh":"债权人会议"},{"phrase":"repay creditors","zh":"偿还债权人"},{"phrase":"a foreign creditor","zh":"外国债权人"},{"phrase":"the creditor of record","zh":"登记在册的债权人"}],"forms":[{"label":"复数","form":"creditors"},{"label":"相关名词（信用；贷方）","form":"credit"},{"label":"相关名词（债务）","form":"debt"},{"label":"相关名词（债务人）","form":"debtor"},{"label":"相关形容词（可信的）","form":"credible"}],"derivatives":[{"word":"credit","pos":"n./v.","zh":"信用；贷记；归功"},{"word":"credible","pos":"adj.","zh":"可信的"},{"word":"credibility","pos":"n.","zh":"可信度"},{"word":"credential","pos":"n.","zh":"资历证明；凭证"},{"word":"creditworthy","pos":"adj.","zh":"信用可靠的"}],"senses":[{"no":"01","title":"A person to whom money is owed","titleCN":"被欠款的人","definition":"a person or firm that has a right to receive payment from a debtor","definitionCN":"有权向债务人收取款项的个人或公司","example":"The creditor refused the offer and demanded full payment.","exampleCN":"这名债权人拒绝了方案，要求全额偿付。","why":"creditor is the Latin agent noun of credere 'to trust': the one who trusted another with money and now holds a claim.","whyCN":"creditor 是拉丁 credere「信任」的施事名词：把钱托付给他人信任、如今握有请求权的那一方。"},{"no":"02","title":"A lending institution","titleCN":"放贷机构","definition":"a bank or finance house that holds loans and is owed repayment","definitionCN":"持有贷款、有权要求偿还的银行或金融公司","example":"The bank became the largest creditor in the restructuring.","exampleCN":"这家银行成为重组中最大的债权人。","why":"an institution that lends stands in the same legal position as a private lender, so the same noun applies.","whyCN":"放贷机构与私人出借人处于同一法律地位，因此适用同一个名词。"},{"no":"03","title":"A supplier shown in accounts","titleCN":"账面上的应付对象","definition":"in bookkeeping, a person or firm to whom the business owes money for goods or services, listed among creditors","definitionCN":"记账上企业因货物或服务而欠款、被列入债权人项下的个人或公司","example":"Trade creditors were paid within thirty days.","exampleCN":"贸易债权人于三十天内获得付款。","why":"British accounts call the whole payables side creditors, because every unpaid supplier holds a claim.","whyCN":"英国账务把整个应付一侧称为债权人，因为每个未获付款的供货方都握有请求权。"},{"no":"04","title":"A sovereign creditor","titleCN":"债权国","definition":"a state or international institution that has lent to another government","definitionCN":"向另一国政府放贷的国家或国际机构","example":"Foreign creditors agreed to a longer repayment period.","exampleCN":"外国债权国同意延长偿还期限。","why":"states lend and are owed like banks, so the word scales to the level of a treasury.","whyCN":"国家像银行一样放贷并被欠款，因此这个词可放大到国库层面。"},{"no":"05","title":"A claimant in law","titleCN":"法律上的请求权人","definition":"in insolvency or civil law, a party with a provable claim against another's assets","definitionCN":"在破产或民事法律中，对他方财产享有可证明请求权的一方","example":"The creditor filed a claim before the deadline.","exampleCN":"债权人在截止日前申报了债权。","why":"law needs a neutral name for anyone with a money claim, whether or not a loan created it.","whyCN":"法律需要一个中性名称来指任何拥有金钱请求权的人，无论该请求权是否由借贷产生。"},{"no":"06","title":"One owed gratitude, figuratively","titleCN":"抽象义：被欠恩情的人","definition":"figuratively, a person to whom one owes thanks or recognition","definitionCN":"比喻上指某人欠其感谢或承认的人","example":"The whole school is a creditor of the old gardener's care.","exampleCN":"整个学校都欠这位老园丁一份照料之情。","why":"if a favour is a loan, the one who gave it holds the claim, so a benefactor becomes a creditor.","whyCN":"若恩惠是贷款，给出恩惠者就握有请求权，因此恩人成了债权人。"},{"no":"07","title":"A supplier who grants credit","titleCN":"给予赊账的供货方","definition":"a seller who delivers goods before payment and so holds a claim for the price","definitionCN":"先交货后收款、因而对价款享有请求权的一方","example":"The paper merchant acted as creditor for the whole term.","exampleCN":"这家纸张商在整个学期里充当赊账债权人。","why":"credit sales are loans in kind, and the unpaid seller occupies the creditor's position.","whyCN":"赊销是实物形式的贷款，未获付款的卖方占据债权人的位置。"},{"no":"08","title":"One who trusted money to another, historically","titleCN":"旧时因信任而放贷的人","definition":"historically, a person who entrusted money or goods to another on the strength of trust in repayment","definitionCN":"历史上凭对偿还的信任把钱或货物交给他人的人","example":"The old creditor kept a private book of every promise.","exampleCN":"这位旧时债权人把每一个承诺都记在私人册子上。","why":"the Latin verb behind the word means to trust, so the earliest creditor was simply someone who trusted a borrower.","whyCN":"这个词背后的拉丁动词意为信任，因此最早的债权人就是信任借款人的那个人。"}],"etymology":{"intro":{"en":"Creditor comes straight from Latin creditor, the agent noun of credere 'to trust, entrust'. The word has always carried both trust and money. Dates are approximate.","cn":"creditor 直接来自拉丁 creditor，即 credere「信任、托付」的施事名词。这个词一直同时带着信任与金钱两层意思。年代均为约数。"},"items":[{"era":"LATIN CREDERE","en":"Credere meant 'to trust, believe, entrust'. It is the source of creed, credit, credible and credential as well as creditor.","cn":"credere 意为「信任、相信、托付」，是 creed、credit、credible、credential 以及 creditor 的来源。"},{"era":"DEEPER ORIGIN","en":"The common account of credere as a compound of a word for 'heart' plus dare 'to give', literally 'to give one's heart', is a hypothesis and not an established derivation.","cn":"把 credere 解释为「心」加 dare「给」、字面为「把心交出」的说法只是假说，并非已确立的派生。"},{"era":"LATIN CREDITOR","en":"Creditor was the agent noun for the one who trusted another with money, and it was used in Roman accounts and law.","cn":"creditor 是施事名词，指把钱托付给他人信任的人，用于罗马的账务与法律。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French crediteur carried the word into English in the Middle Ages, first in legal and commercial writing.","cn":"古法语 crediteur 在中世纪把这个词带入英语，最先用于法律与商业文书。"},{"era":"ACCOUNTING SENSE","en":"From the nineteenth century British bookkeeping used creditors for the payables side, giving the word a collective sense.","cn":"从 19 世纪起，英国记账用 creditors 指应付一侧，使这个词有了集合义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the exact first English use is not fixed, and the pre-Latin origin of credere is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：英语中最早用例没有定论，credere 在拉丁语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms from the trust-and-credit stem; group two holds the parties and instruments that surround a claim.","cn":"第一组是同出「信任与信用」词干的形式；第二组是围绕债权存在的各方与工具。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"credit","ipa":"/ˈkredɪt/","tag":"the trust, not the person","definition":"The trust that allows deferred payment, or an entry on the right side of a ledger; not the party.","definitionCN":"允许延期付款的信任，或账簿右侧的分录；不是当事人。"},{"word":"credible","ipa":"/ˈkredəbl/","tag":"worthy of belief","definition":"Believable or convincing; it shares the trust root but says nothing about money.","definitionCN":"可信的、有说服力的；共用信任词根，但与金钱无关。"},{"word":"credential","ipa":"/ˈkredənʃl/","tag":"proof of trust","definition":"A document or qualification that shows one may be trusted in a role.","definitionCN":"证明某人可被信任担任某角色的文件或资历。"},{"word":"creed","ipa":"/kriːd/","tag":"what is believed","definition":"A statement of belief, from the same verb but with no financial sense at all.","definitionCN":"信仰声明，同出这一动词，但完全没有金融义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"debtor","ipa":"/ˈdebtə(r)/","tag":"the opposite party","definition":"The one who owes; creditor and debtor are the two ends of one obligation.","definitionCN":"欠债的一方；债权人与债务人是同一义务的两端。"},{"word":"lender","ipa":"/ˈlendə(r)/","tag":"the one who handed over","definition":"The party who gave the money; every lender becomes a creditor while the loan is unpaid.","definitionCN":"交付款项的一方；贷款未清时每个出借人都是债权人。"},{"word":"bondholder","ipa":"/ˈbɒndhəʊldə(r)/","tag":"a creditor in paper form","definition":"The owner of a bond, which is a tradable claim on the issuer; a creditor by another route.","definitionCN":"债券持有人，债券是对发行人的可转让请求权；以另一条路径成为债权人。"},{"word":"claimant","ipa":"/ˈkleɪmənt/","tag":"one who asserts a claim","definition":"A person who asserts a right, often in court; not all claimants are creditors.","definitionCN":"主张某项权利的人，常在法庭上；并非所有主张者都是债权人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cred- is 'trust': a creditor is the one who trusted another with money.","cn":"cred- 意为「信任」：债权人就是把钱托付给他人信任的人。"},{"en":"The family runs credit, creditor, credible, credibility, credential and creditworthy.","cn":"同族包括 credit、creditor、credible、credibility、credential 与 creditworthy。"},{"en":"Fixed phrases: a secured creditor, an unsecured creditor, a creditors' meeting.","cn":"固定搭配：有担保债权人、无担保债权人、债权人会议。"},{"en":"Creditor and debtor are mirror terms: one is owed, one owes.","cn":"creditor 与 debtor 是一对镜像词：一个被欠，一个欠。"},{"en":"In British accounts the payables side is simply called creditors.","cn":"在英国账务中，应付一侧就径直称为债权人。"}],"abstract":[{"en":"Picture a row of stamps coming down on a page, each marking a claim.","cn":"想象一排印章落在同一页上，每个都标记一项请求权。"},{"en":"Picture a benefactor holding a receipt for a kindness.","cn":"想象一位恩人手里握着一张善意的收据。"},{"en":"Picture trust as the string that turns a giver into a claimant.","cn":"想象信任是那根绳子，把给出者变成请求权人。"}]},"examples":[{"en":"Secured creditors are paid before shareholders.","cn":"有担保债权人先于股东获得偿付。"},{"en":"The country's foreign creditors accepted a write-off.","cn":"该国的外国债权人接受了债务减记。"},{"en":"Every unpaid supplier is a creditor of the firm.","cn":"每个未获付款的供货方都是这家公司的债权人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「credit（信用）+ or（人）」——凭信用把钱借出、等着收回的人 → 债权人","word":"creditor"},"root":"拉丁 creditor「信任而放贷者」，来自 credere「信任、托付」；credere 更深来源不确定，将其解为「心 + 给」仅为假说。英语经古法语 crediteur 借入。","sensesIntro":{"en":"Eight senses follow one position: the party who trusted another with value and now holds a claim, whether a private lender, a bank, a supplier, a state, a litigant, a benefactor or an old moneylender.","cn":"八个义项沿同一个位置展开：把价值托付他人信任、如今握有请求权的一方，可以是私人出借人、银行、供货方、国家、诉讼当事人、恩人，或旧时放债者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of seals on a claims page, each beside a sum to be recovered.","cn":"核心意象：请求权页面上的一排印章，每个印章旁写着一笔待收回的金额。"},"chain":["TRUST","HAND OVER VALUE","HOLD A CLAIM","ENTER THE ACCOUNTS","SCALE TO STATES","EXTEND TO FAVOURS"],"branches":[{"senses":"01 · 08","en":"THE PERSON WHO TRUSTED: the modern claimant and the old trusting lender are the same figure.","cn":"托付信任的人：现代请求权人与旧时凭信任放贷者是同一个人物。"},{"senses":"02","en":"THE INSTITUTION: a bank stands in the same legal position as a private lender.","cn":"机构：银行与私人出借人处于同一法律地位。"},{"senses":"03 · 07","en":"THE ACCOUNTS: unpaid suppliers are creditors whether or not cash was lent.","cn":"账目：未获付款的供货方无论是否借出过现金，都是债权人。"},{"senses":"04 · 05","en":"STATES AND COURTS: a treasury and a litigant both assert a money claim.","cn":"国家与法庭：国库与诉讼当事人都主张一项金钱请求权。"},{"senses":"06","en":"FAVOURS: if kindness is a loan, the benefactor holds the claim.","cn":"恩惠：若善意是贷款，恩人就握有请求权。"}]},"affixes":{"intro":{"en":"Creditor is a Latin agent noun: a verb of trusting plus the ending that marks the one who acts.","cn":"creditor 是一个拉丁施事名词：一个表示信任的动词加上标记行动者的词尾。"},"latinIntro":{"en":"Latin credere and creditum give credit, creditor, credible and credential, so one trust-root runs through the whole family.","cn":"拉丁 credere 与 creditum 衍生 credit、creditor、credible 与 credential，一个「信任」词根贯穿整个词族。"},"items":[{"word":"cred-","structure":"Latin root cred- (trust, believe)","meaning":"trust; belief","meaningCN":"信任；相信","example":"The root runs through credit and creed.","exampleCN":"这个词根贯穿 credit 与 creed。"},{"word":"credere","structure":"credere, credidi, creditum (Latin verb, third conjugation)","meaning":"to trust, entrust","meaningCN":"信任；托付","example":"To lend is to trust with value.","exampleCN":"放贷就是把价值托付他人信任。"},{"word":"-or","structure":"Latin agent ending -or","meaning":"one who does","meaningCN":"做某事的人","example":"The ending marks the party who holds the claim.","exampleCN":"这个词尾标记握有请求权的一方。"},{"word":"creditor","structure":"credere + -or","meaning":"one who trusts another with money","meaningCN":"把钱托付他人信任的人","example":"The creditor demanded payment.","exampleCN":"债权人要求付款。"},{"word":"credit","structure":"Latin creditum (a thing entrusted)","meaning":"trust allowing deferred payment","meaningCN":"允许延期付款的信任","example":"The supplier offered thirty days of credit.","exampleCN":"供货方给予三十天赊账期。"},{"word":"credible","structure":"credere + -ible (can be)","meaning":"able to be believed","meaningCN":"可被相信的","example":"The witness gave a credible account.","exampleCN":"证人提供了可信的叙述。"},{"word":"credibility","structure":"credible + -ity (state)","meaning":"the quality of being believed","meaningCN":"可信的程度","example":"The report damaged the agency's credibility.","exampleCN":"这份报告损害了该机构的可信度。"},{"word":"credential","structure":"credere + -ential (that which proves)","meaning":"evidence that one may be trusted","meaningCN":"证明某人可信的证据","example":"The board checked her credentials.","exampleCN":"董事会核验了她的资历。"},{"word":"creditworthy","structure":"credit + worthy (fit for)","meaning":"fit to be trusted with credit","meaningCN":"值得给予信用的","example":"Only creditworthy borrowers were approved.","exampleCN":"只有信用可靠的借款人才获批准。"}],"latinEntries":[{"word":"credere","structure":"credere, credidi, creditum (verb, third conjugation)","meaning":"to trust, believe, entrust","meaningCN":"信任；相信；托付"},{"word":"creditum","structure":"creditum, -i (n., second declension)","meaning":"a thing entrusted; a loan","meaningCN":"托付之物；贷款"},{"word":"creditor","structure":"creditor, creditoris (m., third declension)","meaning":"one who trusts another with money","meaningCN":"信任而放贷者；债权人"}]}},{"word":"creditworthiness","ipa_uk":"/ˈkredɪtwɜːðinəs/","ipa_us":"/ˈkredɪtwɜːrðinəs/","definition_zh":"信用可靠度；偿债能力；信用评级所衡量的资质","definition_en":"the quality of being considered able and willing to repay money that is lent","core_image":"审贷员把工资单、还款记录与担保材料摊开，在评分表上逐项打勾","scene":"审贷员摊开申请人的工资单与还款记录，在表格上逐项打分。The bank checked the firm's creditworthiness before renewing the loan.","sceneCN":"这里 creditworthiness 指「信用可靠度」（第 1 个义项：被认为有能力且愿意偿还借款的资质）；句意为银行在续贷前核查这家公司的信用可靠度。图中可辨识物件：工资单、还款记录、评分表、钢笔。","pos":[{"tag":"n.","zh":"信用可靠度；偿债能力（不可数）"}],"collocations":[{"phrase":"assess creditworthiness","zh":"评估信用可靠度"},{"phrase":"a borrower's creditworthiness","zh":"借款人的信用可靠度"},{"phrase":"sovereign creditworthiness","zh":"国家信用可靠度"},{"phrase":"a test of creditworthiness","zh":"信用可靠度检验"},{"phrase":"doubt someone's creditworthiness","zh":"怀疑某人的信用"},{"phrase":"creditworthiness standards","zh":"信用可靠度标准"}],"forms":[{"label":"复数","form":"无（不可数名词）"},{"label":"相关形容词（信用可靠的）","form":"creditworthy"},{"label":"反义形容词","form":"uncreditworthy"},{"label":"相关名词（信用）","form":"credit"},{"label":"相关名词（价值；值得）","form":"worth"}],"derivatives":[{"word":"creditworthy","pos":"adj.","zh":"信用可靠的"},{"word":"uncreditworthy","pos":"adj.","zh":"信用不可靠的"},{"word":"credit","pos":"n./v.","zh":"信用；贷记"},{"word":"worthy","pos":"adj.","zh":"值得的；配得上的"},{"word":"worthiness","pos":"n.","zh":"值得的程度"}],"senses":[{"no":"01","title":"Ability and willingness to repay","titleCN":"偿还借款的能力与意愿","definition":"the quality of being judged able and willing to repay a loan","definitionCN":"被判定有能力且愿意偿还贷款的资质","example":"The bank checked the firm's creditworthiness before renewing the loan.","exampleCN":"银行在续贷前核查这家公司的信用可靠度。","why":"credit is trust extended for payment, and worthiness is fitness for that trust, so the word names fitness to be trusted with money.","whyCN":"credit 是为付款而给出的信任，worthiness 是配得上这份信任的资质，因此这个词指「配被托付金钱」的资质。"},{"no":"02","title":"A score or rating","titleCN":"信用评分或评级","definition":"the measured result of an assessment, expressed as a score, grade or rating","definitionCN":"评估所得的量化结果，以分数、等级或评级表示","example":"The agency lowered the country's creditworthiness to a single grade below the top.","exampleCN":"该机构把这个国家的信用评级降到了最高级之下的一档。","why":"once the quality is measured, the measure itself is spoken of as the creditworthiness.","whyCN":"一旦这种资质被计量，计量结果本身也被称作信用可靠度。"},{"no":"03","title":"A borrower's financial standing","titleCN":"借款人的财务信誉","definition":"the overall position of a borrower as shown by income, assets, records and existing debts","definitionCN":"由收入、资产、记录与既有债务显示的借款人整体状况","example":"Lenders weigh income against obligations when judging creditworthiness.","exampleCN":"放贷方在判断信用时权衡收入与既有义务。","why":"the judgement is about a whole financial position, not a single fact, so the noun is a summary.","whyCN":"这一判断针对整体财务状况而非单一事实，因此这个名词是一种概括。"},{"no":"04","title":"A sovereign's standing","titleCN":"国家信用","definition":"the judged ability of a government to service its borrowings","definitionCN":"对政府偿还借款能力的判定","example":"Sovereign creditworthiness affects the cost of every state loan.","exampleCN":"国家信用影响每一笔国家借款的成本。","why":"governments borrow like firms, and lenders apply the same test at a larger scale.","whyCN":"政府像企业一样借款，放贷方在更大尺度上施加同样的检验。"},{"no":"05","title":"A firm's access to credit","titleCN":"企业的融资信用","definition":"the degree to which a company can obtain loans, bonds or trade credit on good terms","definitionCN":"公司在有利条件下获得贷款、债券或赊账的程度","example":"Strong creditworthiness let the company borrow at a lower rate.","exampleCN":"良好的信用可靠度让这家公司以更低的利率借款。","why":"the practical effect of the quality is access: better standing means cheaper money.","whyCN":"这种资质的实际效果就是融资渠道：状况越好，资金越便宜。"},{"no":"06","title":"General reliability in keeping promises","titleCN":"一般意义上的守信度","definition":"the broader reputation for keeping commitments, not limited to money","definitionCN":"不限于金钱、对履行承诺的较广声誉","example":"Her creditworthiness in small matters earned her the post.","exampleCN":"她在小事上的守信让她得到了这个职位。","why":"the money sense is one application of a wider idea: being worth trusting at one's word.","whyCN":"金钱义是更宽概念的一个应用：一个人的话值得被信任。"},{"no":"07","title":"Credibility of an institution or idea","titleCN":"抽象义：机构或观念的可信度","definition":"figuratively, the degree to which an institution, claim or plan can be believed or relied on","definitionCN":"比喻上指某机构、主张或计划可被相信或依靠的程度","example":"The scandal damaged the fund's creditworthiness as a voice on policy.","exampleCN":"这场丑闻损害了该基金在政策发言上的可信度。","why":"the metaphor borrows the financial test and applies it to reputation rather than repayment.","whyCN":"这个比喻借用了金融检验，把它用在声誉而非偿还上。"},{"no":"08","title":"The old quality of being trusted on credit","titleCN":"旧义：凭信用受信的品质","definition":"historically, the personal quality that made a trader acceptable to those who sold on credit","definitionCN":"历史上使商人在赊销者眼中可被接受的个人品质","example":"In the old market, creditworthiness rested on a family's name.","exampleCN":"在旧时市场上，信用可靠度取决于一个家族的名声。","why":"before formal ratings, reputation among traders performed the same function as a score.","whyCN":"在正式评级出现之前，商人间的名声发挥着与分数相同的功能。"}],"etymology":{"intro":{"en":"Creditworthiness is a mixed compound: credit is Latin, worth and its endings are native English. It joins a financial noun to a Germanic idea of value. Dates are approximate.","cn":"creditworthiness 是一个混杂复合词：credit 是拉丁语，worth 及其词尾是英语本族成分。它把一个金融名词接在一个日耳曼语的价值概念上。年代均为约数。"},"items":[{"era":"LATIN CREDITUM","en":"Creditum meant 'a thing entrusted', from credere 'to trust'; English credit kept both the trust and the accounting sense.","cn":"creditum 意为「托付之物」，来自 credere「信任」；英语 credit 同时保留了信任义与记账义。"},{"era":"OLD ENGLISH WEORÞ","en":"Weorþ meant 'value, price, worth', and also 'worthy'; it is the root of worthy, worship and the ending -worthy.","cn":"weorþ 意为「价值、价格、值得」，也指「配得上」；它是 worthy、worship 与词尾 -worthy 的词根。"},{"era":"WORTHY AS A SUFFIX","en":"The form -worthy combines with nouns to mean 'fit or deserving to be treated in that way', as in newsworthy and trustworthy.","cn":"形式 -worthy 与名词结合，表示「配得上以那种方式对待」，如 newsworthy 与 trustworthy。"},{"era":"THE COMPOUND","en":"Creditworthy appears in the nineteenth century as banking spread, and creditworthiness follows as the abstract noun for the quality.","cn":"creditworthy 在 19 世纪随银行业扩展而出现，creditworthiness 随后作为表示该资质的抽象名词产生。"},{"era":"THE SUFFIX -NESS","en":"The ending -ness is the native suffix for a state or quality, so creditworthiness is the quality of being fit for credit.","cn":"词尾 -ness 是本族表示状态或性质的后缀，因此 creditworthiness 就是「配得信用」的性质。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest printed use of the full noun is not fixed, and the pre-Germanic origin of weorþ is a reconstruction.","cn":"来源不确定（首见年代）：这一完整名词的最早印刷用例没有定论，weorþ 在日耳曼语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds words that share the credit or worth stem; group two holds measures of financial health that are often confused with it.","cn":"第一组是共用 credit 或 worth 词干的词；第二组是常与之混淆的财务健康度量。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"creditworthy","ipa":"/ˈkredɪtwɜːði/","tag":"the adjective","definition":"The adjective describing a borrower fit for credit; the noun adds -ness for the quality.","definitionCN":"形容借款人配得信用的形容词；名词加 -ness 表示这种性质。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"the trust itself","definition":"The trust that permits deferred payment; creditworthiness is the fitness to receive it.","definitionCN":"允许延期付款的信任；creditworthiness 是获得这份信任的资质。"},{"word":"credibility","ipa":"/ˌkredəˈbɪləti/","tag":"believability","definition":"The quality of being believed, from the same trust root but with no repayment test.","definitionCN":"被相信的性质，同出信任词根，但不含偿还检验。"},{"word":"creditor","ipa":"/ˈkredɪtə(r)/","tag":"the one who lends","definition":"The party who extends credit; creditworthiness belongs to the party who receives it.","definitionCN":"给予信用的一方；creditworthiness 属于接受信用的一方。"}]},{"heading":"NEAR MEANING","entries":[{"word":"solvency","ipa":"/ˈsɒlvənsi/","tag":"assets over liabilities","definition":"The ability to meet obligations because assets exceed liabilities; creditworthiness also weighs willingness and record.","definitionCN":"因资产超过负债而能履行义务的能力；creditworthiness 还权衡意愿与记录。"},{"word":"credit rating","ipa":"/ˈkredɪt ˈreɪtɪŋ/","tag":"the grade","definition":"A formal grade assigned by an agency; it is one measure of creditworthiness, not the quality itself.","definitionCN":"评级机构给出的正式等级；它是信用可靠度的一种度量，而非资质本身。"},{"word":"trustworthiness","ipa":"/ˈtrʌstwɜːðinəs/","tag":"the general virtue","definition":"Reliability in keeping promises of any kind; creditworthiness narrows this to money.","definitionCN":"履行任何承诺的可靠性；creditworthiness 把它收窄到金钱。"},{"word":"liquidity","ipa":"/lɪˈkwɪdəti/","tag":"cash available now","definition":"The amount of ready cash or easily sold assets; a liquid firm can still be a poor credit risk.","definitionCN":"手头现金或易变现资产的数量；流动性好的公司仍可能是差的信用风险。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"credit is Latin for trust, and -worthy is the native ending for 'fit to be treated so'.","cn":"credit 是拉丁语的信任，-worthy 是本族词尾，表示「配得上被那样对待」。"},{"en":"The family runs credit, creditworthy, uncreditworthy, worth, worthy and worthiness.","cn":"同族包括 credit、creditworthy、uncreditworthy、worth、worthy 与 worthiness。"},{"en":"Fixed phrases: assess creditworthiness, a borrower's creditworthiness, sovereign creditworthiness.","cn":"固定搭配：评估信用可靠度、借款人的信用可靠度、国家信用可靠度。"},{"en":"The word is uncountable: one speaks of the quality, not of several creditworthinesses.","cn":"这个词不可数：说的是这种资质，而不是好几个「信用可靠度」。"},{"en":"Creditworthiness asks two things: can the borrower pay, and will the borrower pay.","cn":"信用可靠度问两件事：借款人能不能还，以及愿不愿意还。"}],"abstract":[{"en":"Picture a score sheet where every fact earns a small tick.","cn":"想象一张评分表，每一项事实都换来一个小勾。"},{"en":"Picture a family name that opens a trader's account without a contract.","cn":"想象一个家族名声，不签合同就能在商人处赊账。"},{"en":"Picture an institution whose word is treated like a currency.","cn":"想象一个机构，它说的话被当作货币使用。"}]},"examples":[{"en":"The loan was refused on grounds of creditworthiness.","cn":"这笔贷款因信用可靠度不足被拒。"},{"en":"A strong record improves creditworthiness over time.","cn":"良好的记录会随时间提高信用可靠度。"},{"en":"Investors questioned the creditworthiness of the issuer.","cn":"投资者质疑发行方的信用可靠度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「credit（信用）+ worthy（配得上）+ ness（性质）」——配得上被给予信用的性质 → 信用可靠度","word":"creditworthiness"},"root":"拉丁 creditum「托付之物」/ credere「信任」+ 古英语 weorþ「价值、值得」+ 本族词尾 -y 与 -ness；creditworthy 为 19 世纪英语复合词，creditworthiness 为其抽象名词。","sensesIntro":{"en":"Eight senses follow one test: whether a party is fit to be trusted with money, and the same noun covers capacity, a score, a borrower's standing, a state's standing, market access, general reliability, institutional credibility and old reputational credit.","cn":"八个义项沿同一项检验展开：一方是否配得被托付金钱，同一个名词涵盖偿还能力、评分、借款人状况、国家状况、融资渠道、一般守信、机构可信度与旧时名声信用。"},"semanticMap":{"core":{"en":"CORE IMAGE: a score sheet filling with ticks beside income, records and guarantees.","cn":"核心意象：一张评分表，收入、记录与担保旁边逐渐打满勾。"},"chain":["TRUST","MEASURE FITNESS","JUDGE REPAYMENT","GRADE THE RISK","EXTEND TO FIRMS","EXTEND TO REPUTE"],"branches":[{"senses":"01","en":"THE CORE TEST: ability plus willingness to repay is what the whole word measures.","cn":"核心检验：偿还能力加偿还意愿，正是整个词所衡量的东西。"},{"senses":"02 · 03","en":"THE SCORE AND THE STANDING: a grade and a borrower's whole position are two forms of the judgement.","cn":"分数与状况：等级与借款人的整体处境是这一判断的两种形态。"},{"senses":"04 · 05","en":"STATES AND FIRMS: the same test scales to a treasury and to a company's access to money.","cn":"国家与企业：同一检验可放大到国库，也可落到公司的融资渠道。"},{"senses":"06","en":"BEYOND MONEY: reliability in small promises is the wider virtue underneath.","cn":"金钱之外：在小事上的守信是底下那个更宽的美德。"},{"senses":"07 · 08","en":"REPUTATION: an institution's credibility and an old family name both work like credit.","cn":"声誉：机构的可信度与旧时家族名声，作用都像信用。"}]},"affixes":{"intro":{"en":"The word mixes a Latin noun of trust with a native English adjective ending and a native noun ending, a small case of language contact inside one word.","cn":"这个词把拉丁语表示信任的名词与英语本族的形容词词尾、名词词尾混在一起，是一个词内部的微型语言接触案例。"},"latinIntro":{"en":"Latin credere and creditum supply credit; the worth half is Germanic, from Old English weorþ, so the two halves have no common ancestry.","cn":"拉丁 credere 与 creditum 提供 credit；worthiness 那一半是日耳曼语，来自古英语 weorþ，因此两半没有共同祖先。"},"items":[{"word":"credit","structure":"Latin creditum (a thing entrusted)","meaning":"trust allowing deferred payment","meaningCN":"允许延期付款的信任","example":"The supplier extended credit for a month.","exampleCN":"供货方给予一个月的信用期。"},{"word":"worth","structure":"Old English weorþ (value, worth)","meaning":"value; deserving","meaningCN":"价值；值得","example":"The estate is worth a fortune.","exampleCN":"这份产业值一大笔钱。"},{"word":"-worthy","structure":"Old English -weorþe (fit for)","meaning":"fit or deserving to be","meaningCN":"配得上；值得被","example":"A trustworthy account is one fit to be trusted.","exampleCN":"可信的叙述就是配得上被相信的叙述。"},{"word":"creditworthy","structure":"credit + -worthy","meaning":"fit to be trusted with credit","meaningCN":"配得信用的","example":"The applicant was deemed creditworthy.","exampleCN":"申请人被认为信用可靠。"},{"word":"uncreditworthy","structure":"un- (not) + creditworthy","meaning":"not fit for credit","meaningCN":"信用不可靠的","example":"The file was marked uncreditworthy.","exampleCN":"这份档案被标记为信用不可靠。"},{"word":"-ness","structure":"Old English -nes (state, quality)","meaning":"the quality of being","meaningCN":"……的性质","example":"The ending turns the adjective into a quality.","exampleCN":"这个词尾把形容词变成一种性质。"},{"word":"worthiness","structure":"worthy + -ness","meaning":"the quality of deserving","meaningCN":"值得的性质","example":"The committee judged his worthiness for the grant.","exampleCN":"委员会评判他是否值得获得这笔资助。"},{"word":"creditworthiness","structure":"creditworthy + -ness","meaning":"fitness to be trusted with credit","meaningCN":"配得信用的资质","example":"Banks test creditworthiness first.","exampleCN":"银行首先检验信用可靠度。"},{"word":"credit rating","structure":"credit + rating (fixed phrase)","meaning":"a formal grade of credit risk","meaningCN":"信用风险的正式等级","example":"The rating fell by one notch.","exampleCN":"评级下调了一档。"}],"latinEntries":[{"word":"credere","structure":"credere, credidi, creditum (verb, third conjugation)","meaning":"to trust, entrust","meaningCN":"信任；托付"},{"word":"creditum","structure":"creditum, -i (n., second declension)","meaning":"a thing entrusted; credit","meaningCN":"托付之物；信用"}]}},{"word":"debit","ipa_uk":"/ˈdebɪt/","ipa_us":"/ˈdebɪt/","definition_zh":"借方；借方分录；记入借方；扣款；借记卡支付","definition_en":"an entry recording money paid out or charged, the left-hand side of a ledger, or to charge an account","core_image":"收银台的小屏幕上跳出一笔扣款，账本左侧多了一行数字","scene":"收银台前，顾客把卡片插入机器，输入密码，屏幕上跳出一笔扣款。The clerk recorded the debit against the customer's account.","sceneCN":"这里 debit 指「借方分录、扣款」（第 1 个义项：记录资金被付出的那一笔账）；句意为职员把这笔扣款记在客户的账户上。图中可辨识物件：刷卡机、密码键盘、屏幕数字、账本左栏。","pos":[{"tag":"n.","zh":"借方；借方分录；扣款（可数）"},{"tag":"v.","zh":"记入借方；从账户扣款"}],"collocations":[{"phrase":"a debit entry","zh":"借方分录"},{"phrase":"debit a customer's account","zh":"从客户账户扣款"},{"phrase":"a debit card","zh":"借记卡"},{"phrase":"debit and credit","zh":"借方与贷方"},{"phrase":"a direct debit","zh":"直接扣款"},{"phrase":"the debit side","zh":"借方一侧"}],"forms":[{"label":"复数","form":"debits"},{"label":"三单（he/she/it）","form":"debits"},{"label":"过去式","form":"debited"},{"label":"过去分词","form":"debited"},{"label":"现在分词","form":"debiting"}],"derivatives":[{"word":"debt","pos":"n.","zh":"债务（同源双重借词）"},{"word":"debtor","pos":"n.","zh":"债务人"},{"word":"debenture","pos":"n.","zh":"债券"},{"word":"debit card","pos":"n.","zh":"借记卡"},{"word":"direct debit","pos":"n.","zh":"直接扣款"}],"senses":[{"no":"01","title":"An entry for money paid out","titleCN":"记录资金付出的分录","definition":"a bookkeeping entry that records money leaving an account or being charged to it","definitionCN":"记录资金离开某账户或被计入其支出的记账条目","example":"The clerk recorded the debit against the customer's account.","exampleCN":"职员把这笔扣款记在客户的账户上。","why":"debit comes from the Latin word for what is owed, and bookkeeping turned it into the entry that records a claim against an account.","whyCN":"debit 来自拉丁语表示「被欠之物」的词，记账把它变成了记录对某账户的债权要求的条目。"},{"no":"02","title":"The left-hand side of a ledger","titleCN":"账簿的借方一侧","definition":"the left side of a double-entry account, where increases in assets and decreases in liabilities are entered","definitionCN":"复式账户的左侧，登记资产增加与负债减少","example":"Every debit on the left must have a credit on the right.","exampleCN":"左侧的每一笔借方都必须在右侧有一笔贷方。","why":"double-entry bookkeeping fixed debit to the left by convention, so the word also names that side of the page.","whyCN":"复式记账按惯例把借方固定在左侧，因此这个词也指页面的那一侧。"},{"no":"03","title":"To charge an account","titleCN":"从账户扣款","definition":"to take a sum out of an account by recording it as an amount owed or paid","definitionCN":"把一笔金额记为应付或已付，从而从账户中扣除","example":"The bank debited the fee at the end of the month.","exampleCN":"银行在月末扣除了这笔手续费。","why":"the noun became a verb meaning to make a debit entry, that is, to place a charge against an account.","whyCN":"名词转成动词，意为做一笔借方分录，也就是对账户施加一笔扣款。"},{"no":"04","title":"The amount charged","titleCN":"被扣除的金额","definition":"the sum recorded in one debit entry","definitionCN":"一笔借方分录所记录的金额","example":"The monthly debit for the gym is small.","exampleCN":"健身房每月扣款金额不大。","why":"as with many action nouns, the entry and the sum it carries are both called a debit.","whyCN":"与许多动作名词一样，分录与它所载的金额都被称为 debit。"},{"no":"05","title":"A debit card payment","titleCN":"借记卡支付","definition":"a payment made by card that takes money directly from a current account","definitionCN":"用卡片直接从活期账户扣钱的支付方式","example":"She paid by debit at the counter.","exampleCN":"她在柜台用借记卡付款。","why":"a debit card is named for the immediate debit it creates, unlike a credit card which lends for a while.","whyCN":"借记卡因即时产生扣款而得名，与先借后还的信用卡相对。"},{"no":"06","title":"An accounting effect","titleCN":"会计上的借方变动","definition":"in accounting, an entry that increases assets or expenses and decreases liabilities or equity","definitionCN":"会计上使资产或费用增加、负债或权益减少的条目","example":"The purchase was a debit to the equipment account.","exampleCN":"这次采购是设备账户的一笔借方。","why":"the left-side rule defines debit by its effect on each class of account, not by whether it feels like a loss.","whyCN":"左侧规则按对各账户类别的影响来定义借方，而不是按它感觉是否像损失。"},{"no":"07","title":"A burden charged against something","titleCN":"抽象义：记在某物账上的负担","definition":"figuratively, something recorded as a disadvantage or cost against a person or plan","definitionCN":"比喻上指被记为某人或某计划的一项不利或代价","example":"The delay was a debit against the project's reputation.","exampleCN":"这次延误是记在项目声誉上的一笔负账。","why":"the ledger metaphor lets any cost or fault be entered on the debit side of a reputation.","whyCN":"账簿比喻让任何代价或过失都能被记入声誉的借方。"},{"no":"08","title":"A thing owed, in older use","titleCN":"旧义：被欠之物","definition":"historically, a debt or an amount owed, before the word became specialised in bookkeeping","definitionCN":"历史上指债务或所欠金额，在词义专门化为记账术语之前","example":"The old ledger lists each debit beside the name of its owner.","exampleCN":"那本旧账簿把每一笔欠款列在债主名字旁边。","why":"the accounting sense grew out of the older sense of an amount owed, which survives in the wording of old accounts.","whyCN":"记账义由「所欠金额」的旧义生长而来，旧式账目用语中仍可见其痕迹。"}],"etymology":{"intro":{"en":"Debit is Latin debitum borrowed directly into English, while debt is the same Latin word filtered through French. They are doublets. Dates are approximate.","cn":"debit 是直接借入英语的拉丁 debitum，而 debt 是同一个拉丁词经法语过滤后的形式。二者是双重借词。年代均为约数。"},"items":[{"era":"LATIN DEBERE","en":"Debere 'to owe' was built on de- 'away from' plus habere 'to have': to have what belongs to another.","cn":"debere「欠」由 de-「离开」加 habere「有」构成：持有属于他人之物。"},{"era":"LATIN DEBITUM","en":"Its neuter past participle debitum meant 'that which is owed' and served as a noun in accounts and law.","cn":"其中性过去分词 debitum 意为「被欠之物」，在账务与法律中作名词使用。"},{"era":"TWO ROUTES","en":"Debt came through Old French dette, losing and later restoring the b; debit was taken straight from Latin in the fifteenth century, keeping the b.","cn":"debt 经古法语 dette 而来，b 先丢失后又被补回；debit 于 15 世纪直接从拉丁语借入，保留了 b。"},{"era":"DOUBLE-ENTRY","en":"As double-entry bookkeeping spread, debit was fixed to the left side of an account, and credit to the right.","cn":"随着复式记账普及，debit 被固定在账户左侧，credit 在右侧。"},{"era":"CARD SENSE","en":"In the late twentieth century the debit card took the name because it debits an account at once rather than lending.","cn":"20 世纪后期，借记卡取用这个名字，因为它即刻扣减账户，而非提供借款。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact date of the accounting sense is not settled, and the pre-Latin origin of habere is a reconstruction.","cn":"来源不确定（首见年代）：会计义的确切年代没有定论，habere 在拉丁语之前的来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms from the same Latin word or close in shape; group two holds accounting and money-movement terms that are easily mixed with debit.","cn":"第一组是同出那个拉丁词或字形相近的形式；第二组是易与 debit 混淆的记账与资金流词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"debt","ipa":"/det/","tag":"the doublet","definition":"The same Latin source through French; debt is the obligation, debit is the ledger entry that records it.","definitionCN":"同一拉丁来源经法语而来；debt 是义务，debit 是记录它的分录。"},{"word":"debtor","ipa":"/ˈdebtə(r)/","tag":"the person","definition":"The party who owes; debit is an accounting entry, not a person.","definitionCN":"欠债的一方；debit 是会计条目，不是人。"},{"word":"debenture","ipa":"/dɪˈbentʃə(r)/","tag":"a debt instrument","definition":"A written acknowledgement of a debt; it looks close but names a security, not an entry.","definitionCN":"承认债务的书面凭证；字形相近，但指证券而非分录。"},{"word":"debit card","ipa":"/ˈdebɪt kɑːd/","tag":"the fixed phrase","definition":"A card that debits a current account at once; the word debit alone does not mean the card.","definitionCN":"即时扣减活期账户的卡；单说 debit 并不指这张卡。"}]},{"heading":"NEAR MEANING","entries":[{"word":"credit","ipa":"/ˈkredɪt/","tag":"the opposite side","definition":"The right-hand entry in double-entry bookkeeping, and also the trust that allows deferred payment.","definitionCN":"复式记账中右侧的条目，也指允许延期付款的信任。"},{"word":"charge","ipa":"/tʃɑːdʒ/","tag":"the everyday verb","definition":"To ask for payment or put a cost on an account; debit is its bookkeeping counterpart.","definitionCN":"要求付款或把费用记在某账上；debit 是它的记账对应词。"},{"word":"withdrawal","ipa":"/wɪðˈdrɔːəl/","tag":"money taken out","definition":"Cash removed by the customer; a debit is the record of it, and also covers card payments.","definitionCN":"客户取出的现金；debit 是它的记录，也涵盖刷卡支付。"},{"word":"entry","ipa":"/ˈentri/","tag":"one line in the book","definition":"Any single written item in a ledger; a debit is one kind of entry.","definitionCN":"账簿中任何单独一条书写项；debit 是其中一种条目。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"de- 'away' + habere 'have': what is owed has gone away from its owner, and the entry records the gap.","cn":"de-「离开」+ habere「有」：被欠之物离开了主人，分录记录这个缺口。"},{"en":"The family runs debit, debt, debtor, debenture, debit card and direct debit.","cn":"同族包括 debit、debt、debtor、debenture、debit card 与 direct debit。"},{"en":"Fixed phrases: a debit entry, the debit side, debit and credit, a direct debit.","cn":"固定搭配：借方分录、借方一侧、借贷双方、直接扣款。"},{"en":"In double entry, debit is simply the left side; it is not a synonym for loss.","cn":"在复式记账中，debit 就是左侧，并非「损失」的同义词。"},{"en":"Debit and debt come from one Latin word by two different routes.","cn":"debit 与 debt 经由两条不同路径来自同一个拉丁词。"}],"abstract":[{"en":"Picture a left-hand column that never quite balances with the right.","cn":"想象左侧一栏与右侧始终差一点才配平。"},{"en":"Picture a card that takes coins out of a pocket the moment it is swiped.","cn":"想象一张卡，一刷就从口袋里拿走硬币。"},{"en":"Picture a reputation with a debit column of its own.","cn":"想象一份声誉也有自己的借方栏。"}]},"examples":[{"en":"The bank debited the account for the annual fee.","cn":"银行为年费从该账户扣款。"},{"en":"Debits and credits must balance at the end of the day.","cn":"日终时借贷双方必须配平。"},{"en":"He paid with a debit card rather than a credit card.","cn":"他用借记卡而不是信用卡付款。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「debit 读作 deb-it」——账本左边记下付出的一笔 → 借方、扣款","word":"debit"},"root":"拉丁 debere「欠」= de-（离开）+ habere「有」，过去分词 debitum「被欠之物」直接借入英语；与经古法语而来的 debt 为同源双重借词。","sensesIntro":{"en":"Eight senses follow one entry: a value is recorded as taken away, and the same word covers the line in the book, the left side, the act of charging, the amount, a card payment, the accounting effect, a figurative cost and the old sense of a sum owed.","cn":"八个义项沿同一条分录展开：一笔价值被记为被取走，同一个词涵盖簿中那一行、左侧、扣款动作、金额、刷卡支付、会计影响、比喻代价，以及旧时「所欠金额」义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new line on the left of a ledger and a matching deduction on a small screen.","cn":"核心意象：账簿左侧新添一行，小屏幕上同时出现一笔扣减。"},"chain":["OWE","RECORD THE GAP","FIX THE LEFT SIDE","CHARGE THE ACCOUNT","MOVE MONEY AT ONCE","COUNT A COST"],"branches":[{"senses":"01 · 08","en":"THE ENTRY AND THE OLD DEBT: the line in the book grew out of the older sense of a sum owed.","cn":"分录与旧债：簿中那一行由更早的「所欠金额」义生长而来。"},{"senses":"02 · 06","en":"THE LEFT SIDE: convention and accounting effect define debit by position and by class of account.","cn":"左侧：惯例与会计影响按位置和账户类别定义借方。"},{"senses":"03 · 04","en":"THE CHARGE AND ITS AMOUNT: the act of charging and the sum charged share one noun.","cn":"扣款与金额：扣款动作与所扣金额共用一个名词。"},{"senses":"05","en":"THE CARD: a debit card is named for the immediate deduction it creates.","cn":"卡片：借记卡因它造成的即时扣减而得名。"},{"senses":"07","en":"A COST ON A REPUTATION: the ledger metaphor charges any fault to a person or a plan.","cn":"声誉上的代价：账簿比喻把任何过失记到某人或某计划账上。"}]},"affixes":{"intro":{"en":"Debit is a Latin participle borrowed whole, so its parts are a prefix, a verb of having and a participial ending, with no English ending added.","cn":"debit 是整词借入的拉丁分词，其成分是一个前缀、一个表示「有」的动词与一个分词词尾，没有再加英语词尾。"},"latinIntro":{"en":"Latin habere and debere give debit, debt and debtor, while debitum supplies both the English accounting term and its French-filtered doublet.","cn":"拉丁 habere 与 debere 衍生 debit、debt 与 debtor，debitum 同时提供英语会计术语与它经法语过滤的双重形式。"},"items":[{"word":"de-","structure":"Latin prefix de- (away from, down)","meaning":"away; down","meaningCN":"离开；向下","example":"The prefix marks value going away from its owner.","exampleCN":"这个前缀标记价值离开主人。"},{"word":"habere","structure":"habere, habui, habitum (Latin verb, second conjugation)","meaning":"to have, hold","meaningCN":"有；持有","example":"The root is the act of holding.","exampleCN":"这个词根是持有的动作。"},{"word":"debere","structure":"de- + habere (to owe)","meaning":"to owe","meaningCN":"欠","example":"To owe is to hold another's property.","exampleCN":"欠就是持有他人财物。"},{"word":"debitum","structure":"debere + participial ending -itum","meaning":"that which is owed","meaningCN":"被欠之物","example":"The participle became the accounting noun.","exampleCN":"这个分词成了会计名词。"},{"word":"debit","structure":"Latin debitum borrowed directly","meaning":"a charge recorded on the left","meaningCN":"记在左侧的扣项","example":"Each debit needs a matching credit.","exampleCN":"每一笔借方都需要对应的贷方。"},{"word":"debited","structure":"debit + -ed (past participle)","meaning":"charged to an account","meaningCN":"已从账户扣除","example":"The fee was debited at noon.","exampleCN":"手续费在中午被扣除。"},{"word":"debiting","structure":"debit + -ing (present participle)","meaning":"the act of charging","meaningCN":"正在扣款","example":"Debiting the account early avoids late fees.","exampleCN":"提前扣款可避免滞纳金。"},{"word":"debit card","structure":"debit + card (fixed phrase)","meaning":"a card that deducts at once","meaningCN":"即时扣款的卡","example":"The debit card works without a credit line.","exampleCN":"借记卡无需信用额度即可使用。"},{"word":"debt","structure":"Latin debitum through Old French","meaning":"the obligation itself","meaningCN":"义务本身","example":"Debt is the doublet of debit.","exampleCN":"debt 是 debit 的同源双重形式。"}],"latinEntries":[{"word":"habere","structure":"habere, habui, habitum (verb, second conjugation)","meaning":"to have, hold","meaningCN":"有；持有"},{"word":"debere","structure":"debere, debui, debitum (verb, second conjugation)","meaning":"to owe","meaningCN":"欠"},{"word":"debitum","structure":"debitum, -i (n., second declension)","meaning":"that which is owed","meaningCN":"被欠之物"},{"word":"debitor","structure":"debitor, debitoris (m., third declension)","meaning":"one who owes","meaningCN":"欠债者"}]}}]);
